    "q.l13#4.e" to "輕度 AMS 的首選是停止上升、給身體適應時間。止痛藥可以緩解頭痛，但不改變適應程序。若休息後症狀持續或加重，下撤才是確定性的治療。",
    "q.l13#5.p" to "「爬高睡低」為什麼能提高適應效率？",
