    "q.l13#5.o2" to "因為可以少背裝備",
    "q.l13#5.o3" to "因為夜間行進更安全",
    "q.l13#5.e" to "適應依賴低氧刺激，但睡眠質量同樣是適應的必要條件——夜間嚴重低氧會加重週期性呼吸與症狀。爬高睡低把這兩件事調和在一起，因此效率高於一直停在高處。",
    "q.l13#6.p" to "出現 AMS 後仍然繼續上升，最嚴重的後果可能是什麼？",
    "q.l13#6.o0" to "只是感覺更累一點",
    "q.l13#6.o1" to "進展為 HACE 或 HAPE，可能在數小時內危及生命",
    "q.l13#6.o2" to "食慾下降",
    "q.l13#6.o3" to "睡眠質量變差",
    "q.l13#6.e" to "AMS 本身通常在休息或下降後緩解，但它可能成為危重病症的前驅。這也正是「出現症狀不上升」被反覆強調的原因——它阻斷的是整條惡化鏈條的起點。",
    "q.l13#7.p" to "判斷 AMS 是否在惡化，最應該關注什麼？",
    "q.l13#7.o0" to "頭痛是否消失",
    "q.l13#7.o1" to "症狀是否進行性加重，尤其是意識、步態與呼吸的變化",
    "q.l13#7.o2" to "體溫是否正常",
    "q.l13#7.o3" to "血氧讀數是否上升",
    "q.l13#7.e" to "從 AMS 轉向 HACE/HAPE 的關鍵轉折體現在意識、步態與呼吸三個維度上。緊盯這三個維度，比盯著單一症狀或某個血氧讀數更可靠。",
    "q.l13#8.p" to "AMS 的頭痛通常有什麼特點？",
