    "q.l13#8.o3" to "通常是最後一個出現的症狀",
    "q.l13#8.e" to "頭痛往往是 AMS 最先出現的訊號，也是 Lake Louise 標準裡的必備條件。正因為它「很常見」，反而容易被當作普通疲勞頭痛而忽略——所以判斷的關鍵是「在海拔上升後出現」這個背景。",
    "q.l13#9.p" to "乙醯唑胺用於預防高山症時，教材推薦的用法是？",
    "q.l13#9.o0" to "每日 3 次，每次 250 毫克",
