    "q.l13#10.o2" to "因為藥物會失效",
    "q.l13#10.o3" to "因為藥物需要持續加量",
    "q.l13#10.e" to "這是高山症處置中最關鍵的一條認知：症狀是警報，不是病本身。藥物把警報關掉，但低氧造成的生理壓力仍在累積——在藥物掩護下繼續上升，等於在無聲狀態下讓病情向前推進。",
    "q.l13#11.p" to "【多選】下列哪些情況容易與 AMS 混淆，需要仔細鑑別？",
