    "q.l15#0.o2" to "越快越好",
    "q.l15#0.o3" to "沒有限制",
    "q.l15#0.e" to "把睡眠海拔的日升幅限制在 500 公尺以內，並每升高約 1,000 公尺安排休息日，是國際指南中反覆出現的基礎建議。它給身體留出產生代償的時間。（不同資料給出的建議值在 300–700 公尺之間；本課程採用其中較通行的一組。）",
    "q.l15#1.p" to "「爬高睡低」的含義是？",
    "q.l15#1.o0" to "白天上升到更高海拔活動，夜間返回較低海拔睡眠",
    "q.l15#1.o1" to "白天休息，夜間趕路",
    "q.l15#1.o2" to "一直待在同一海拔",
    "q.l15#1.o3" to "只在最高處睡覺",
    "q.l15#1.e" to "白天的高海拔暴露能刺激紅細胞生成與呼吸調節等適應機制，而夜間回到較低海拔睡眠可減輕症狀、改善睡眠質量，兩者結合是效率最高的適應方式。",
    "q.l15#2.p" to "下列哪項行為會加重高原適應的負擔？",
    "q.l15#2.o0" to "充分飲水",
    "q.l15#2.o1" to "攝入酒精或服用鎮靜類藥物",
    "q.l15#2.o2" to "以碳水化合物為主食",
    "q.l15#2.o3" to "保證睡眠",
    "q.l15#2.e" to "酒精與鎮靜劑會抑制呼吸驅動，尤其會加重夜間週期性呼吸與低氧，顯著抬高患病風險。在高海拔，睡眠呼吸質量本身就是適應的一部分。",
    "q.l15#3.p" to "使用脈搏血氧儀監測血氧的意義是？",
    "q.l15#3.o0" to "可以完全替代症狀判斷",
    "q.l15#3.o1" to "提供客觀參考，尤其對既往有高山症史的人",
    "q.l15#3.o2" to "只是為了留下記錄",
    "q.l15#3.o3" to "沒有任何實際意義",
    "q.l15#3.e" to "血氧是有用的參考，但個體差異大，不能單獨作為決策依據。症狀與功能狀態（能否走直線、能否正常活動）始終是第一判據。",
    "q.l15#4.p" to "用於 HAPE 高危人群預防的藥物，醫生可能考慮？",
    "q.l15#4.o0" to "硝苯地平或西地那非（磷酸二酯酶抑制劑）",
    "q.l15#4.o1" to "廣譜抗生素",
    "q.l15#4.o2" to "普通止痛藥",
    "q.l15#4.o3" to "維生素補充劑",
    "q.l15#4.e" to "這兩類藥物可降低肺動脈壓，用於 HAPE 高危人群的預防，須由醫生評估後使用。它們的作用環節與乙醯唑胺不同，不能互相替代。",
    "q.l15#5.p" to "為什麼「上升太快」是高山症最強的風險因素之一？",
    "q.l15#5.o0" to "因為走得太累",
    "q.l15#5.o1" to "身體來不及產生呼吸調節、紅細胞增加等代償",
    "q.l15#5.o2" to "因為負重更多",
    "q.l15#5.o3" to "因為山區天氣變化快",
    "q.l15#5.e" to "適應是一系列生理代償的累積過程，需要以「天」為單位的時間。上升速度超過代償速度，就會以症狀形式表現出來——這就是所有上升速率建議的由來。",
    "q.l15#6.p" to "充足飲水對高原適應的作用是？",
    "q.l15#6.o0" to "只是為了解渴",
    "q.l15#6.o1" to "維持迴圈與代謝，脫水會明顯加重症狀",
    "q.l15#6.o2" to "可以預防肺水腫",
    "q.l15#6.o3" to "可以替代預防藥物",
    "q.l15#6.e" to "高海拔的乾燥空氣與加快的呼吸會顯著增加水分流失，脫水會使血液黏稠、加重缺氧感與頭痛。但也要避免過度補水，保持均勻充足的飲水即可。",
    "q.l15#7.p" to "為什麼在高海拔要避免過度勞累？",
    "q.l15#7.o0" to "因為會很快累",
    "q.l15#7.o1" to "過度勞累可誘發 HAPE，尤其在尚未適應時",
    "q.l15#7.o2" to "因為會導致脫水",
    "q.l15#7.o3" to "因為會拖慢隊伍進度",
    "q.l15#7.e" to "劇烈運動會讓肺動脈壓進一步升高，在尚未適應的人群中是 HAPE 的明確誘因之一。控制行進節奏不只是為了省力，也是降低發病風險的手段。",
    "q.l15#8.p" to "乙醯唑胺應該在什麼時候開始服用、什麼時候停藥？",
    "q.l15#8.o0" to "到達高海拔後開始，適應後停藥",
    "q.l15#8.o1" to "海拔上升前 1 天左右開始，上升後 2 天左右停藥",
    "q.l15#8.o2" to "整個行程都要持續服用",
    "q.l15#8.o3" to "只在出現症狀時服用",
    "q.l15#8.e" to "提前一天開始是為了讓藥物在上升時就已起效；上升後兩天左右停藥，是因為此時身體已開始自行適應。乙醯唑胺的作用是「提高適應速度」，不是替代適應過程。",
    "q.l15#9.p" to "停止服用乙醯唑胺會不會導致症狀反彈？",
    "q.l15#9.o0" to "會，必須逐漸減量",
    "q.l15#9.o1" to "不會，只會讓適應速度恢復正常值",
    "q.l15#9.o2" to "會，症狀會加倍出現",
    "q.l15#9.o3" to "取決於海拔",
    "q.l15#9.e" to "教材明確說停藥不會導致症狀反彈，只是適應速度回到正常水平。這一點很重要——它說明藥物並沒有「壓制」什麼，只是把適應過程加快了一段時間。",
    "q.l15#10.p" to "阿司匹林用於緩解高山反應頭痛的用法是？",
    "q.l15#10.o0" to "出現頭痛後一次服用 500 毫克",
    "q.l15#10.o1" to "海拔上升前 1 天開始，每日 3 次、每次 320 毫克，直至適應過程結束",
    "q.l15#10.o2" to "每日 1 次、每次 100 毫克",
    "q.l15#10.o3" to "只在睡前服用",
    "q.l15#10.e" to "這是「預防性使用」而非「痛了才吃」：提前開始、規律服用，直到適應過程結束。需要注意阿司匹林有胃腸道與出血風險，屬於藥物決策，應由醫生評估。",
    "q.l15#11.p" to "關於銀杏提取物預防高山反應，正確的認識是？",
    "q.l15#11.o0" to "效果優於乙醯唑胺，可以替代",
    "q.l15#11.o1" to "有一定預防作用，但對照實驗顯示療效遠不如乙醯唑胺",
    "q.l15#11.o2" to "完全無效",
    "q.l15#11.o3" to "只對腦水腫有效",
    "q.l15#11.e" to "教材的態度很謹慎：有實驗顯示可以緩解症狀，但不同實驗的劑量與條件差異較大，無法準確定量；而與乙醯唑胺的對照實驗顯示前者療效遠不如後者。同時還要注意它與抗凝血藥的相互作用。",
    // ---------- q.l16 ----------
    "q.l16#0.p" to "「顫抖停止」意味著什麼？",
    "q.l16#0.o0" to "身體已經適應寒冷",
    "q.l16#0.o1" to "失溫正在加重，是危險訊號",
    "q.l16#0.o2" to "可以繼續前進",
    "q.l16#0.o3" to "需要立刻喝水",
    "q.l16#0.e" to "顫抖是身體產熱的最後手段。當顫抖停止，說明產熱機制已經衰竭，體溫正在加速下降——這是從輕度轉向中度/重度的關鍵分界，必須立即處置。",
    "q.l16#1.p" to "凍傷的現場復溫方法正確的是？",
    "q.l16#1.o0" to "用雪反覆揉搓患處",
    "q.l16#1.o1" to "用 37–40℃ 溫水浸泡約 30 分鐘，直到皮膚變紅變軟",
    "q.l16#1.o2" to "用火堆烤熱",
    "q.l16#1.o3" to "用熱水袋直接敷",
    "q.l16#1.e" to "凍傷組織內部已形成冰晶，機械揉搓會造成細胞二次損傷；高溫會燙傷失去感覺的皮膚。只有溫水快速復溫是標準做法，可直接用未受傷的手/腋下做應急復溫。",
    "q.l16#2.p" to "什麼情況下不應該在現場復溫凍傷？",
    "q.l16#2.o0" to "只要凍傷就必須復溫",
    "q.l16#2.o1" to "存在再次凍結風險時，復溫後再度凍結的損傷更嚴重",
    "q.l16#2.o2" to "白天不能復溫",
    "q.l16#2.o3" to "只有輕度凍傷才復溫",
    "q.l16#2.e" to "復溫—再凍結的迴圈會造成遠比持續凍傷更嚴重的組織破壞。所以在可能繼續暴露於嚴寒、無法保證持續保暖時，正確做法是保護患處、避免摩擦，儘快下撤到能持續保暖的環境再復溫。",
    "q.l16#3.p" to "中度以上失溫者，為什麼要避免四肢劇烈活動？",
    "q.l16#3.o0" to "因為會消耗體力",
    "q.l16#3.o1" to "因為低溫心肌極易被誘發心律失常",
    "q.l16#3.o2" to "因為會讓患者煩躁",
    "q.l16#3.o3" to "因為會加重凍傷",
    "q.l16#3.e" to "這是失溫急救中最反直覺的一點：讓患者自己走動常常是致命的。低溫狀態下心肌應激性極高，突然的肢體活動或粗暴搬動可能直接觸發心室顫動。",
    "q.l16#4.p" to "凍傷復溫時，正確的水溫是？",
    "q.l16#4.o0" to "0–5℃",
    "q.l16#4.o1" to "20–25℃",
    "q.l16#4.o2" to "37–40℃",
    "q.l16#4.o3" to "60℃ 以上",
    "q.l16#4.e" to "水溫過低無法有效復溫，過高會燙傷已經失去感覺的皮膚。37–40℃ 是既能快速融化冰晶、又不會造成熱損傷的區間。復溫過程會劇烈疼痛，需要止痛處理。",
    "q.l16#5.p" to "失溫急救時，為什麼優先復溫軀幹而不是四肢？",
    "q.l16#5.o0" to "因為四肢不重要",
    "q.l16#5.o1" to "四肢復溫會使外周冷血迴流核心，進一步降低核心體溫",
    "q.l16#5.o2" to "因為軀幹更容易操作",
    "q.l16#5.o3" to "因為四肢可能已經凍傷",
    "q.l16#5.e" to "這是失溫處置中最關鍵的原則之一。先處理四肢會推動外周冷血迴流到核心，可能讓核心體溫進一步下降並誘發心律失常——因此核心優先、四肢其次。",
    "q.l16#6.p" to "輕度失溫的現場處置是？",
    "q.l16#6.o0" to "立刻送醫院",
    "q.l16#6.o1" to "脫離風寒、更換溼衣、補充熱量，並持續觀察是否惡化",
    "q.l16#6.o2" to "讓他繼續行進以產生熱量",
    "q.l16#6.o3" to "用雪搓身體促進迴圈",
    "q.l16#6.e" to "輕度失溫者仍能自主產熱，處理重點是阻斷熱量繼續流失並補充能量。但必須持續觀察——顫抖停止往往是轉向中度失溫的訊號，而不是好轉。",
    "q.l16#7.p" to "凍傷後可以直接用熱水袋熱敷嗎？",
    "q.l16#7.o0" to "可以，越快復溫越好",
    "q.l16#7.o1" to "不可以，失去感覺的皮膚極易被燙傷，只能用 37–40℃ 溫水浸泡",
    "q.l16#7.o2" to "可以，只要包上毛巾",
    "q.l16#7.o3" to "可以，只要溫度不太高",
    "q.l16#7.e" to "凍傷部位的痛覺與溫覺都已受損，無法反饋「太燙了」。直接熱源很容易造成額外燒傷，使原本可能恢復的組織徹底壞死。",
    "q.l16#8.p" to "【多選】失溫急救中，下列哪些做法是錯誤的？",
    "q.l16#8.o0" to "給失溫者飲酒「暖身」",
    "q.l16#8.o1" to "讓重度失溫者自己走動產熱",
    "q.l16#8.o2" to "用力搓揉凍傷的四肢",
    "q.l16#8.o3" to "先復溫四肢再處理軀幹",
    "q.l16#8.o4" to "把患者轉移到避風處並更換溼衣",
    "q.l16#8.e" to "四項全錯，而且錯得各有原因：酒精擴張外周血管反而加速散熱；重度失溫者走動可能誘發心律失常；搓揉會造成凍傷組織的二次損傷；先暖四肢會讓冷血迴流核心、進一步降低核心體溫。",
    "q.l16#9.p" to "失溫急救的核心優先順序是？",
    "q.l16#9.o0" to "先復溫四肢，再復溫軀幹",
    "q.l16#9.o1" to "優先復溫軀幹核心，同時避免粗暴搬動與四肢劇烈活動",
    "q.l16#9.o2" to "先讓患者喝熱水",
    "q.l16#9.o3" to "先脫掉所有衣物",
    "q.l16#9.e" to "核心優先是失溫處置的第一原則：軀幹溫暖了，心臟與大腦才能恢復功能，血液才有能力被送往四肢。順序顛倒會直接造成核心體溫進一步下降。",
    "q.l16#10.p" to "凍傷復溫之後，正確的後續護理是？",
    "q.l16#10.o0" to "刺破水皰以減輕壓力",
    "q.l16#10.o1" to "不要刺破水皰，用無菌敷料鬆散包紮，避免患處承重",
    "q.l16#10.o2" to "用力按摩促進血液迴圈",
    "q.l16#10.o3" to "立即讓患處接觸熱源",
    "q.l16#10.e" to "復溫後的組織非常脆弱：水皰是天然的保護層，刺破會引入感染；按摩會造成機械損傷；熱源則會燙傷已失去感覺的皮膚。正確做法是保護、乾燥、避免承重，並儘快送醫。",
    "q.l16#11.p" to "凍傷可能留下哪些長期後遺症？",
    "q.l16#11.o0" to "通常完全恢復，沒有後遺症",
    "q.l16#11.o1" to "怕冷、感覺異常與出汗異常，可能需要數月甚至更久恢復",
    "q.l16#11.o2" to "只會影響外觀",
    "q.l16#11.o3" to "隻影響運動能力",
    "q.l16#11.e" to "凍傷損傷的是深層組織與神經末梢，即使外觀恢復，怕冷、麻木、刺痛與出汗異常等後遺症也可能長期存在。這一點讓「預防凍傷」比「治好凍傷」重要得多。",
    // ---------- q.l21 ----------
    "q.l21#0.p" to "三層穿著系統中，貼身層的主要職責是？",
    "q.l21#0.o0" to "隔絕風雪",
    "q.l21#0.o1" to "把汗從皮膚帶走，保持乾爽",
    "q.l21#0.o2" to "提供主要保暖",
    "q.l21#0.o3" to "儲存備用物品",
    "q.l21#0.e" to "貼身層的核心是排汗。它緊貼皮膚，如果它保持著潮溼狀態，無論外面穿多少層，熱量都會持續被帶走——這也是為什麼貼身層被稱為「第二層皮膚」。",
    "q.l21#1.p" to "為什麼抓絨在潮溼環境下比羽絨更可靠？",
    "q.l21#1.o0" to "因為抓絨更厚",
    "q.l21#1.o1" to "因為聚酯纖維天然疏水，潮溼時仍能保暖",
    "q.l21#1.o2" to "因為抓絨更便宜",
    "q.l21#1.o3" to "因為羽絨不能穿在裡面",
    "q.l21#1.e" to "抓絨由塑膠（聚酯）纖維構成，本身幾乎不吸水，因此潮溼時依然能留住空氣層保暖。羽絨一旦受潮就會塌縮並失去保暖能力——所以羽絨必須嚴格防潮儲存。",
    "q.l21#2.p" to "用於高海拔極寒環境的羽絨服，蓬鬆度建議是？",
    "q.l21#2.o0" to "500 以下",
    "q.l21#2.o1" to "600 左右",
    "q.l21#2.o2" to "800 蓬鬆度以上",
    "q.l21#2.o3" to "蓬鬆度不重要",
    "q.l21#2.e" to "蓬鬆度越高，同樣重量的羽絨能固定更多空氣，保暖效率越高。800 蓬鬆度以上是高海拔行程的常見建議，同時應選擇帶帽、非合成填料的款式。",
    "q.l21#3.p" to "硬殼衝鋒衣的核心功能是？",
    "q.l21#3.o0" to "提供主要保暖",
    "q.l21#3.o1" to "防水、防風、透氣，同時兼顧頭盔相容性",
    "q.l21#3.o2" to "排汗",
    "q.l21#3.o3" to "增加負重訓練效果",
    "q.l21#3.e" to "硬殼負責抵禦外界的風雨雪，同時把身體產生的溼氣排出去。如果透氣性差，汗氣會在內層凝結，等於自己製造了一個潮溼環境。",
    "q.l21#4.p" to "手套配置中，專門用於操作觸控裝置的是？",
    "q.l21#4.o0" to "薄抓絨手套",
    "q.l21#4.o1" to "防風/防刮手套，選擇觸控靈敏度高的款式",
    "q.l21#4.o2" to "厚保暖嚮導手套",
    "q.l21#4.o3" to "登頂手套",
    "q.l21#4.e" to "高海拔操作手機、GPS 或相機時，需要一副既能防風又有觸控靈敏度的手套。脫手套操作是凍傷最常見的誘因之一——寧可多帶一副專門的手套。",
    "q.l21#5.p" to "關於手腳保暖貼（暖寶寶）的使用，下列說法正確的是？",
    "q.l21#5.o0" to "可以隨意貼在襪子外側",
    "q.l21#5.o1" to "僅在封閉空間使用，如手套、靴內；暴露在通風環境中溫度可高達約 74℃",
    "q.l21#5.o2" to "越貼近皮膚效果越好",
    "q.l21#5.o3" to "可以貼在帽子外側",
    "q.l21#5.e" to "保暖貼依賴隔絕空氣來維持溫度。暴露在通風環境中會劇烈反應、溫度可達約 74℃，足以造成燙傷。因此必須放在封閉空間（手套、靴內），絕不能直接貼皮膚或用在外露位置。",
    "q.l21#6.p" to "為什麼推薦選擇帶帽款的保暖外套與羽絨服？",
    "q.l21#6.o0" to "因為更好看",
    "q.l21#6.o1" to "因為用途更廣，能顯著減少頭部散熱",
    "q.l21#6.o2" to "因為更方便收納",
    "q.l21#6.o3" to "因為帶帽款更輕",
    "q.l21#6.e" to "頭部是散熱大戶，而帽子是最輕便、最靠近核心的保溫手段。帶帽外套在營地、休息、突發降溫時都能立刻用上；不帶帽的款式則必須額外配帽子，反而更麻煩也更重。",
    "q.l21#7.p" to "【多選】關於羽絨服的使用與保管，正確的做法是？",
    "q.l21#7.o0" to "嚴格防潮，受潮後會迅速失去保暖能力",
    "q.l21#7.o1" to "收納時保持乾燥",
    "q.l21#7.o2" to "極寒環境選擇帶帽、非合成填料的款式",
    "q.l21#7.o3" to "蓬鬆度越高，同重量下保暖性越好",
    "q.l21#7.o4" to "長期用壓縮袋收納以節省空間",
    "q.l21#7.e" to "羽絨靠固定空氣保暖，一旦受潮就會塌縮。這也是為什麼潮溼環境更推薦抓絨（聚酯纖維本身疏水）作為主力中間層，而把羽絨留作乾燥環境下的核心保暖。",
    "q.l21#8.p" to "高海拔防曬霜的參考規格是？",
    "q.l21#8.o0" to "SPF 15、普通乳液即可",
    "q.l21#8.o1" to "高氧化鋅含量、SPF 50 級別",
    "q.l21#8.o2" to "SPF 30 以下更透氣",
    "q.l21#8.o3" to "只需含防曬成分即可，不看數值",
    "q.l21#8.e" to "高海拔紫外線強、雪面反射再疊加一次，普通防曬很快就不夠用。高氧化鋅含量與 SPF 50 是常見推薦，而且必須定時補塗——出汗、擦拭、摩擦都會讓防護衰減。",
    "q.l21#9.p" to "戶外護唇膏的選擇要點是？",
    "q.l21#9.o0" to "越便宜越好",
    "q.l21#9.o1" to "富含鋅、具備一定抗汗能力，防曬係數 SPF 30–50",
    "q.l21#9.o2" to "只要保溼即可",
    "q.l21#9.o3" to "含薄荷成分更清涼",
    "q.l21#9.e" to "唇部皮膚薄、幾乎沒有黑色素保護，在高海拔極易曬傷與乾裂。鋅提供物理防護，抗汗能力保證它在出汗與飲食後仍留在唇上——這是最容易被忽略、又最影響體驗的一件小裝備。",
    // ---------- q.l22 ----------
    "q.l22#0.p" to "搭建冰裂縫救援系統最基礎的器材是？",
    "q.l22#0.o0" to "普式抓結繩套（輔助繩）",
    "q.l22#0.o1" to "望遠鏡",
    "q.l22#0.o2" to "備用睡袋",
    "q.l22#0.o3" to "登山杖",
    "q.l22#0.e" to "抓結繩套用來打摩擦結，是 3:1 拉昇系統的核心。沒有它，你只有赤手空拳的 1:1 拉力——而一個人幾乎不可能徒手把隊友從裂縫裡拉上來。",
    "q.l22#1.p" to "在高海拔山區，最可靠的呼救手段通常是？",
    "q.l22#1.o0" to "手機訊號",
    "q.l22#1.o1" to "衛星電話或 GPS 追蹤器",
    "q.l22#1.o2" to "大聲呼救",
    "q.l22#1.o3" to "生火冒煙",
    "q.l22#1.e" to "山區絕大部分割槽域沒有手機訊號。衛星電話可以直接通話與發簡訊，GPS 追蹤器能讓後方掌握你的位置——兩者都是出發前就該落實的裝備。",
    "q.l22#2.p" to "備用頭燈的亮度建議是？",
    "q.l22#2.o0" to "100 流明以下",
    "q.l22#2.o1" to "200 流明即可",
    "q.l22#2.o2" to "400 流明以上",
    "q.l22#2.o3" to "亮度不重要",
    "q.l22#2.e" to "頭燈要用於夜間帳篷內活動與日出前出發（衝頂通常在凌晨）。在風雪、霧天與需要辨認路線時，足夠的亮度直接關係判斷質量。防風雨型號在惡劣環境中優勢明顯。",
    "q.l22#3.p" to "選擇高山安全帶的關鍵要求是？",
    "q.l22#3.o0" to "越輕越好，不考慮尺寸",
    "q.l22#3.o1" to "腰腿部尺寸足夠，能套在最外層衣物外面",
    "q.l22#3.o2" to "必須有多個裝備掛環",
    "q.l22#3.o3" to "顏色要顯眼",
    "q.l22#3.e" to "高海拔行進時你往往穿著厚重衣物，安全帶必須能在這種情況下仍然正確貼合。穿在厚衣服外面卻已經被調到最長的安全帶，是常見且危險的錯誤配置。",
    "q.l22#4.p" to "高度計手錶的「風暴警報」功能基於什麼來判斷？",
    "q.l22#4.o0" to "衛星雲圖",
    "q.l22#4.o1" to "氣壓在短時間內快速下降",
    "q.l22#4.o2" to "風速測量",
    "q.l22#4.o3" to "溫度驟降",
    "q.l22#4.e" to "氣壓快速下降是天氣惡化的前置訊號。高度計手錶透過持續監測氣壓變化來預警，這在高海拔非常實用——因為天氣窗口的變化往往是決定行程的關鍵變數。",
    "q.l22#5.p" to "【配對】把主鎖型號與其最適合的用途對應起來。",
    "q.l22#5.l0" to "HMS 梨型鎖",
    "q.l22#5.l1" to "D 型鎖",
    "q.l22#5.l2" to "X 型鎖",
    "q.l22#5.l3" to "B 型鎖",
    "q.l22#5.r0" to "鎖門開口大，可用義大利半扣繩結連線做下降，用途最廣",
    "q.l22#5.r1" to "多與滑輪連線，用於救援系統中",
    "q.l22#5.r2" to "形狀對稱，簡易鎖，連線方便",
    "q.l22#5.r3" to "最基本的主鎖，用於各種臨時連線",
    "q.l22#5.e" to "不同形狀的主鎖各有擅長：HMS 開口大所以能配合半扣與下降，D 型強度高且便於裝滑輪，X 型對稱、操作方便，B 型是最通用的基礎款。選鎖不是看哪個「更結實」，而是看機構是否匹配。",
    "q.l22#6.p" to "使用上升器時，教材特別提醒不要怎麼做？",
    "q.l22#6.o0" to "不要在潮溼環境使用",
    "q.l22#6.o1" to "不要把上升器推得離固定端（繩結）過近",
    "q.l22#6.o2" to "不要單手操作",
    "q.l22#6.o3" to "不要在雪面使用",
    "q.l22#6.e" to "把上升器推到貼近繩結或固定端，會導致它無法繼續上行、又難以快速解除，人就卡在那個位置進退兩難。這類「卡住」在需要快速調整時非常危險，所以要在還有餘量時就處理。",
    "q.l22#7.p" to "關於固定繩與結組的選擇，下列說法正確的是？",
    "q.l22#7.o0" to "固定繩永遠比結組安全",
    "q.l22#7.o1" to "隊伍規模大時多用固定繩；隊伍小或攀技術型山峰時結組效率更高",
    "q.l22#7.o2" to "結組只適合雪坡",
    "q.l22#7.o3" to "固定繩只用於下降",
    "q.l22#7.e" to "固定繩能提高整體安全性，但需要更多的人力與裝備、鋪繩時間也更長。隊伍小而精、或面對技術型山峰時，結組反而更高效。這是典型的「沒有最好，只有是否匹配」的決策。",
    "q.l22#8.p" to "【多選】下列哪些屬於高海拔的通訊與導航器材？",
    "q.l22#8.o0" to "衛星電話",
    "q.l22#8.o1" to "對講機",
    "q.l22#8.o2" to "GPS 追蹤器",
    "q.l22#8.o3" to "帶氣壓計的高度計手錶",
    "q.l22#8.o4" to "望遠鏡",
    "q.l22#8.e" to "四者分工不同：衛星電話用於對外呼救，對講機用於隊內協同，GPS 追蹤器讓後方掌握位置，高度計手錶提供氣壓與海拔趨勢。高海拔的風險恰恰在於「無法求助」與「不知道自己在哪」，這幾件器材直接對沖這兩件事。",
    "q.l22#9.p" to "為什麼頭盔必須能安裝頭燈？",
    "q.l22#9.o0" to "為了美觀統一",
    "q.l22#9.o1" to "因為衝頂通常在日出前出發，頭燈需要穩定地固定在頭上",
    "q.l22#9.o2" to "為了減輕頭燈重量",
    "q.l22#9.o3" to "為了增加頭盔強度",
    "q.l22#9.e" to "衝頂日往往凌晨出發，頭燈是唯一光源；而戴著頭盔時，頭燈必須固定在頭盔上才能穩定照射。頭燈在行進中晃動或脫落，會直接導致看不清落腳點——這在技術地形上是實打實的風險。",
    // ---------- q.l17 ----------
    "q.l17#0.p" to "揮鎬時正確的發力方式是？",
    "q.l17#0.o0" to "用大臂猛砸",
    "q.l17#0.o1" to "靠手腕甩動，讓鎬尖垂直入冰",
    "q.l17#0.o2" to "用錘面敲擊冰面",
    "q.l17#0.o3" to "水平切進冰面",
    "q.l17#0.e" to "手腕發力能讓鎬尖以垂直角度快速入冰，更容易咬合且更省力。用大臂砸容易讓鎬尖以斜角切入並崩碎冰面，形成「剝落」而無法受力。",
    "q.l17#1.p" to "攀冰中的「三點固定」指的是？",
    "q.l17#1.o0" to "兩隻手加一隻腳（或兩腳加一隻手）保持三個穩定接觸點，再移動第四點",
    "q.l17#1.o1" to "三個人一起爬",
    "q.l17#1.o2" to "三個繩結同時受力",
    "q.l17#1.o3" to "裝備上要有三個掛鉤",
    "q.l17#1.e" to "三點固定是攀冰與攀岩共同的移動原則：始終保留三個可靠接觸點，只移動一個。這能保證在任一接觸點失效時你仍有支撐。",
    "q.l17#2.p" to "WI4 的典型特徵是？",
    "q.l17#2.o0" to "低角度冰面可徒步透過",
    "q.l17#2.o1" to "接近垂直並含短段垂直，保護位置可能不理想",
    "q.l17#2.o2" to "全是外懸屋簷",
    "q.l17#2.o3" to "只需要一根手杖",
    "q.l17#2.e" to "WI4 意味著地形已接近垂直並出現短段垂直段，同時保護（打冰錐）的位置可能並不理想，需要更強的技術與判斷力。WI1–WI2 屬於適合學習的低難度地形。",
    "q.l17#3.p" to "為什麼攀冰時要剋制揮鎬次數？",
    "q.l17#3.o0" to "為了省力",
    "q.l17#3.o1" to "冰面被打碎後會形成難以受力的剝落面",
    "q.l17#3.o2" to "因為冰鎬會磨損",
    "q.l17#3.o3" to "因為會吵到隊友",
    "q.l17#3.e" to "每一次失敗的揮鎬都會在冰壁上製造一個「爛洞」。頻繁敲擊會讓整片冰面失去承力能力，反而迫使你更多依賴手臂力量——形成惡性迴圈。",
    "q.l17#4.p" to "為什麼攀冰比運動攀岩更危險？",
    "q.l17#4.o0" to "因為更冷",
    "q.l17#4.o1" to "冰錐受力時可能崩出，且冰況每天都在變化",
    "q.l17#4.o2" to "因為沒有保護點",
    "q.l17#4.o3" to "因為不能使用繩索",
    "q.l17#4.e" to "岩石上的岩塞與膨脹釘一旦正確放置就相對可靠；冰錐依賴冰體本身的質量，而冰會融化、變脆、出現空腔——昨天牢固的保護點今天可能已經失去意義。",
    "q.l17#5.p" to "攀冰時為什麼強調「先站穩雙腳，再揮鎬」？",
    "q.l17#5.o0" to "因為手臂比腿更容易累",
    "q.l17#5.o1" to "腳是主要承重與休息的部位，手臂只做輔助",
    "q.l17#5.o2" to "因為冰鎬比較貴",
    "q.l17#5.o3" to "因為看起來更專業",
    "q.l17#5.e" to "攀冰中手臂力量消耗極快，腳才是能長時間承重的部位。在腳未站穩時就急於揮鎬，會讓手臂提前力竭，反而增加脫落風險。",
    "q.l17#6.p" to "冰況變「爛」通常發生在什麼條件下？",
    "q.l17#6.o0" to "深夜降溫之後",
    "q.l17#6.o1" to "強烈日照或氣溫升高後，冰體變軟並出現蜂窩狀結構",
    "q.l17#6.o2" to "剛下過新雪時",
    "q.l17#6.o3" to "風速明顯增大時",
    "q.l17#6.e" to "冰是溫度的函式。清晨的硬冰適合精準入鎬，午後的軟冰看似容易攀爬，實際上保護點更容易崩出。判斷冰況要結合時間、朝向、氣溫與日照歷史。",
    "q.l17#7.p" to "打冰錐之前，最應該確認的是？",
    "q.l17#7.o0" to "冰錐的顏色是否醒目",
    "q.l17#7.o1" to "該處冰體是否密實，有無空腔或蜂窩化",
    "q.l17#7.o2" to "是否便於拍照記錄",
    "q.l17#7.o3" to "離地面的高度",
    "q.l17#7.e" to "冰錐的強度不取決於放置技巧，而取決於冰本身。打在空腔或蜂窩冰上的冰錐幾乎無法承受墜落衝擊——這是攀冰保護與攀岩最本質的差別。",
    "q.l17#8.p" to "攀冰時前臂出現「泵脹」感，最應該怎麼做？",
    "q.l17#8.o0" to "加快攀爬速度儘快透過",
    "q.l17#8.o1" to "儘快找到能站穩的位置，把體重交給雙腳並放鬆手臂",
    "q.l17#8.o2" to "更用力地抓握以保持穩定",
    "q.l17#8.o3" to "立刻主動下撤",
    "q.l17#8.e" to "泵脹是前臂缺血的表現，繼續下去很快就會失去握力。正確反應是在還能控制時把重量轉移到腳上，讓前臂恢復血流——這也是「腳別偷懶」在實戰中的真正意義。",
    "q.l17#9.p" to "【配對】把 WI 水冰難度等級與其典型特徵對應起來。",
    "q.l17#9.l0" to "WI2",
    "q.l17#9.l1" to "WI3",
    "q.l17#9.l2" to "WI4",
    "q.l17#9.l3" to "WI5",
    "q.l17#9.r0" to "約 60° 的持續冰面並可能有鼓包，保護良好",
    "q.l17#9.r1" to "持續 60°～75°，通常保護良好但較費力",
    "q.l17#9.r2" to "接近垂直並含短段垂直，保護位置可能不理想",
    "q.l17#9.r3" to "持續垂直，保護較差且強度很大",
    "q.l17#9.e" to "WI 等級描述的是「地形角度 + 保護條件 + 體力消耗」三個變數的綜合結果。等級越高，撤退與自救的餘地越小——這也是為什麼等級只是參考，真正決定成敗的是當天的冰況與隊伍狀態。",
    "q.l17#10.p" to "【多選】攀冰時應當隨身可取的裝備包括？",
    "q.l17#10.o0" to "冰錐若干",
    "q.l17#10.o1" to "主鎖與快掛",
    "q.l17#10.o2" to "抓結輔繩",
    "q.l17#10.o3" to "制動/保護器",
    "q.l17#10.o4" to "備用睡袋",
    "q.l17#10.e" to "攀冰是「一邊移動一邊建立保護」的運動，任何一件裝備壓在揹包裡都等於不在。教材列出的救援裝備清單（冰錐、主鎖、扁帶、滑輪、抓結、上升器）邏輯與此一致：所有可能用到的都要在手邊。",
    "q.l17#11.p" to "為什麼攀冰時冰錐可能「崩出」？",
    "q.l17#11.o0" to "因為冰錐太短",
    "q.l17#11.o1" to "因為冰體本身可能存在空腔、蜂窩化或正在融化，強度不足",
    "q.l17#11.o2" to "因為掛得太多",
    "q.l17#11.o3" to "因為冰錐不鋒利",
    "q.l17#11.e" to "冰錐的強度不取決於放置技巧，而取決於冰本身。打在空腔或蜂窩冰上的冰錐幾乎無法承受墜落衝擊——這是攀冰保護與攀岩最本質的差別，也是打錐前必須確認冰質的原因。",
    "q.l17#12.p" to "為什麼說「攀冰的等級只是參考」？",
    "q.l17#12.o0" to "因為等級是隨手定的",
    "q.l17#12.o1" to "因為冰況每天都在變——日照、氣溫與季節會顯著改變同一路線的難度",
    "q.l17#12.o2" to "因為不同國家的等級不通用",
    "q.l17#12.o3" to "因為等級只反映長度",
    "q.l17#12.e" to "冰是溫度的函式：清晨的硬冰需要更精準的入鎬，午後的軟冰看似容易，保護點卻更容易崩出。同一路線在不同時間的難度差異可能超過一個等級——所以現場判斷永遠優先於資料上的數字。",
    "q.l17#13.p" to "【排序】把攀冰移動的「三點固定」節奏按正確順序排列。",
    "q.l17#13.o0" to "先觀察冰面，選擇入鎬點與落腳點",
    "q.l17#13.o1" to "用前齒穩定踢入冰面，建立雙腳支撐",
    "q.l17#13.o2" to "穩定雙腳後揮鎬入冰，確認咬合牢固",
    "q.l17#13.o3" to "在三個點穩定後，移動第四個點",
    "q.l17#13.e" to "這個順序解釋了為什麼「腳別偷懶」是攀冰的核心紀律：腳是能長時間承重的部位，手臂只做輔助。先揮鎬後站穩，就會讓手臂提前力竭——這在陡冰上是致命的。",
    // ---------- q.l18 ----------
    "q.l18#0.p" to "雪崩發生最集中的坡度區間是？",
    "q.l18#0.o0" to "10°–25°",
    "q.l18#0.o1" to "34°–45°",
    "q.l18#0.o2" to "55°–70°",
    "q.l18#0.o3" to "垂直冰壁",
    "q.l18#0.e" to "統計顯示絕大多數雪崩發生在 34°–45° 之間（96% 落在 30°–50° 區間）。這個坡度恰好是積雪能堆積、又陡到足以滑動的「危險窗口」，也正是登山路線最常經過的角度。",
    "q.l18#1.p" to "為什麼危險等級 3「相當危險」時事故最多？",
    "q.l18#1.o0" to "因為雪層最不穩定",
    "q.l18#1.o1" to "因為條件看起來尚可，最容易被低估",
    "q.l18#1.o2" to "因為所有人都待在家裡",
    "q.l18#1.o3" to "因為預報不準",
    "q.l18#1.e" to "等級 3 的矛盾在於：雪崩可能性確實存在，但地形看起來「可以接受」，於是大量人進入雪崩地形。等級 4、5 時人們普遍迴避，反而事故佔比下降。風險判斷中最危險的從來不是極端條件，而是被低估的中等條件。",
    "q.l18#2.p" to "雪崩三件套指的是？",
    "q.l18#2.o0" to "信標（收發器）、探杆、雪鏟",
    "q.l18#2.o1" to "頭盔、繩索、安全帶",
    "q.l18#2.o2" to "冰鎬、冰爪、冰錐",
    "q.l18#2.o3" to "帳篷、睡袋、防潮墊",
    "q.l18#2.e" to "信標用於搜救定位，探杆用於精確定位被埋者，雪鏟用於挖掘。三者缺一不可，而且必須經過練習才能在十幾分鐘的黃金窗口內完成有效救援。",
    "q.l18#3.p" to "為什麼「看起來不太陡」的坡反而最危險？",
    "q.l18#3.o0" to "因為雪層更厚",
    "q.l18#3.o1" to "34°–45° 正是雪崩最集中的區間，而人眼容易低估坡度",
    "q.l18#3.o2" to "因為人走得更快",
    "q.l18#3.o3" to "因為陽光更強",
    "q.l18#3.e" to "低於約 30° 的坡太平緩不易形成板狀雪崩，高於約 50° 雪不易堆積。危險窗口恰好落在「感覺還可以走」的角度區間——這就是它最容易被低估的原因。",
    "q.l18#4.p" to "透過雪崩地形時的正確做法是？",
    "q.l18#4.o0" to "全隊一起快速透過",
    "q.l18#4.o1" to "拉開間距、一人一人透過、指定觀察員並規劃撤離路線",
    "q.l18#4.o2" to "走谷底最短路線",
    "q.l18#4.o3" to "儘量走雪層最厚的地方",
    "q.l18#4.e" to "一人一人透過能把風險限定在單個人身上；觀察員能在事故發生時立刻定位並組織救援。全隊一起透過意味著一旦觸發就是全隊被埋——那是最壞的結果。",
    "q.l18#5.p" to "在野外聽到雪層發出「whumpf」塌陷聲，說明什麼？",
    "q.l18#5.o0" to "只是踩到了雪洞",
    "q.l18#5.o1" to "雪層中存在容易被觸發的弱層，穩定性差",
    "q.l18#5.o2" to "說明積雪很厚，透過性好",
    "q.l18#5.o3" to "說明雪層已經穩定",
    "q.l18#5.e" to "whumpf 是雪層瞬間塌陷的聲音，代表弱層已經開始破壞。這是非常直接的穩定性訊號——繼續進入該坡面，等於在用自己測試它是否會發生板狀雪崩。",
    "q.l18#6.p" to "為什麼板狀雪崩比松雪雪崩更致命？",
    "q.l18#6.o0" to "因為溫度更低",
    "q.l18#6.o1" to "整塊雪板同時崩落並壓埋，被埋者極難自救",
    "q.l18#6.o2" to "因為聲音更大",
    "q.l18#6.o3" to "因為發生得更頻繁",
    "q.l18#6.e" to "板狀雪崩幾乎整面同時斷裂，人在坡上就已失去支撐。一旦被埋，雪的重量與快速凝固會讓自救幾乎不可能——這就是雪崩搜救必須爭分奪秒的原因。",
    "q.l18#7.p" to "關於信標（收發器）的使用，正確的做法是？",
    "q.l18#7.o0" to "放在揹包裡攜帶即可",
    "q.l18#7.o1" to "出發前互相檢查傳送狀態，並定期演練搜尋流程",
    "q.l18#7.o2" to "只由隊長一人攜帶",
    "q.l18#7.o3" to "關機以節省電量",
    "q.l18#7.e" to "信標放在揹包裡幾乎沒有意義——被埋時手臂可能完全無法活動，必須貼身攜帶（通常放在胸前）。同時搜尋流程必須經過演練，否則現場無法在黃金十幾分鍾內完成定位。",
    "q.l18#8.p" to "進入雪崩地形之前，隊伍最應該做的準備是？",
    "q.l18#8.o0" to "只要帶齊裝備就夠了",
    "q.l18#8.o1" to "檢視當日雪崩預報，並結合現場觀察隨時調整路線與計劃",
    "q.l18#8.o2" to "完全相信個人經驗",
    "q.l18#8.o3" to "跟隨前人留下的足跡",
    "q.l18#8.e" to "預報提供區域尺度的判斷，現場觀察提供坡面尺度的證據，兩者缺一不可。跟隨前人足跡尤其危險——足跡可能是幾小時前留下的，而雪層條件早已改變。",
    "q.l18#9.p" to "據統計，登山山難事故死亡案例中佔比最高的是？",
    "q.l18#9.o0" to "雪崩最多，其次是滑墜",
    "q.l18#9.o1" to "滑墜最多，其次是雪崩",
    "q.l18#9.o2" to "疾病最多，其次是落石",
    "q.l18#9.o3" to "失溫最多，其次是雪崩",
    "q.l18#9.e" to "教材給出的排序很明確：滑墜最多，其次是雪崩。這個排序有現實意義——雪崩常被認為是最可怕的風險，但真正奪命最多的是更「日常」的滑墜。風險排序應當按資料，而不是按印象。",
    "q.l18#10.p" to "雪崩發生後，被埋者的黃金救援時間大約是？",
    "q.l18#10.o0" to "十幾分鍾",
    "q.l18#10.o1" to "兩小時",
    "q.l18#10.o2" to "六小時",
    "q.l18#10.o3" to "24 小時",
    "q.l18#10.e" to "十幾分鍾——這個時間尺度決定了救援必須由同伴立即完成，等專業救援到達幾乎來不及。這也是為什麼雪崩三件套（信標、探杆、雪鏟）必須隨身、必須練熟，而不是「帶著就行」。",
    "q.l18#11.p" to "【多選】判斷雪崩風險時，值得留意現場訊號有？",
    "q.l18#11.o0" to "雪層發出「whumpf」塌陷聲",
    "q.l18#11.o1" to "坡面上出現新鮮的裂縫",
    "q.l18#11.o2" to "近期有新雪堆積或明顯風載",
    "q.l18#11.o3" to "下坡時雪面出現明顯的「發響」與下沉",
    "q.l18#11.o4" to "天空出現大片捲雲、能見度極佳",
    "q.l18#11.e" to "這些都是穩定性正在下降的直接證據。它們的價值在於「當下」——區域預報給出的是尺度判斷，而這些現場訊號反映的是你腳下這一坡此刻的真實狀態。兩者缺一不可。",
    "q.l18#12.p" to "圖中是同一座山的三段坡面。點選雪崩風險最高的那一段。",
    "q.l18#12.e" to "雪崩最集中的坡度是 34°～45°。左側緩坡（約 16°）太平緩，難以形成板狀雪崩；右側陡坡（約 60°）太陡，積雪不易堆積成厚雪板。只有中間約 40° 的坡面落在「既能積雪、又能滑動」的危險窗口裡——而這恰好是登山路線最常經過的角度，這就是它最容易被低估的原因。",
    // ---------- q.l19 ----------
    "q.l19#0.p" to "設定折返時間（turnaround time）的作用是？",
    "q.l19#0.o0" to "到點無條件撤退，避免被目標執念綁架",
    "q.l19#0.o1" to "用來計算登山速度",
    "q.l19#0.o2" to "用來決定帶多少食物",
    "q.l19#0.o3" to "只是形式上的安排",
    "q.l19#0.e" to "折返時間把決策從「現場情緒」中剝離出來：出發前理性時定下的規則，在疲憊與不甘的現場替你執行判斷。這是對抗登頂狂熱最有效的工具。",
    "q.l19#1.p" to "「登頂狂熱」的典型成因是？",
    "q.l19#1.o0" to "天氣太好",
    "q.l19#1.o1" to "沉沒成本與隊伍壓力導致判斷扭曲",
    "q.l19#1.o2" to "裝備不足",
    "q.l19#1.o3" to "海拔太低",
    "q.l19#1.e" to "已經投入的時間、金錢與體力會讓人不願承認應當放棄；隊伍中的沉默或相互鼓勵會進一步壓制疑慮。理解這個機制，是提前建立客觀決策規則的前提。",
    "q.l19#2.p" to "隊伍的撤退決策應該在什麼時候定好？",
    "q.l19#2.o0" to "出發前就約定客觀觸發訊號與決策權",
    "q.l19#2.o1" to "等到了山頂再說",
    "q.l19#2.o2" to "遇到危險時臨時討論",
    "q.l19#2.o3" to "由體力最好的人現場決定",
    "q.l19#2.e" to "在疲憊、缺氧與情緒化的現場臨時爭論撤退，幾乎總是傾向於繼續前進。出發前約定好客觀訊號（例如某個時間點、某種天氣變化、某類隊員狀態），並明確誰有最終決定權，才是可靠的做法。",
    "q.l19#3.p" to "為什麼大量事故發生在下撤途中？",
    "q.l19#3.o0" to "因為下坡更難走",
    "q.l19#3.o1" to "目標達成後警覺性下降，而體能已接近極限",
    "q.l19#3.o2" to "因為下撤時天氣總是更差",
    "q.l19#3.o3" to "因為裝備會失效",
    "q.l19#3.e" to "「登頂只是行程的一半」的真正含義是：行程風險在下撤時才集中釋放。因此下撤階段的結組、繩索保護與節奏控制，不能因為登頂而放鬆。",
    "q.l19#4.p" to "事前約定撤退決策的價值在於？",
    "q.l19#4.o0" to "節省時間",
    "q.l19#4.o1" to "把決策從現場的疲憊與情緒中剝離出來，由出發前的理性判斷執行",
    "q.l19#4.o2" to "讓隊長更有權威",
    "q.l19#4.o3" to "避免隊友爭吵",
    "q.l19#4.e" to "在缺氧、疲勞與不甘的情緒裡做決定，幾乎總會傾向於繼續前進。出發前約定客觀訊號與決策權，等於讓「冷靜時的自己」替「疲憊時的自己」做決定。",
    "q.l19#5.p" to "為什麼「撤退方案」必須寫進攀登計劃？",
    "q.l19#5.o0" to "為了讓計劃看起來完整",
    "q.l19#5.o1" to "撤退需要裝備、路線與時間預算，臨時決定往往來不及準備",
    "q.l19#5.o2" to "為了應付檢查",
    "q.l19#5.o3" to "因為規定要求如此",
    "q.l19#5.e" to "撤退本身是一次真實的技術操作：可能需要建立確保站、沿繩下降、在黑暗中行進。如果計劃裡沒有為它預留時間與器材，撤退就會變成一次高風險的臨時作業。",
    "q.l19#6.p" to "隊伍中對路線或天氣出現不同意見時，正確的處理方式是？",
    "q.l19#6.o0" to "少數服從多數",
    "q.l19#6.o1" to "採用最保守的意見，直到出現新證據能說服所有人",
    "q.l19#6.o2" to "由體力最好的人決定",
    "q.l19#6.o3" to "投票決定後不再討論",
    "q.l19#6.e" to "在高風險環境中，最保守的意見應當擁有優先權。多數決會讓少數人的合理擔憂被壓制——而事故覆盤中最常見的一句話就是「當時有人覺得不對勁，但沒人說出來」。",
    "q.l19#7.p" to "關於「跟著嚮導就一定安全」，正確的認識是？",
    "q.l19#7.o0" to "跟著嚮導就絕對安全",
    "q.l19#7.o1" to "嚮導能降低風險，但無法消除客觀危險，隊員仍需保持判斷力",
    "q.l19#7.o2" to "嚮導只負責帶路，安全靠自己",
    "q.l19#7.o3" to "隊員不需要做任何判斷",
    "q.l19#7.e" to "嚮導的價值在於經驗與決策質量，但雪崩、落石與天氣不會因為有人帶隊就消失。隊員理解風險、能識別危險訊號並主動溝通，本身就是隊伍安全能力的一部分。",
    "q.l19#8.p" to "登山中的「目標退變」指的是？",
    "q.l19#8.o0" to "降低路線的難度等級",
    "q.l19#8.o1" to "為了達成登頂目標，不斷放寬原本設定的安全標準",
    "q.l19#8.o2" to "中途更換目標山峰",
    "q.l19#8.o3" to "縮小隊伍規模",
    "q.l19#8.e" to "目標退變是登頂狂熱的典型表現：折返時間一推再推，可接受的天氣窗口一寬再寬，身體症狀一忍再忍。識別它的唯一方法是事前把標準量化，讓「放寬」變成一個顯式的、需要向隊友解釋的行為。",
    "q.l19#9.p" to "【多選】一份完整的攀登計劃應當包含哪些內容？",
    "q.l19#9.o0" to "路線與時間表（含折返時間）",
    "q.l19#9.o1" to "撤退方案與備用路線",
    "q.l19#9.o2" to "隊員狀態評估與分工",
    "q.l19#9.o3" to "通訊方式、聯絡人與應急流程",
    "q.l19#9.o4" to "對外的媒體報道與傳播計劃",
    "q.l19#9.e" to "四項缺一不可。特別容易被省略的是第二項與第四項——因為它們在順利時用不到。但計劃的價值恰恰在於「不順利的時候」，而那時沒有時間補做計劃。",
    "q.l19#10.p" to "為什麼行程裡要預留「餘量天數」？",
    "q.l19#10.o0" to "為了應對天氣窗口後移、隊員不適等延誤",
    "q.l19#10.o1" to "為了多休息",
    "q.l19#10.o2" to "為了省錢",
    "q.l19#10.o3" to "為了讓行程更寬鬆好看",
    "q.l19#10.e" to "高海拔行程幾乎必然出現延誤：天氣不配合、有人需要多一天適應、路上比預想慢。沒有餘量的計劃，一遇延誤就會被迫壓縮適應時間或延長每日行軍——兩者都會顯著推高風險。",
    "q.l19#11.p" to "【排序】制定攀登計劃的合理步驟是？",
    "q.l19#11.o0" to "確定目標與路線，收集資料與歷史天氣",
    "q.l19#11.o1" to "評估隊伍能力與時間，安排適應節奏",
    "q.l19#11.o2" to "設定折返時間與可量化的撤退訊號",
    "q.l19#11.o3" to "制定撤退方案與應急流程，並告知後方聯絡人",
    "q.l19#11.e" to "順序體現的是「先定目標、再看能力、然後劃紅線、最後留退路」。很多人把順序倒過來——先做目標、後想退路，結果退路永遠排在最後，也永遠不會被認真設計。",
    "q.l19#12.p" to "為什麼「下撤所需時間」最常被低估？",
    "q.l19#12.o0" to "因為下坡更快",
    "q.l19#12.o1" to "因為下撤時體力已大量消耗、地形可能變差、還要操作保護與回收裝備",
    "q.l19#12.o2" to "因為地圖不準",
    "q.l19#12.o3" to "因為嚮導會催促",
    "q.l19#12.e" to "上升時你可能只花了 6 小時，但下撤往往需要更久：體力下降、雪面變軟或結冰、能見度變差、還可能要做繩降與回收保護。把下撤時間按上升時間估算，是最常見的計劃錯誤之一。",
    "q.l19#13.p" to "為什麼計劃裡要寫明通訊與聯絡方案？",
    "q.l19#13.o0" to "為了記錄",
    "q.l19#13.o1" to "因為一旦失聯，後方需要知道去哪裡搜救、以及何時該啟動搜救",
    "q.l19#13.o2" to "為了向公司彙報",
    "q.l19#13.o3" to "為了滿足許可要求",
    "q.l19#13.e" to "搜救最大的困難是「不知道人在哪」。行程計劃、路線、備用方案與聯絡時間，是把搜救時間從幾天壓縮到幾小時的關鍵資訊——而這些資訊只能在出發前提供。",
    "q.l19#14.p" to "隊伍規模會如何影響計劃？",
    "q.l19#14.o0" to "規模與計劃無關",
    "q.l19#14.o1" to "人數越多行軍越慢、後勤負擔越重，適應節奏也更難統一",
    "q.l19#14.o2" to "人越多越安全，不需要調整計劃",
    "q.l19#14.o3" to "人越多越快",
    "q.l19#14.e" to "大隊伍的優勢是人力與資源共享，代價是速度與靈活度下降：每個人的節奏不同，而隊伍只能按最慢者前進。因此隊伍規模必須寫進計劃的節奏估算裡，而不是事後抱怨「人多走得慢」。",
    "q.l19#15.p" to "填空：高海拔行程通常建議預留約（ ）% 的餘量天數。",
    "q.l19#15.a0" to "20",
    "q.l19#15.a1" to "30",
    "q.l19#15.a2" to "25",
    "q.l19#15.a3" to "20-30",
    "q.l19#15.a4" to "20～30",
    "q.l19#15.a5" to "二十五",
    "q.l19#15.e" to "通常建議預留 20%～30% 的餘量。舉例：一個預計 10 天的行程，應當按 12～13 天來規劃補給、假期與許可——這個比例看似保守，但它對應的正是實際延誤的發生頻率。",
    // ---------- q.l20 ----------
    "q.l20#0.p" to "救援的第一原則是？",
    "q.l20#0.o0" to "儘快搬動傷員",
    "q.l20#0.o1" to "確保現場安全，不製造第二個傷員",
    "q.l20#0.o2" to "先拍照記錄現場",
    "q.l20#0.o3" to "先給傷員喝水",
    "q.l20#0.e" to "在落石、雪崩、冰裂縫、陡坡等環境中，貿然接近傷員往往會讓救援者也變成傷員，使可用人力直接減半。評估現場風險是救援的第一步，也是唯一不可省略的一步。",
    "q.l20#1.p" to "應急處理的正確順序起點是？",
    "q.l20#1.o0" to "先確保現場安全，再評估傷情",
    "q.l20#1.o1" to "先搬動傷員到安全處再說",
    "q.l20#1.o2" to "先尋找食物和水",
    "q.l20#1.o3" to "先建立繩索系統",
    "q.l20#1.e" to "標準順序是安全 → 評估 → 呼救 → 處置 → 轉移。跳過安全評估直接接觸傷員，是最常見的救援失誤。",
    "q.l20#2.p" to "為什麼在高海拔，預防遠比救援重要？",
    "q.l20#2.o0" to "因為救援費用高",
    "q.l20#2.o1" to "因為救援受天氣、氧氣與人力制約，往往無法及時抵達",
    "q.l20#2.o2" to "因為救援隊不願意出動",
    "q.l20#2.o3" to "因為山上沒有訊號而已",
    "q.l20#2.e" to "高海拔環境會同時削弱救援方與被救方：直升機受氣流與海拔限制，救援隊需要數小時才能到達，而傷員在低氧與低溫下惡化得更快。這個時間差就是你唯一的救援資源。",
    "q.l20#3.p" to "高山救援為什麼常常需要數小時到數天？",
    "q.l20#3.o0" to "因為救援隊不願意出動",
    "q.l20#3.o1" to "受天氣、氧氣、通訊與人力嚴格制約，直升機也受氣流與海拔限制",
    "q.l20#3.o2" to "因為距離太遠",
    "q.l20#3.o3" to "因為費用太高",
    "q.l20#3.e" to "直升機在高海拔的載重與氣流條件下難以起飛，地面救援隊需要數小時才能抵達。這個時間差意味著：在高海拔，你首先是自己唯一的救援隊。",
    "q.l20#4.p" to "出發前留下行程計劃與聯絡人的作用是？",
    "q.l20#4.o0" to "只是走形式",
    "q.l20#4.o1" to "一旦失聯，救援方知道去哪裡搜救，能顯著縮短搜救時間",
    "q.l20#4.o2" to "方便事後報銷",
    "q.l20#4.o3" to "為了遵守規定",
    "q.l20#4.e" to "搜救最大的困難是「不知道人在哪裡」。行程計劃、路線、備用方案與聯絡方式，是把搜救時間從幾天壓縮到幾小時的關鍵資訊。",
    "q.l20#5.p" to "傷情評估中，最先要處理的是什麼？",
    "q.l20#5.o0" to "骨折固定",
    "q.l20#5.o1" to "氣道與呼吸等危及生命的緊急問題",
    "q.l20#5.o2" to "詳細記錄傷情",
    "q.l20#5.o3" to "先處理可見的傷口",
    "q.l20#5.e" to "評估遵循「危及生命優先」的順序：先解決氣道、呼吸與迴圈的緊急問題，再處理骨折、傷口等非即刻致命的損傷。順序錯了，其餘處置的意義都會大打折扣。",
    "q.l20#6.p" to "在高海拔環境中，保溫為什麼是急救的關鍵環節？",
    "q.l20#6.o0" to "因為傷員會覺得舒服",
    "q.l20#6.o1" to "傷員失去活動能力後失溫會迅速進展，進一步加重傷情",
    "q.l20#6.o2" to "因為有相關規定",
    "q.l20#6.o3" to "為了方便後續搬運",
    "q.l20#6.e" to "在寒冷與缺氧環境中，無法活動的傷員會迅速喪失產熱能力。失溫會加重休克並掩蓋症狀，因此隔離地面、防風、更換溼衣往往與止血同等重要。",
    "q.l20#7.p" to "通訊中斷時，隊伍的應急預案應該是？",
    "q.l20#7.o0" to "原地等待直到恢復聯絡",
    "q.l20#7.o1" to "出發前約定匯合點、失聯時限與後續行動方案",
    "q.l20#7.o2" to "立刻分頭尋找",
    "q.l20#7.o3" to "直接全體下撤",
    "q.l20#7.e" to "通訊中斷在山地是常態而非意外。事前約定「幾點未能聯絡就啟動什麼步驟」，既能避免現場慌亂，也讓後方知道何時該發起搜救。",
    "q.l20#8.p" to "關於急救與救援訓練，正確的態度是？",
    "q.l20#8.o0" to "看過教程、記住步驟就夠了",
    "q.l20#8.o1" to "必須定期實操演練，僅靠閱讀無法在真實場景中執行",
    "q.l20#8.o2" to "只需要隊長掌握即可",
    "q.l20#8.o3" to "那是專業救援人員才需要學的",
    "q.l20#8.e" to "急救與救援都是高度程式化的技能，在壓力下會退回到你實際訓練過的水平。閱讀能建立框架，但只有重複演練，才能讓動作在慌亂中依然正確。",
    "q.l20#9.p" to "【排序】傷情評估與處置的標準順序是？",
    "q.l20#9.o0" to "確保現場安全，不製造第二個傷員",
    "q.l20#9.o1" to "評估意識、氣道、呼吸與迴圈",
    "q.l20#9.o2" to "處理危及生命的緊急問題（止血、保溫、固定）",
    "q.l20#9.o3" to "呼救並安排轉移或等待專業救援",
    "q.l20#9.e" to "第一步與第四步最容易被壓縮——人在緊張時會直接衝向傷員。但現場不安全時，救援者會變成第二個傷員，可用人力直接減半；而不呼救則意味著後面的處置沒有後援。",
    "q.l20#10.p" to "【多選】呼救時應提供的關鍵資訊包括？",
    "q.l20#10.o0" to "準確位置（座標或可識別地標）",
    "q.l20#10.o1" to "傷員人數、意識與呼吸狀況",
    "q.l20#10.o2" to "現場地形與天氣條件",
    "q.l20#10.o3" to "可用的通訊方式與聯絡時間",
    "q.l20#10.o4" to "傷員的過往攀登履歷",
    "q.l20#10.e" to "這四項決定救援方派什麼、派多少、從哪進。位置不準會浪費數小時；不知道傷情就無法準備裝備；不瞭解天氣可能導致救援隊自己也陷入險境。呼救是一門需要提前練習的溝通技能。",
    "q.l20#11.p" to "為什麼高海拔的直升機救援常常難以實施？",
    "q.l20#11.o0" to "因為費用太高",
    "q.l20#11.o1" to "因為空氣稀薄降低升力與載重能力，且氣流亂、天氣窗口短",
    "q.l20#11.o2" to "因為飛行員不願意上去",
    "q.l20#11.o3" to "因為海拔高沒有航線",
    "q.l20#11.e" to "直升機的升力來自空氣，而高海拔空氣稀薄——這直接限制了它能吊起多少重量、能飛多高。加上山區氣流紊亂、天氣多變，能飛的時間窗口可能只有幾十分鐘。這就是「不能把救援當成預案」的原因。",
    "q.l20#12.p" to "【配對】把急救處置與其適用場景對應起來。",
    "q.l20#12.l0" to "保溫",
    "q.l20#12.l1" to "止血",
    "q.l20#12.l2" to "固定",
    "q.l20#12.l3" to "給氧",
    "q.l20#12.r0" to "任何高海拔傷員都應優先做，防止失溫加重休克",
    "q.l20#12.r1" to "開放性傷口或肢體出血時的首要處置",
    "q.l20#12.r2" to "疑似骨折或關節損傷，避免搬運造成二次傷害",
    "q.l20#12.r3" to "呼吸困難、血氧明顯偏低或疑似肺水腫",
    "q.l20#12.e" to "四類處置在高海拔都是「基礎動作」而非專業操作。它們的共同點是：不需要複雜裝置、但需要正確判斷順序——例如保溫在一般急救裡常被放在後面，在高海拔卻是優先項。",
    "q.l20#13.p" to "為什麼救援中要評估「繼續救援本身的風險」？",
    "q.l20#13.o0" to "因為救援太累",
    "q.l20#13.o1" to "因為救援行動可能讓更多人陷入危險，從而降低整體生存機率",
    "q.l20#13.o2" to "因為需要保險",
    "q.l20#13.o3" to "因為規定要求",
    "q.l20#13.e" to "救援決策的本質是資源分配：如果為了接近傷員而讓兩名救援者也受傷，可用人力就從「一傷兩救」變成「三傷零救」。這不是冷酷，而是讓整體存活機率最大化的必要計算。",
    "q.l20#14.p" to "什麼情況下應該停止自救、轉入等待專業救援？",
    "q.l20#14.o0" to "只要還有力氣就應繼續自救",
    "q.l20#14.o1" to "當自救可能造成二次傷害、或環境條件已超出隊伍能力時",
    "q.l20#14.o2" to "只有當完全沒力氣時才停止",
    "q.l20#14.o3" to "永遠不該停止自救",
    "q.l20#14.e" to "自救的價值在於爭取時間，而不是冒險。當繼續操作可能讓傷員或救援者受更重的傷，或者暴風雪已使移動風險大於停留風險時，穩住現狀、等待後援反而是更優解。",
    "q.l20#15.p" to "填空：傷情評估中的 SAMPLE 縮寫，E 代表（ ）。",
    "q.l20#15.a0" to "事件",
    "q.l20#15.a1" to "Event",
    "q.l20#15.a2" to "event",
    "q.l20#15.a3" to "事故",
    "q.l20#15.e" to "E 代表 Event（事件）——即戶外事故發生的經過。這一項的價值常被低估：事故機制（如何墜落、有無撞擊頭部、被埋多久）直接指向可能的損傷型別，是判斷傷情的重要線索。",
    // ---------- q.l1 ----------
    "q.l1#0.p" to "下列哪一項屬於「客觀危險」？",
    "q.l1#0.o0" to "落石與冰崩",
    "q.l1#0.o1" to "判斷失誤",
    "q.l1#0.o2" to "體能透支",
    "q.l1#0.o3" to "攀比心理",
    "q.l1#0.e" to "客觀危險指不因人的技術與態度而改變的環境因素：落石、冰崩、雪崩、天氣、冰裂縫。其餘三項都是可被訓練與自律控制的主觀危險。",
    "q.l1#1.p" to "海拔上升時，氣溫與氧分壓如何變化？",
    "q.l1#1.o0" to "氣溫上升，氧分壓下降",
    "q.l1#1.o1" to "氣溫約每公里下降 6.5℃，氧分壓同步下降",
    "q.l1#1.o2" to "氣溫與氧分壓都不變",
    "q.l1#1.o3" to "氣溫下降，氧分壓上升",
    "q.l1#1.e" to "海拔每升高約 1000 公尺，氣溫平均下降約 6.5℃；同時氣壓降低、氧分壓下降，這是高山症與環境失溫同時存在的根本原因。",
    "q.l1#2.p" to "關於培訓的作用，下列說法正確的是？",
    "q.l1#2.o0" to "訓練到位就能消除所有客觀危險",
    "q.l1#2.o1" to "培訓只能降低主觀危險，無法消除客觀危險",
    "q.l1#2.o2" to "客觀危險只能靠運氣",
    "q.l1#2.o3" to "只要體能足夠就沒有危險",
    "q.l1#2.e" to "技術訓練提高的是你應對與判斷的能力，但落石、雪崩、天氣不會因為你有經驗就消失。對客觀危險的正確態度是規避與留退路。",
    "q.l1#3.p" to "登山中強調「留餘量」，而不是強調「現場補救」，原因是？",
    "q.l1#3.o0" to "因為餘量能提高登頂率",
    "q.l1#3.o1" to "因為餘量作用在事故鏈的早期，而補救往往發生在最後一環",
    "q.l1#3.o2" to "因為餘量比較省錢",
    "q.l1#3.o3" to "因為規定要求預留餘量",
    "q.l1#3.e" to "餘量的形式很多：時間餘量、體力餘量、補給餘量、天氣窗口餘量。它們的共同點是——在你還能選擇時就把空間留出來。而“補救”總是在事情已經不對勁之後才開始，選擇已經很少了。",
    "q.l1#4.p" to "衡量一支登山隊伍的“水平”，最合適的依據是？",
    "q.l1#4.o0" to "登頂過的最高海拔",
    "q.l1#4.o1" to "每年出隊的次數",
    "q.l1#4.o2" to "能否在需要時穩妥撤退，把風險控制在可接受範圍",
    "q.l1#4.o3" to "裝備的總價值",
    "q.l1#4.e" to "登頂資料只能說明“成功過”，而撤退能力才能說明“可控”。高海拔運動的現實是：機會總會再來，而嚴重事故不會。因此真正區分隊伍水平的，是它們在不利條件下做出好決定的能力。",
    "q.l1#5.p" to "《國內登山管理辦法》限定登山活動為攀登「獨立山峰」。獨立山峰在地形圖上的定義是？",
    "q.l1#5.o0" to "高度超過 5000 公尺的山體",
    "q.l1#5.o1" to "具有閉合等高線的山體",
    "q.l1#5.o2" to "有明顯冰川的山體",
    "q.l1#5.o3" to "從未有人登頂的山體",
    "q.l1#5.e" to "獨立山峰在地形圖上表現為一條閉合的等高線，也就是山體四周都有獨立的下坡輪廓。這個定義把「登山」與「走到某個高點」區分開來，也是登山活動管理與統計的基礎。",
    "q.l1#6.p" to "事故覆盤中最常見的規律是？",
    "q.l1#6.o0" to "絕大多數事故源於單一的重大失誤",
    "q.l1#6.o1" to "重大事故通常是多個小失誤疊加的結果",
    "q.l1#6.o2" to "事故與經驗水平無關",
    "q.l1#6.o3" to "裝備失效是主要原因",
    "q.l1#6.e" to "典型事故往往是一條「事故鏈」：路線判斷偏樂觀 → 時間比計劃晚 → 為趕時間簡化保護 → 疲勞導致動作變形。鏈條上任何一環被打破，事故就不會發生——這也是為什麼「留餘量」比「補救」有效得多。",
    "q.l1#7.p" to "【多選】下列哪些屬於登山中的客觀危險？",
    "q.l1#7.o0" to "落石與冰崩",
    "q.l1#7.o1" to "雪崩",
    "q.l1#7.o2" to "天氣突變",
    "q.l1#7.o3" to "冰裂縫",
    "q.l1#7.o4" to "攀比心理",
    "q.l1#7.e" to "這四項都不因你的技術與態度而改變——它們是環境本身的屬性。面對客觀危險，能做的只有規避、選時機、留退路；主觀危險（判斷失誤、準備不足、攀比心理）才是訓練能真正降低的部分。",
    "q.l1#8.p" to "參加一次高海拔攀登之前，最應該確認的三件事是？",
    "q.l1#8.o0" to "體能、裝備、行程與保險",
    "q.l1#8.o1" to "同伴名氣、山峰知名度、裝備品牌",
    "q.l1#8.o2" to "照片、影片、社交分享計劃",
    "q.l1#8.o3" to "天氣預報、機票、酒店",
    "q.l1#8.e" to "體能決定你能不能走完，裝備決定你能不能在惡劣條件下生存，行程與保險決定出事時有沒有後援。這三項都屬於出發前可以完全掌控的部分——也正因如此，它們出了問題沒有任何藉口。",
    "q.l1#9.p" to "為什麼經驗豐富的攀登者也可能遇險？",
    "q.l1#9.o0" to "因為經驗會讓人對風險的接受度逐步提高",
    "q.l1#9.o1" to "因為經驗豐富的人走得更難",
    "q.l1#9.o2" to "因為經驗與安全無關",
    "q.l1#9.o3" to "因為經驗豐富的人更容易疲勞",
    "q.l1#9.e" to "這叫「風險正常化」：多次在某個條件下安全透過後，人會不自覺地把這個條件重新歸類為「安全」，於是把標準一點點放寬。所以越是老手，越需要靠顯式的規則（比如折返時間）來約束自己的判斷。",
    // ---------- q.l2 ----------
    "q.l2#0.p" to "T 型（技術型）冰鎬主要適用的場景是？",
    "q.l2#0.o0" to "平緩雪坡散步",
    "q.l2#0.o1" to "陡峭冰壁與技術攀登",
    "q.l2#0.o2" to "僅用於拍照",
    "q.l2#0.o3" to "只用於雪地露營",
    "q.l2#0.e" to "T 型冰鎬的鎬柄可插入冰面並承受拉力，用於陡峭冰壁。B 型鎬柄強度較低，只能承受行走與自制動時的負荷，不能當作技術攀登的支撐點。",
    "q.l2#1.p" to "全硬的 B3 高山靴應該搭配哪一檔冰爪？",
    "q.l2#1.o0" to "C1 全綁帶式",
    "q.l2#1.o1" to "C2 前綁後卡式",
    "q.l2#1.o2" to "C3 全卡式",
    "q.l2#1.o3" to "任意一檔都可以",
    "q.l2#1.e" to "B3 全硬靴的前後都有卡槽，配 C3 全卡式冰爪最穩固。B1 配 C1、B2 配 C2、B3 配 C3 是裝備配套的基本規則。",
    "q.l2#2.p" to "把 C3 全卡式冰爪裝在軟底徒步靴上，會有什麼後果？",
    "q.l2#2.o0" to "完全沒問題，更省事",
    "q.l2#2.o1" to "靴體受力變形，冰爪在行走中脫落，屬危險配置",
    "q.l2#2.o2" to "會跑得更快",
    "q.l2#2.o3" to "只是外觀不好看",
    "q.l2#2.e" to "全卡式冰爪依賴硬質靴體提供剛性支撐。裝在軟底靴上，靴體會變形，卡扣失去咬合，冰爪可能在陡坡上脫落——這是明確的高危錯誤配置。",
    "q.l2#3.p" to "冰鎬長度通常按身高選擇。身高約 173–180 公分的攀登者建議選多長？",
    "q.l2#3.o0" to "50 公分",
    "q.l2#3.o1" to "55 公分",
    "q.l2#3.o2" to "60 公分",
    "q.l2#3.o3" to "70 公分",
    "q.l2#3.e" to "常見的身高對應參考：低於約 157 公分選 50 公分，157–170 公分選 55 公分，173–180 公分選 60 公分，183 公分以上選 65–70 公分。長度合適才能在自我制動時把鎬尖有效地壓入雪面。",
    "q.l2#4.p" to "選擇冰爪時，最基本也最關鍵的要求是？",
    "q.l2#4.o0" to "越輕越好",
    "q.l2#4.o1" to "必須與靴子貼合，推薦 12 齒鋼製並帶防滑板",
    "q.l2#4.o2" to "顏色要與裝備統一",
    "q.l2#4.o3" to "齒越多越好，20 齒以上最佳",
    "q.l2#4.e" to "冰爪的價值完全取決於它與靴子結合的可靠性。齒數並非越多越好，貼合度與防滑板（防止雪球堆積）才是關鍵——不貼合的冰爪最容易在陡坡上脫落。",
    "q.l2#5.p" to "【情境】一次需要自帶冰爪、冰鎬、備用保暖層、當日水糧與應急物資的高海拔技術登頂日，揹包淨容量建議選？",
    "q.l2#5.c" to "揹包容量沒有唯一的標準答案——它取決於路線型別、是否需要自帶技術裝備、以及公共物資由誰承擔。",
    "q.l2#5.o0" to "15–25 升",
    "q.l2#5.o1" to "35–50 升",
    "q.l2#5.o2" to "60–75 升",
    "q.l2#5.o3" to "90 升以上",
    "q.l2#5.e" to "在這種“需自帶技術裝備 + 備用保暖 + 應急物資”的場景下，35–50 升是常見區間，而且最好有專門放冰爪的口袋。\n但容量並非固定：在路線成熟、公共物資由協作承擔、天氣穩定的簡單雪坡上，15–25 升的輕量登頂包完全可能夠用；反之若需自行揹負帳篷或繩索，就要更大。\n判斷依據始終是“實際要裝什麼”，而不是一個通用數字。",
    "q.l2#6.p" to "冰鎬腕套（腕帶）的主要作用是？",
    "q.l2#6.o0" to "裝飾與識別隊伍",
    "q.l2#6.o1" to "防止脫手，並讓滑墜後仍能控制冰鎬",
    "q.l2#6.o2" to "增加冰鎬重量以便下壓",
    "q.l2#6.o3" to "便於掛在揹包上",
    "q.l2#6.e" to "腕套的核心價值在滑墜的瞬間：冰鎬一旦脫手，你就失去了唯一能制動的東西。腕套讓你在劇烈顛簸中依然握有冰鎬——這是很多教材反覆強調「戴好腕套」的原因。",
    "q.l2#7.p" to "【多選】選擇冰爪時，需要重點考慮的因素包括？",
    "q.l2#7.o0" to "與靴子的匹配方式（綁帶 / 半卡 / 全卡）",
    "q.l2#7.o1" to "齒數與齒形是否適合目標地形",
    "q.l2#7.o2" to "是否有防滑板（防雪球）",
    "q.l2#7.o3" to "卡扣與綁帶的可靠性",
    "q.l2#7.o4" to "顏色是否與揹包搭配",
    "q.l2#7.e" to "這四項缺一不可。匹配方式決定能不能裝上，齒形決定適不適合地形（陡冰要前齒，緩雪坡要平齒受力），防滑板決定雪會不會在爪底堆成球，卡扣可靠性決定它會不會在陡坡上掉下來。",
    "q.l2#8.p" to "為什麼每次出發前都要檢查冰爪的綁帶與卡扣？",
    "q.l2#8.o0" to "為了保持裝備整潔",
    "q.l2#8.o1" to "因為冰爪脫落是陡坡上的直接生命威脅",
    "q.l2#8.o2" to "因為綁帶容易老化變色",
    "q.l2#8.o3" to "出於隊伍紀律要求",
    "q.l2#8.e" to "冰爪脫落往往發生在最糟的時刻——陡坡上、橫切時、負重的第一步。一旦一隻腳失去附著力，重心立刻偏移。檢查成本幾乎為零，代價卻完全不對等。",
    "q.l2#9.p" to "關於冰鎬鎬尖的形態，下列說法正確的是？",
    "q.l2#9.o0" to "所有冰鎬鎬尖都是直的",
    "q.l2#9.o1" to "彎齒鎬尖更利於入冰且不易脫出，多用於技術攀冰",
    "q.l2#9.o2" to "彎齒鎬尖只適合雪坡行走",
    "q.l2#9.o3" to "鎬尖形態與用途無關",
    "q.l2#9.e" to "長冰鎬的鎬尖一般向下彎曲，揮動或自我制動時容易進入雪面、不易脫出；而攀冰用冰鎬的鎬尖更鋒利、角度更陡，便於在陡峭冰面上快速入冰並容易取出。用途決定形態。",
    // ---------- q.l3 ----------
    "q.l3#0.p" to "雙層高山靴相對單層靴的主要優勢是？",
    "q.l3#0.o0" to "更輕便",
    "q.l3#0.o1" to "更保暖，且內靴可取出烘乾",
    "q.l3#0.o2" to "更便宜",
    "q.l3#0.o3" to "更容易穿脫",
    "q.l3#0.e" to "雙層靴的內靴可以取出，夜間貼身或睡袋內烘乾，避免內靴結冰——這是多日高海拔行程的關鍵。代價是更重、更貴。",
    "q.l3#1.p" to "選擇雪鏡最核心的指標是？",
    "q.l3#1.o0" to "鏡片顏色深淺",
    "q.l3#1.o1" to "UV400 紫外線防護",
    "q.l3#1.o2" to "鏡框品牌",
    "q.l3#1.o3" to "鏡片是否反光",
    "q.l3#1.e" to "雪面反射會顯著增加紫外線暴露。UV400 表示幾乎完全阻隔紫外線，是防止雪盲的關鍵指標；顏色深淺隻影響視覺舒適度。",
    "q.l3#2.p" to "高山靴尺碼選擇的要點是？",
    "q.l3#2.o0" to "越緊越好，防止滑動",
    "q.l3#2.o1" to "腳趾不頂靴頭，留少量空間避免下坡撞傷",
    "q.l3#2.o2" to "越大越好，方便加襪子",
    "q.l3#2.o3" to "與日常鞋碼完全相同即可",
    "q.l3#2.e" to "下坡時腳會向前衝。如果腳趾頂到靴頭，長時間下撤會造成趾甲瘀血甚至脫落。正確做法是留少量空間，並用鞋帶系統鎖住腳跟。",
    "q.l3#3.p" to "8000 公尺級登頂靴最關鍵的設計特徵是？",
    "q.l3#3.o0" to "越輕越好",
    "q.l3#3.o1" to "可拆卸保暖內膽，配合防水防風耐磨鞋面",
    "q.l3#3.o2" to "必須是單層設計",
    "q.l3#3.o3" to "鞋底越軟越舒適",
    "q.l3#3.e" to "可拆卸內膽讓你能在夜間把內靴取出烘乾或貼身保暖，避免內靴結冰——這是多日高海拔行程中腳部保暖的關鍵。鞋面通常為三層壓膠，兼顧防水、防風與耐磨。",
    "q.l3#4.p" to "為什麼貼身層（內衣）應當避免棉質？",
    "q.l3#4.o0" to "棉質太貴",
    "q.l3#4.o1" to "棉吸汗後不易幹，潮溼貼身會加速失溫",
    "q.l3#4.o2" to "棉質會引起過敏",
    "q.l3#4.o3" to "棉質不透氣所以更冷",
    "q.l3#4.e" to "貼身層的任務是把汗從皮膚帶走。棉纖維吸水後幾乎不排水，溼冷貼在皮膚上會持續帶走熱量。應選滌綸或美利奴羊毛等能快速排汗的材料。",
    "q.l3#5.p" to "6000 公尺級高山靴的推薦材質是？",
    "q.l3#5.o0" to "普通皮革",
    "q.l3#5.o1" to "GORE-TEX 等防水透氣材質",
    "q.l3#5.o2" to "純棉織物",
    "q.l3#5.o3" to "塑膠硬殼",
    "q.l3#5.e" to "6000 公尺級高山靴強調輕便、舒適與抓地力，同時要能長時間徒步。GORE-TEX 等防水透氣膜在保證不進水的同時讓汗氣排出——如果只防水不透氣，靴內會自己積汗，同樣是潮溼致冷。",
    "q.l3#6.p" to "高山襪應該避免什麼材質？",
    "q.l3#6.o0" to "美利奴羊毛",
    "q.l3#6.o1" to "滌綸等合成纖維",
    "q.l3#6.o2" to "棉",
    "q.l3#6.o3" to "錦綸",
    "q.l3#6.e" to "與貼身內衣同理：棉吸汗後幾乎不排水，溼冷貼在腳上會持續帶走熱量，還大幅增加水泡風險。高山襪應選合成纖維（不含棉）或美利奴羊毛，並選擇加長款式以兼顧保暖與足部血液迴圈。",
    "q.l3#7.p" to "關於雪套（綁腿）的選擇，正確的做法是？",
    "q.l3#7.o0" to "所有行程都用同一款短雪套",
    "q.l3#7.o1" to "高海拔山峰建議使用較長款，防止雪進入靴子",
    "q.l3#7.o2" to "雪套只在下雨時使用",
    "q.l3#7.o3" to "雪套越短越輕便越好",
    "q.l3#7.e" to "雪套是管狀織物套在靴外，防止雪與雜物進入靴子。高海拔積雪深，短款會很快被埋住而失效，因此建議用長款；短款則適合知名徒步路線與阿爾卑斯式的淺雪環境。",
    "q.l3#8.p" to "營地靴與拖鞋的主要作用與要求是？",
    "q.l3#8.o0" to "用於登頂，必須很硬",
    "q.l3#8.o1" to "用於營地內活動，要求保暖、防水、防滑",
    "q.l3#8.o2" to "用於技術攀爬，需要前齒",
    "q.l3#8.o3" to "只是裝飾，可帶可不帶",
    "q.l3#8.e" to "這是「讓主靴休息」的裝備：進帳篷換上營地靴或拖鞋，可以讓高山靴內膽乾燥、避免腳部長時間受壓。它不承擔技術功能，但直接影響你第二天的腳部狀態。",
    "q.l3#9.p" to "襪子選擇「加長設計」在長途探險中的意義是？",
    "q.l3#9.o0" to "顯得更專業",
    "q.l3#9.o1" to "保暖的同時促進足部血液迴圈",
    "q.l3#9.o2" to "便於穿脫",
    "q.l3#9.o3" to "增加緩衝厚度",
    "q.l3#9.e" to "長途行走時足部容易腫脹、血流變差。加長襪能覆蓋到小腿，既保暖又透過均勻的壓力分佈幫助靜脈迴流——這在連續多日的行程裡，直接關係到腳會不會在第三天就撐不住。",
    // ---------- q.l4 ----------
    "q.l4#0.p" to "踢步（kick steps）時正確的做法是？",
    "q.l4#0.o0" to "大步跨越，減少步數",
    "q.l4#0.o1" to "用小步、均勻節奏踢出臺階，保持重心穩定",
    "q.l4#0.o2" to "只用腳尖點地",
    "q.l4#0.o3" to "全程用腳跟砸雪面",
    "q.l4#0.e" to "小步與均勻節奏能維持重心穩定、減少能量浪費。大步跨越會讓重心大幅擺動，在雪坡上是最容易失穩的走法。",
    "q.l4#1.p" to "行進時冰鎬應該握在哪隻手上？",
    "q.l4#1.o0" to "下坡側的手",
    "q.l4#1.o1" to "上坡側的手，隨時可轉入制動",
    "q.l4#1.o2" to "雙手都不握",
    "q.l4#1.o3" to "掛在揹包外面",
    "q.l4#1.e" to "上坡側的手握鎬（柺杖式 piolet canne），鎬尖朝後、鎬頭朝前。一旦失穩，可以直接下壓轉入自我制動，無需換手——換手的那幾秒往往就是事故窗口。",
    "q.l4#2.p" to "上坡時緩解高原呼吸困難的技巧是？",
    "q.l4#2.o0" to "憋氣前進",
    "q.l4#2.o1" to "壓力呼吸：深吸並用力撥出，與步頻同步",
    "q.l4#2.o2" to "快速淺呼吸",
    "q.l4#2.o3" to "用嘴咬住手套呼吸",
    "q.l4#2.e" to "壓力呼吸透過主動用力呼氣增加肺內正壓，提高氣體交換效率，配合步頻（如每兩到三步一次呼吸）可顯著減輕高海拔的憋悶感。",
    "q.l4#3.p" to "隊伍在雪坡上行進時，踢臺階的正確做法是？",
    "q.l4#3.o0" to "每人各踢一路臺階",
    "q.l4#3.o1" to "前排隊員按均勻節奏踢出臺階，後續隊員踩同一臺階",
    "q.l4#3.o2" to "誰都可以隨意踢",
    "q.l4#3.o3" to "儘量踢得又深又大",
    "q.l4#3.e" to "統一臺階能大幅降低後續隊員的體力消耗，也讓隊伍保持一致的路線與節奏。臺階踢得平整、間距均勻，本身就是團隊效率與安全的體現。",
    "q.l4#4.p" to "高海拔行進中，節奏控制的核心原則是？",
    "q.l4#4.o0" to "儘量快，早到早休息",
    "q.l4#4.o1" to "保持可持續的勻速，避免頻繁的爆發式用力",
    "q.l4#4.o2" to "時快時慢以節省體力",
    "q.l4#4.o3" to "只看隊友速度，不用管自己",
    "q.l4#4.e" to "高海拔供氧能力受限，頻繁的爆發式用力會迅速堆積乳酸並加重缺氧。穩定勻速配合壓力呼吸能讓你走得更遠，也讓隊伍不會因某個人衝刺而被打亂。",
    "q.l4#5.p" to "隊伍在雪坡上的行進節奏應該由誰決定？",
    "q.l4#5.o0" to "隊伍中體能最好的人",
    "q.l4#5.o1" to "按最慢的隊員調整，讓全隊保持在一起",
    "q.l4#5.o2" to "領隊按計劃時間硬性規定",
    "q.l4#5.o3" to "每個人各自按自己的節奏走",
    "q.l4#5.e" to "雪坡上一旦拉開距離，後方的隊員既失去保護也失去照應；而節奏過快會讓體能差的人在還沒到危險地形時就已耗盡。全隊按最慢者行進，是把安全餘量留給整支隊伍。",
    "q.l4#6.p" to "透過有一定坡度的冰坡時，教材建議的做法是？",
    "q.l4#6.o0" to "照常結組行進即可",
    "q.l4#6.o1" to "架設固定路線繩或交替保護系統，一般不結組行進",
    "q.l4#6.o2" to "加快速度快速透過",
    "q.l4#6.o3" to "卸下冰爪以增加摩擦力",
    "q.l4#6.e" to "冰面制動的成功率遠低於雪面，結組在冰坡上反而可能把整隊帶下去。因此在透過有坡度的冰坡時，正確做法是架設固定路線繩或採用交替保護——用系統提供保護，而不是靠個人制動能力。",
    "q.l4#7.p" to "雪坡上採用「之」字形上升相比直上的主要優勢是？",
    "q.l4#7.o0" to "路程更短",
    "q.l4#7.o1" to "降低單段實際坡度、減少體力消耗",
    "q.l4#7.o2" to "風景更好",
    "q.l4#7.o3" to "不需要使用冰鎬",
    "q.l4#7.e" to "「之」字把陡坡分解成若干段緩坡，讓小腿與踝關節的負擔大幅下降，也更適合使用法式（平齒）技術。代價是路程變長，需要據此調整時間預算——這也是折返時間要留餘量的原因之一。",
    // ---------- q.m01 ----------
    "q.m01#0.p" to "海拔每升高 1000 公尺，氣溫平均下降約多少？",
    "q.m01#0.o0" to "約 1.5℃",
    "q.m01#0.o1" to "約 3℃",
    "q.m01#0.o2" to "約 6.5℃",
    "q.m01#0.o3" to "約 10℃",
    "q.m01#0.e" to "平均每升高 1000 公尺氣溫下降約 6.5℃，這是大氣溫度垂直遞減率。它解釋了雪線的高度，也決定了 5000 公尺級山峰即使在夏天也終年積雪。",
    "q.m01#1.p" to "高海拔缺氧的根本原因是什麼？",
    "q.m01#1.o0" to "空氣裡氧氣的比例變低了",
    "q.m01#1.o1" to "氣壓降低，導致吸入空氣的氧分壓下降",
    "q.m01#1.o2" to "空氣中的氧氣被紫外線分解了",
    "q.m01#1.o3" to "海拔越高空氣越稀薄，氧氣被其他氣體取代",
    "q.m01#1.e" to "這是一個非常普遍的誤解。高海拔空氣裡氧氣的比例依然是約 21%，比例並沒有變。真正變的是氣壓——氣壓降低，同樣體積空氣裡的氧分子總數就少了，氧分壓隨之下降，身體因此得不到足夠的氧。",
    "q.m01#2.p" to "【多選】下列哪些屬於高海拔環境的典型特徵？",
    "q.m01#2.o0" to "氣壓低、氧分壓低",
    "q.m01#2.o1" to "氣溫低、晝夜溫差大",
    "q.m01#2.o2" to "紫外線輻射顯著增強",
    "q.m01#2.o3" to "空氣極其乾燥",
    "q.m01#2.o4" to "空氣含氧比例顯著降低",
    "q.m01#2.e" to "四項都對，而且它們會互相放大：低溫加上缺氧，讓身體同時面對產熱困難和供氧不足；乾燥加上強紫外線，讓呼吸道、皮膚和眼睛都更容易受損。裝備與行程安排必須同時覆蓋這四項。",
    "q.m01#3.p" to "海平面大氣壓約 1013 hPa。5000 公尺處的大氣壓大約是多少？",
    "q.m01#3.o0" to "約 900 hPa",
    "q.m01#3.o1" to "約 700 hPa",
    "q.m01#3.o2" to "約 540 hPa",
    "q.m01#3.o3" to "約 300 hPa",
    "q.m01#3.e" to "5000 公尺處氣壓約為海平面的一半。這意味著每次呼吸只能吸入大約一半的氧分子——身體必須靠加快呼吸與心率來代償，這正是高海拔心率偏快、活動能力下降的物理原因。",
    "q.m01#4.p" to "填空：海拔每升高 1000 公尺，氣溫平均下降約（ ）℃。",
    "q.m01#4.a0" to "6.5",
    "q.m01#4.a1" to "六點五",
    "q.m01#4.e" to "6.5℃／1000 m。這個數字在行程規劃裡很實用：從 3000 公尺大本營走到 5000 公尺，氣溫大約會再低 13℃——這直接決定你帶多厚的羽絨服與睡袋。",
    "q.m01#5.p" to "【排序】把高海拔缺氧的因果鏈按發生順序排列。",
    "q.m01#5.o0" to "氣壓下降，吸入氣氧分壓降低",
    "q.m01#5.o1" to "動脈血氧飽和度下降",
    "q.m01#5.o2" to "身體代償性加快呼吸與心率",
    "q.m01#5.o3" to "持續缺氧可能發展為高山症",
    "q.m01#5.e" to "這條鏈條是高海拔醫學的骨架：環境（氣壓低）→ 生理（血氧低）→ 代償（呼吸心率加快）→ 失代償（高山症）。理解它之後，AMS、HACE、HAPE 就不再是零散知識，而是同一條鏈上不同階段的產物。",
    "q.m01#6.p" to "新雪表面的反射率大約是多少？",
    "q.m01#6.o0" to "約 20%",
    "q.m01#6.o1" to "約 40%",
    "q.m01#6.o2" to "約 60%",
    "q.m01#6.o3" to "約 80%～90%",
    "q.m01#6.e" to "新雪可反射約 80%～90% 的太陽輻射。這意味著雪面上的紫外線暴露幾乎是「雙份」——來自上方直射，加上來自雪面的反射。這就是雪盲與嚴重曬傷在雪山上高發的原因。",
    "q.m01#7.p" to "為什麼在高海拔必須做防曬，而不是「可做可不做」？",
    "q.m01#7.o0" to "因為高海拔太陽離地球更近",
    "q.m01#7.o1" to "因為紫外線隨海拔升高而增強，且雪面會把紫外線反射到臉上",
    "q.m01#7.o2" to "因為高原上臭氧層更薄所以可見光更強",
    "q.m01#7.o3" to "因為低溫會削弱皮膚抵抗力",
    "q.m01#7.e" to "紫外線強度每升高 1000 公尺大約增強 10%～12%，雪面再加一次約 80%～90% 的反射。兩者疊加，暴露量遠超同緯度低海拔地區。防曬霜、唇膏、UV400 雪鏡屬於必需品，不是可選項。",
    "q.m01#8.p" to "高海拔空氣乾燥，最容易被忽略的直接後果是？",
    "q.m01#8.o0" to "皮膚變好",
    "q.m01#8.o1" to "呼吸與出汗造成的隱性失水，加重脫水與高反症狀",
    "q.m01#8.o2" to "食慾增強",
    "q.m01#8.o3" to "睡眠變深",
    "q.m01#8.e" to "高海拔空氣乾燥加上呼吸加快，會持續帶走呼吸道水分，而且這種失水往往沒有明顯口渴感。脫水會讓血液黏稠、加重缺氧感受與頭痛，因此規律飲水是高海拔適應的一部分，而不是附帶事項。",
    "q.m01#9.p" to "【多選】下列哪些屬於高海拔環境直接造成的損傷？",
    "q.m01#9.o0" to "曬傷",
    "q.m01#9.o1" to "雪盲",
    "q.m01#9.o2" to "脫水",
    "q.m01#9.o3" to "唇部乾裂",
    "q.m01#9.o4" to "腳踝扭傷",
    "q.m01#9.e" to "四項都屬於環境性損傷，而且共同點是「幾乎完全可以預防」。它們不像雪崩那樣難以預判，純粹取決於裝備與習慣——所以這類損傷出現在隊伍裡，通常說明準備環節出了問題。",
    "q.m01#10.p" to "關於高海拔空氣成分，下列說法正確的是？",
    "q.m01#10.o0" to "氧氣比例隨海拔升高而降低",
    "q.m01#10.o1" to "氧氣比例基本不變，是氣壓降低使氧分壓下降",
    "q.m01#10.o2" to "氮氣比例隨海拔升高而升高",
    "q.m01#10.o3" to "海拔越高，空氣中氧氣被其他氣體擠出",
    "q.m01#10.e" to "空氣的成分比例在對流層內基本恆定（氧約 21%、氮約 78%）。真正隨海拔變化的是氣壓，也就是「同樣一口空氣裡有多少分子」。把這個區別想清楚，很多裝備與生理問題都會變得容易理解。",
    "q.m01#11.p" to "為什麼 5000 公尺級山峰在夏天依然積雪？",
    "q.m01#11.o0" to "因為海拔高處距離太陽更遠",
    "q.m01#11.o1" to "因為高海拔氣溫顯著低於同緯度低地，降水以雪的形式存在",
    "q.m01#11.o2" to "因為山頂風大所以不化",
    "q.m01#11.o3" to "因為積雪被壓實成冰後不會再融化",
    "q.m01#11.e" to "每升高 1000 公尺降約 6.5℃ 的規律，讓 5000 公尺處的夏季氣溫依然低於冰點。這也解釋了為什麼同一座山冬季與夏季的雪況差異直接影響攀登難度——雪線在變，路線也在變。",
    "q.m01#12.p" to "從海拔 3,000 公尺的大本營上到 5,000 公尺的營地，按平均遞減率計算，氣溫大約下降多少攝氏度？",
    "q.m01#12.a0" to "13",
    "q.m01#12.e" to "13℃。演算法：海拔差 2,000 公尺，每 1,000 公尺降 6.5℃，即 2 × 6.5 = 13℃。這個推算在行前非常實用——它直接決定你要帶多厚的保暖層與睡袋。",
    // ---------- q.m02 ----------
    "q.m02#0.p" to "高海拔攀登最需要的體能是？",
    "q.m02#0.o0" to "爆發力與短距離衝刺能力",
    "q.m02#0.o1" to "長時間持續輸出的有氧耐力",
    "q.m02#0.o2" to "最大握力",
    "q.m02#0.o3" to "柔韌性",
    "q.m02#0.e" to "高海拔攀登是典型的長時段低強度運動：一天走 6～10 小時，坡度不陡但持續。缺氧環境下無氧能力被大幅壓縮，真正支撐你走完的是有氧基礎與穩定的配速能力。",
    "q.m02#1.p" to "出發前的訓練安排，比較合理的做法是？",
    "q.m02#1.o0" to "出發前一週加大訓練量，臨陣磨槍",
    "q.m02#1.o1" to "提前 2～3 周逐步減量，帶著恢復充分的狀態上山",
    "q.m02#1.o2" to "全程保持最大強度訓練到出發前一天",
    "q.m02#1.o3" to "完全不訓練，靠現場適應",
    "q.m02#1.e" to "訓練效果是在恢復期產生的。帶著疲勞上山，會同時削弱你的運動表現和高原適應能力——而高原適應本身就需要消耗體能。提前減量是讓訓練成果真正轉化出來的關鍵一步。",
    "q.m02#2.p" to "在高海拔，飲食上應該以什麼為主？",
    "q.m02#2.o0" to "高脂肪食物",
    "q.m02#2.o1" to "碳水化合物",
    "q.m02#2.o2" to "高蛋白食物",
    "q.m02#2.o3" to "只喝流質",
    "q.m02#2.e" to "碳水在缺氧條件下代謝效率更高、耗氧更少，身體在高海拔也會本能地偏好碳水。這與「高海拔要多吃高熱量脂肪」的直覺相反，背後是氧氣利用效率的現實約束。",
    "q.m02#3.p" to "判斷飲水是否充足，比較實用的參考指標是？",
    "q.m02#3.o0" to "口渴程度",
    "q.m02#3.o1" to "尿液保持清淡",
    "q.m02#3.o2" to "每天固定喝 1 升",
    "q.m02#3.o3" to "體重變化",
    "q.m02#3.e" to "口渴感在高海拔並不可靠——寒冷與缺氧都會鈍化它。尿液顏色與氣味是更直觀的日常指標：清淡說明水分基本夠用，顏色變深、氣味重則提示需要補液。",
    "q.m02#4.p" to "為什麼在高海拔要避免飲酒？",
    "q.m02#4.o0" to "因為酒精會讓人發胖",
    "q.m02#4.o1" to "因為酒精抑制呼吸驅動，加重夜間低氧",
    "q.m02#4.o2" to "因為酒精會加速紫外線損傷",
    "q.m02#4.o3" to "因為山上沒有冰箱",
    "q.m02#4.e" to "酒精與鎮靜類藥物都會抑制呼吸中樞。高海拔的夜間本就容易出現週期性呼吸（呼吸間停），再疊加呼吸抑制，血氧會明顯下滑——這是高山症在夜間加重的重要機制之一。",
    "q.m02#5.p" to "【多選】高海拔行進中補充能量，哪些做法是對的？",
    "q.m02#5.o0" to "少量多次，不等餓透再吃",
    "q.m02#5.o1" to "優先選擇易消化、含水適中的食物",
    "q.m02#5.o2" to "以碳水化合物類為主",
    "q.m02#5.o3" to "一次吃很飽以減少進食次數",
    "q.m02#5.e" to "少量多次既減輕消化負擔，也維持血糖穩定。一次吃很飽在缺氧環境下容易引起腹脹與噁心——而食慾下降本身就是高山症反應的常見表現，靠大餐硬補反而適得其反。",
    "q.m02#6.p" to "在高海拔出現食慾下降，正確的應對是？",
    "q.m02#6.o0" to "不吃，等有胃口再說",
    "q.m02#6.o1" to "主動進食，選擇高碳水、易消化的食物",
    "q.m02#6.o2" to "大量喝咖啡代替進食",
    "q.m02#6.o3" to "只補充電解質",
    "q.m02#6.e" to "食慾下降是高山症反應的一部分，而能量攝入不足又會削弱適應能力，形成惡性迴圈。正確做法是主動、小量、高頻地進食——這不是「有沒有胃口」的問題，而是必要的應對措施。",
    "q.m02#7.p" to "關於高海拔訓練與體能的關係，下列說法正確的是？",
    "q.m02#7.o0" to "體能好就不會高山症",
    "q.m02#7.o1" to "體能好能提升表現，但不能代替適應過程",
    "q.m02#7.o2" to "體能差的人不該上高原",
    "q.m02#7.o3" to "體能越好需要適應的時間越短",
    "q.m02#7.e" to "體能和高原適應是兩條獨立的線。體能好的人在同樣海拔可能感覺更從容，但生理適應仍需要以天為單位的時間——把「我體能好」當成「我不會高反」的依據，是很多意外背後的共同邏輯。",
    "q.m02#8.p" to "【排序】把一次合理的攀登前準備按時間順序排列。",
    "q.m02#8.o0" to "基礎體能訓練（提前 2～3 個月）",
    "q.m02#8.o1" to "逐步減量、保證恢復（出發前 2～3 周）",
    "q.m02#8.o2" to "檢查裝備、核對行程與保險（出發前 1 周）",
    "q.m02#8.o3" to "按計劃適應上升（行程中）",
    "q.m02#8.e" to "順序本身就是方法論：訓練要早，恢復要留，準備要細，適應要慢。這四步裡最容易被打亂的是第三步與第四步——很多人裝備檢查做得很足，卻在山上一心想趕進度，把適應時間壓掉了。",
    "q.m02#9.p" to "補液過量（短時間內喝大量水）在高海拔可能帶來什麼問題？",
    "q.m02#9.o0" to "完全沒影響",
    "q.m02#9.o1" to "稀釋血液電解質，嚴重時引起低鈉血癥",
    "q.m02#9.o2" to "能有效預防肺水腫",
    "q.m02#9.o3" to "可以替代進食",
    "q.m02#9.e" to "「多喝水」不等於「拼命喝水」。短時間內大量進水而不補充電解質，可能稀釋血鈉並引起頭痛、噁心、意識改變——這些症狀與高山症高度相似，容易造成誤判。均勻、適量地補水才是正確做法。",
    // ---------- q.m03 ----------
    "q.m03#0.p" to "「低衝擊法則」的核心含義是？",
    "q.m03#0.o0" to "減少裝備重量以降低對身體的衝擊",
    "q.m03#0.o1" to "把人類活動對山野環境的影響降到最低",
    "q.m03#0.o2" to "降低攀登難度以保障安全",
    "q.m03#0.o3" to "減少隊伍人數",
    "q.m03#0.e" to "低衝擊法則是登山戶外運動倡導的環境保護原則。它關心的不是「你爬得輕不輕」，而是「山野因你改變了多少」——垃圾、踩踏、用火、對野生動物的干擾都算在內。",
    "q.m03#1.p" to "離開營地時，關於垃圾的正確做法是？",
    "q.m03#1.o0" to "廚餘可以就地掩埋",
    "q.m03#1.o1" to "全部攜帶出去，包括衛生紙等清潔用品",
    "q.m03#1.o2" to "只帶走塑膠類垃圾",
    "q.m03#1.o3" to "集中焚燒處理",
    "q.m03#1.e" to "教材的要求很明確：把產生的垃圾包裝起來帶走，並檢查營地及活動區域，衛生紙等清潔用品也須包裝帶走。就地掩埋與焚燒都會留下痕跡，而高海拔低溫環境下垃圾降解極慢。",
    "q.m03#2.p" to "在野外處理排洩物，位置選擇應遵循什麼原則？",
    "q.m03#2.o0" to "越隱蔽越好，考慮隱私優先",
    "q.m03#2.o1" to "遠離水源、營地與步道",
    "q.m03#2.o2" to "選在雪面最平的地方",
    "q.m03#2.o3" to "靠近溪流以便沖刷",
    "q.m03#2.e" to "核心是避免汙染水源與被後來者踩到。實踐中通常要求距水源與步道一定距離，並挖淺坑掩埋、把用過的衛生紙帶走——在雪線以上則應打包帶走，因為低溫下幾乎不分解。",
    "q.m03#3.p" to "為什麼要密封保管食物和垃圾？",
    "q.m03#3.o0" to "防止受潮變質",
    "q.m03#3.o1" to "防止動物翻找與襲擾",
    "q.m03#3.o2" to "節省揹包空間",
    "q.m03#3.o3" to "方便稱重",
    "q.m03#3.e" to "翻找食物的動物往往是被隊伍自己「教出來」的——一旦它們把營地與食物聯絡起來，後續路線的風險就永久升高了。密封保管既保護食物，也保護動物，更保護後面的隊伍。",
    "q.m03#4.p" to "野生動物的「敏感期」主要指的是？",
    "q.m03#4.o0" to "白天的覓食時段",
    "q.m03#4.o1" to "交配期與哺乳期",
    "q.m03#4.o2" to "遷徙季節",
    "q.m03#4.o3" to "冬季休眠期",
    "q.m03#4.e" to "交配期與哺乳期動物對干擾格外敏感，母獸護仔時還可能表現出攻擊性。因此除了避開活動區域，還要避開固定飲水時間與地點——這既是保護它們，也是保護自己。",
    "q.m03#5.p" to "為什麼要堅持走在既有步道上？",
    "q.m03#5.o0" to "因為規定要求",
    "q.m03#5.o1" to "因為踩踏會形成長期存在的新路徑，並引發水土流失",
    "q.m03#5.o2" to "因為步道更好走",
    "q.m03#5.o3" to "因為有嚮導標記",
    "q.m03#5.e" to "高海拔植被生長極慢，一次踩踏的痕跡可能留存數年。多條並行的「捷徑」還會切斷植被、加劇雨水沖刷，最終形成沖溝——路線的退化往往就是這樣開始的。",
    "q.m03#6.p" to "【多選】以下哪些屬於必須帶離山野的垃圾？",
    "q.m03#6.o0" to "食品包裝",
    "q.m03#6.o1" to "果皮與廚餘",
    "q.m03#6.o2" to "用過的衛生紙",
    "q.m03#6.o3" to "菸頭",
    "q.m03#6.o4" to "膠帶與包裝繩可以就地焚燒處理",
    "q.m03#6.e" to "四項都要帶走。這裡最容易誤解的是果皮與廚餘——它們看起來「會降解」，但在低溫乾燥的高山環境裡分解極慢，而且會吸引動物、改變它們的習性。",
    "q.m03#7.p" to "關於收集自然物（石塊、植物、化石）作為紀念品，正確的態度是？",
    "q.m03#7.o0" to "小型物品可以帶走",
    "q.m03#7.o1" to "不帶走自然物，只帶走照片",
    "q.m03#7.o2" to "只要不破壞環境即可",
    "q.m03#7.o3" to "採集標本有助於科研",
    "q.m03#7.e" to "「只帶走照片，只留下腳印」是低衝擊法則的經典表述。自然物是當地生態與地貌的一部分，而且一旦每個隊伍都帶走一點，累積效應非常可觀。",
    "q.m03#8.p" to "登山活動對山區環境的影響，主要表現為？",
    "q.m03#8.o0" to "僅僅是垃圾汙染",
    "q.m03#8.o1" to "植被破壞、野生動物活動範圍縮小、垃圾汙染，以及外來文化對當地居民的衝擊",
    "q.m03#8.o2" to "主要是噪音問題",
    "q.m03#8.o3" to "影響可以忽略不計",
    "q.m03#8.e" to "教材把影響分為生態與社會兩層：生態上是植被破壞、動物遷徙與垃圾汙染；社會上是外來文化對當地生活方式的衝擊。理解這一點，才能明白「禮儀」為什麼也是登山訓練的一部分。",
    "q.m03#9.p" to "【排序】把一次離開營地的環保流程按正確順序排列。",
    "q.m03#9.o0" to "收拾個人與公共裝備",
    "q.m03#9.o1" to "把所有垃圾分類打包",
    "q.m03#9.o2" to "處理排洩物（掩埋或打包）",
    "q.m03#9.o3" to "巡視營地與活動區域，確認無遺留",
    "q.m03#9.e" to "最後一步「巡視」最容易被跳過，也最關鍵：人離開時會下意識只帶走「自己的東西」，而帳篷釘、繩子頭、掉落的食品包裝往往就是這樣留下的。回頭看一眼，成本幾乎為零。",
    // ---------- q.m04 ----------
    "q.m04#0.p" to "判斷天氣轉壞，最可靠的依據是？",
    "q.m04#0.o0" to "此刻是否晴天",
    "q.m04#0.o1" to "氣壓、雲層與風力變化的趨勢",
    "q.m04#0.o2" to "出發前的天氣預報",
    "q.m04#0.o3" to "同行者的感覺",
    "q.m04#0.e" to "「當下」是快照，「趨勢」才是方向。氣壓持續下降、雲層變厚變低、風力增強——這三項同時出現時，基本可以確定天氣在轉壞。這也是帶氣壓計（高度計手錶）的實用價值。",
    "q.m04#1.p" to "積雨雲的典型特徵與含義是？",
    "q.m04#1.o0" to "薄而均勻，天氣穩定",
    "q.m04#1.o1" to "垂直髮展、頂部呈砧狀，預示雷暴與強降水",
    "q.m04#1.o2" to "呈層狀鋪開，只帶來毛毛雨",
    "q.m04#1.o3" to "呈絲縷狀，預示好天氣",
    "q.m04#1.e" to "積雨雲的垂直髮展說明對流強烈，頂部被高空風吹成砧狀則說明已經發展到成熟階段。在高海拔遇上它，意味著雷電、冰雹與強降水都可能出現——應當立即離開暴露的山脊與高處。",
    "q.m04#2.p" to "登山中常用的地形圖比例尺是？",
    "q.m04#2.o0" to "1:1000 與 1:5000",
    "q.m04#2.o1" to "1:50000 與 1:10000",
    "q.m04#2.o2" to "1:250000 與 1:500000",
    "q.m04#2.o3" to "任意比例尺都可以",
    "q.m04#2.e" to "1:50000 與 1:10000 是登山常用比例尺，前者覆蓋範圍大、適合行程規劃，後者細節豐富、適合技術地形。1:200000 偶爾使用，而 1:10000 用得更少——因為一張圖的範圍太小，很快就走出圖外了。",
    "q.m04#3.p" to "地形圖上等高線密集，表示該處？",
    "q.m04#3.o0" to "坡度平緩",
    "q.m04#3.o1" to "坡度陡峭",
    "q.m04#3.o2" to "是山谷",
    "q.m04#3.o3" to "有冰川",
    "q.m04#3.e" to "等高線越密，說明相同水平距離內的高差越大，也就是越陡。這項判讀能力在規劃路線時很實用：可以在出發前就把陡坡段、平臺與可能的營地位置標出來。",
    "q.m04#4.p" to "地形圖上出現閉合的等高線，表示什麼？",
    "q.m04#4.o0" to "一個湖泊",
    "q.m04#4.o1" to "一座獨立山體",
    "q.m04#4.o2" to "一條冰川",
    "q.m04#4.o3" to "一處斷崖",
    "q.m04#4.e" to "閉合等高線意味著山體四周都有獨立的下坡輪廓，這正是「獨立山峰」的定義依據。多個同心閉合圈則代表山體逐級升高，最內圈就是峰頂所在區域。",
    "q.m04#5.p" to "【多選】使用指北針（羅盤）時，需要注意的事項有？",
    "q.m04#5.o0" to "儘量保持水平",
    "q.m04#5.o1" to "不要離磁性物質太近",
    "q.m04#5.o2" to "勿將磁針 S 端誤作北方",
    "q.m04#5.o3" to "按活動地區的磁偏角進行校正",
    "q.m04#5.o4" to "儘量貼近揹包金屬扣以保持穩定",
    "q.m04#5.e" to "這四條都是教材明確列出的注意事項。其中「S 端誤作北方」會造成 180° 的方向誤差——在地形複雜時這類錯誤可能讓人朝完全相反的方向走，且很難自行察覺。",
    "q.m04#6.p" to "什麼是磁偏角？",
    "q.m04#6.o0" to "指北針本身的製造誤差",
    "q.m04#6.o1" to "磁北與真北之間的偏差，需要校正",
    "q.m04#6.o2" to "海拔升高帶來的角度變化",
    "q.m04#6.o3" to "地圖投影造成的變形",
    "q.m04#6.e" to "磁針指向磁北，而地圖通常以真北為基準，兩者之間存在偏差。不同地區磁偏角不同，使用地圖與指北針配合定位時必須校正，否則路線會整體偏移。",
    "q.m04#7.p" to "地形圖上整齊的方格線代表什麼？",
    "q.m04#7.o0" to "經緯線",
    "q.m04#7.o1" to "UTM（通用橫軸墨卡託投影）方格線",
    "q.m04#7.o2" to "等高線",
    "q.m04#7.o3" to "行政邊界",
    "q.m04#7.e" to "地圖上的方格線並不是經緯線，而是 UTM 格式的方格線。理解這一點很重要：因為地球是橢球體，經緯網格在不同緯度並不等大，而 UTM 方格是等大的，便於直接量算距離與座標。",
    "q.m04#8.p" to "為什麼不能只依賴 GPS 導航？",
    "q.m04#8.o0" to "因為 GPS 精度不夠",
    "q.m04#8.o1" to "因為裝置可能沒電、進水、損壞或失去訊號",
    "q.m04#8.o2" to "因為 GPS 只適用於城市",
    "q.m04#8.o3" to "因為 GPS 需要付費",
    "q.m04#8.e" to "GPS 是極好的輔助工具，但它的前提是「裝置可用」。在高海拔低溫下電池衰減很快，進水與摔落也很常見。地圖與指北針不需要電，這也是為什麼它們至今仍是登山訓練的必修內容。",
    "q.m04#9.p" to "在能見度迅速惡化（起霧、白化）時，最應該優先做的是？",
    "q.m04#9.o0" to "加快速度儘快走完",
    "q.m04#9.o1" to "立即確認自己的位置與朝向，必要時原地等待",
    "q.m04#9.o2" to "繼續按原計劃直走",
    "q.m04#9.o3" to "分散尋找路線",
    "q.m04#9.e" to "白化（whiteout）最危險的地方在於失去所有視覺參照，人會本能地沿錯誤方向前進。此時先定位、記錄方向、必要時原地等待，遠比硬走安全——分散尋找更是要避免。",
    // ---------- q.m05 ----------
    "q.m05#0.p" to "「徒步型」與「技術型」山峰的核心區別在於？",
    "q.m05#0.o0" to "海拔高低",
    "q.m05#0.o1" to "是否需要技術裝備與相應的技術操作",
    "q.m05#0.o2" to "所在國家",
    "q.m05#0.o3" to "是否需要許可",
    "q.m05#0.e" to "分界線是技術要求，而不是高度。5,895 m 的乞力馬紮羅不需要技術裝備，而 5,396 m 的哈巴雪山雪線以上就需要冰爪與冰鎬——海拔只是難度的一個維度。",
    "q.m05#1.p" to "乞力馬紮羅的最高點叫什麼？",
    "q.m05#1.o0" to "烏呼魯峰",
    "q.m05#1.o1" to "基博峰",
    "q.m05#1.o2" to "馬文濟峰",
    "q.m05#1.o3" to "希拉峰",
    "q.m05#1.e" to "最高點是烏呼魯峰（Uhuru Peak，5,895 m）。乞力馬紮羅是一座休眠火山，由基博、馬文濟、希拉三個火山錐組成，其中基博峰最高，而烏呼魯峰是基博峰的最高點。",
    "q.m05#2.p" to "乞力馬紮羅最獨特的地方是？",
    "q.m05#2.o0" to "它是世界上攀登人數最少的 5000 公尺峰",
    "q.m05#2.o1" to "它位於赤道附近卻有冰川，沿途跨越熱帶雨林到高山荒漠的多個氣候帶",
    "q.m05#2.o2" to "它需要極強的技術裝備",
    "q.m05#2.o3" to "它全年只有一個月可以攀登",
    "q.m05#2.e" to "赤道 + 冰川的組合，讓乞力馬紮羅成為一條「垂直的氣候走廊」：一天之內從雨林走到冰川。這也帶來一個現實問題——行程跨度大，海拔上升快，高原適應反而成了主要挑戰。",
    "q.m05#3.p" to "奧太娜屬於哪一組雪山？",
    "q.m05#3.o0" to "四姑娘山",
    "q.m05#3.o1" to "三奧雪山",
    "q.m05#3.o2" to "貢嘎山",
    "q.m05#3.o3" to "梅里雪山",
    "q.m05#3.e" to "三奧雪山由奧太基（群山之父）、奧太美（群山之母）、奧太娜（群山之子）三座山峰組成，位於四川黑水。奧太娜是三座中最容易的一座，也是常被選為「人生第一座雪山」的對象。",
    "q.m05#4.p" to "關於奧太娜的海拔，下列哪項描述是準確的？",
    "q.m05#4.o0" to "所有資料都一致標註為 4,800 m",
    "q.m05#4.o1" to "官方海拔 5,211 m，但實測約 4,800 m，不同來源資料存在差異",
    "q.m05#4.o2" to "官方海拔 4,800 m，實測 5,211 m",
    "q.m05#4.o3" to "海拔資料從未有過爭議",
    "q.m05#4.e" to "這類差異在山峰資料裡很常見：官方公佈值、實測值與不同時期的測繪標準都可能不同。實際意義是——引用任何山峰資料時都應註明來源，而不是把某一個數字當作絕對真理。",
    "q.m05#5.p" to "四姑娘山大峰與二峰的海拔分別是？",
    "q.m05#5.o0" to "5,025 m 與 5,276 m",
    "q.m05#5.o1" to "5,276 m 與 5,025 m",
    "q.m05#5.o2" to "5,025 m 與 5,355 m",
    "q.m05#5.o3" to "4,850 m 與 5,276 m",
    "q.m05#5.e" to "大峰 5,025 m、二峰 5,276 m。兩者常被作為入門組合：先上大峰積累高海拔經驗，再上二峰——二峰最後一段需要簡單器械輔助，正好是走向技術攀登的過渡。",
    "q.m05#6.p" to "【多選】選擇第一座雪山時，最值得比較的因素是？",
    "q.m05#6.o0" to "路線成熟度與登頂率",
    "q.m05#6.o1" to "嚮導與救援資源是否可靠",
    "q.m05#6.o2" to "海拔上升節奏是否合理",
    "q.m05#6.o3" to "自身當前體能與可投入的時間",
    "q.m05#6.o4" to "山峰在社交平臺上的熱度",
    "q.m05#6.e" to "這四項構成了「這座山適不適合現在的我」這個問題的完整答案。只看海拔數字容易誤判：一座 5,000 公尺但上升節奏合理、後援可靠的山，可能比一座 5,500 公尺卻要連趕三天的山更安全。",
    "q.m05#7.p" to "入門山峰登頂失敗，最常見的原因是？",
    "q.m05#7.o0" to "技術難度過高",
    "q.m05#7.o1" to "高山症反應與天氣，而不是技術難度",
    "q.m05#7.o2" to "裝備不足",
    "q.m05#7.o3" to "隊伍人數不夠",
    "q.m05#7.e" to "這是最容易被低估的一點：入門山峰的失敗，絕大多數發生在「走不動了」或「天氣不等人」，而不是「難點過不去」。所以入門階段真正的功課是適應、節奏與體能，而不是技術動作。",
    "q.m05#8.p" to "為什麼在選擇山峰時要關注「登頂率」這個資料？",
    "q.m05#8.o0" to "因為它代表山峰的風景質量",
    "q.m05#8.o1" to "因為它綜合反映了路線難度、上升節奏與保障條件的現實水平",
    "q.m05#8.o2" to "因為它決定了登山費用",
    "q.m05#8.o3" to "因為它與安全無關",
    "q.m05#8.e" to "登頂率是多項因素的結果：路線難不難、上升節奏是否合理、天氣窗口寬不寬、後勤是否可靠。它比單純的「海拔」更能反映你實際會面對什麼。",
    "q.m05#9.p" to "關於「入門級雪山」的正確態度是？",
    "q.m05#9.o0" to "入門級 = 沒有風險",
    "q.m05#9.o1" to "入門只意味著技術難度低，高原與天氣風險依然真實存在",
    "q.m05#9.o2" to "入門級不需要嚮導",
    "q.m05#9.o3" to "入門級不需要體能準備",
    "q.m05#9.e" to "「入門」描述的是技術門檻，不是風險總量。高海拔本身、突變的天氣、以及體能透支，在任何海拔上都可能致命。把入門理解成「輕鬆」是準備不足的開端。",
    // ---------- q.m06 ----------
    "q.m06#0.p" to "技術攀登的三大基本系統是？",
    "q.m06#0.o0" to "裝備、體能、天氣",
    "q.m06#0.o1" to "制動、保護、行進",
    "q.m06#0.o2" to "上升、下降、休息",
    "q.m06#0.o3" to "冰爪、冰鎬、繩索",
    "q.m06#0.e" to "制動解決「失穩之後怎麼辦」，保護解決「萬一墜落誰來接住」，行進解決「在危險地形上如何移動」。三者構成一個閉環——缺任何一環，技術攀登都不成立。",
    "q.m06#1.p" to "學習技術攀登的根本目的是？",
    "q.m06#1.o0" to "為了攀登更難的路線",
    "q.m06#1.o1" to "把不可控的滑墜變成可控的風險",
    "q.m06#1.o2" to "為了獲得證書",
    "q.m06#1.o3" to "為了走得更快",
    "q.m06#1.e" to "技術本身不會降低山的高度，它改變的是「出錯之後會怎樣」。有了制動，滑墜不再是不可逆的災難；有了保護，一次失誤不會直接等於墜落——這才是技術真正的價值。",
    "q.m06#2.p" to "掌握技術動作最有效的方式是？",
    "q.m06#2.o0" to "反覆觀看教學影片",
    "q.m06#2.o1" to "在有保護的場地上實地反覆練習，直至形成條件反射",
    "q.m06#2.o2" to "閱讀教材並記住要點",
    "q.m06#2.o3" to "在真實陡坡上一次學會",
    "q.m06#2.e" to "技術動作要在壓力下執行，而壓力會讓人退回到訓練過的水平。緩坡、軟雪、下方開闊、有教練保護——這四個條件同時滿足的場地，才是真正學會一門技術的地方。",
    "q.m06#3.p" to "為什麼說「看影片學不會自我制動」？",
    "q.m06#3.o0" to "因為影片畫質不好",
    "q.m06#3.o1" to "因為它是需要在壓力下本能執行的動作，必須靠反覆實地練習形成條件反射",
    "q.m06#3.o2" to "因為影片裡的技術是錯的",
    "q.m06#3.o3" to "因為自我制動其實很簡單",
    "q.m06#3.e" to "滑墜發生後留給你的反應時間只有一兩秒，沒有任何思考餘地。肌肉記憶是靠重複次數換來的——這也是為什麼所有正規培訓都要求「練到不用想就能做出來」。",
    "q.m06#4.p" to "技術裝備入門的三件套是？",
    "q.m06#4.o0" to "頭盔、手套、雪鏡",
    "q.m06#4.o1" to "與靴子配套的冰爪、冰鎬、安全帶",
    "q.m06#4.o2" to "帳篷、睡袋、防潮墊",
    "q.m06#4.o3" to "GPS、對講機、頭燈",
    "q.m06#4.e" to "冰爪提供附著力，冰鎬提供製動與支撐，安全帶把你與保護系統連線起來。三者的共同點是：只有配套、只有與同伴形成系統，才產生安全價值——單件裝備本身保護不了任何人。",
    "q.m06#5.p" to "學會技術動作之後，最重要的能力變成了什麼？",
    "q.m06#5.o0" to "攀爬速度",
    "q.m06#5.o1" to "判斷「什麼時候不需要使用技術裝備」",
    "q.m06#5.o2" to "裝備的維護",
    "q.m06#5.o3" to "體能的進一步提升",
    "q.m06#5.e" to "這是技術攀登裡最反直覺的一點：技術讓人敢於進入更困難的地形，而真正的高手則在用技術換取「可以不走上去」的餘地。判斷力始終高於執行力。",
    "q.m06#6.p" to "【多選】下列哪些屬於技術攀登的範疇？",
    "q.m06#6.o0" to "冰坡行進與制動",
    "q.m06#6.o1" to "結組透過冰川",
    "q.m06#6.o2" to "確保站搭建",
    "q.m06#6.o3" to "繩降下降",
    "q.m06#6.o4" to "在成熟步道上徒步穿越",
    "q.m06#6.e" to "四項都屬於技術攀登：它們都需要裝備、系統與專門訓練的配合。而單純在雪坡上行走、走成熟徒步路線，則不屬於技術攀登——區別就在於是否需要這些系統。",
    "q.m06#7.p" to "為什麼技術能力不能替代判斷力？",
    "q.m06#7.o0" to "因為技術能力無法訓練",
    "q.m06#7.o1" to "因為判斷錯誤會讓你進入本不該進入的地形，技術再好也難以挽回",
    "q.m06#7.o2" to "因為判斷力比技術更容易學",
    "q.m06#7.o3" to "因為技術只適用於攀岩",
    "q.m06#7.e" to "技術是在「已經身處險境」時用的，而判斷決定「要不要進入險境」。大量事故覆盤顯示，問題很少出在「動作沒做對」，而是出在「本來就不該出現在那裡」。",
    "q.m06#8.p" to "【排序】把技術攀登的學習順序按合理邏輯排列。",
    "q.m06#8.o0" to "認識裝備：冰爪、冰鎬、安全帶的結構與使用",
    "q.m06#8.o1" to "在安全場地反覆練習基本動作（如自我制動）",
    "q.m06#8.o2" to "學習繩索系統：繩結、結組、確保站",
    "q.m06#8.o3" to "在真實但又可控的路線中綜合運用",
    "q.m06#8.e" to "這個順序背後是「先會保護自己，再連線別人，最後進入真實環境」。跳過任何一步都會造成能力斷層——比如在沒練熟制動的情況下就結組上冰川，風險會被放大整隊。",
    "q.m06#9.p" to "本單元到此完成了什麼？",
    "q.m06#9.o0" to "完成了全部高山攀登訓練",
    "q.m06#9.o1" to "完成了科普與環境裝備的基礎鋪墊，準備進入技術動作學習",
    "q.m06#9.o2" to "完成了 8000 公尺級準備",
    "q.m06#9.o3" to "完成了救援能力認證",
    "q.m06#9.e" to "5000 公尺入門單元的任務是「把底子打好」：環境科學、裝備、穿著、體能、環保、天氣導航，最後引出技術攀登。下一單元開始正式學習冰爪、冰鎬、制動與繩索。",
    // ---------- q.m07 ----------
    "q.m07#0.p" to "確保站設計的核心思路是？",
    "q.m07#0.o0" to "儘量節省器材",
    "q.m07#0.o1" to "任何一個保護點失效，系統都不應該崩潰",
    "q.m07#0.o2" to "把確保站建在最高的位置",
    "q.m07#0.o3" to "只使用天然保護點",
    "q.m07#0.e" to "岩雪保護點的可靠性無法做到絕對確定，所以系統的設計目標是「容錯」而非「絕對牢固」。理解這一點，後面所有原則（冗餘、均衡、不延展）都只是它的具體展開。",
    "q.m07#1.p" to "兩個保護點夾角為 90° 時，每個點大致承擔多少比例的負荷？",
    "q.m07#1.o0" to "約 50%",
    "q.m07#1.o1" to "約 58%",
    "q.m07#1.o2" to "約 71%",
    "q.m07#1.o3" to "約 100%",
    "q.m07#1.e" to "這是教材表格裡的關鍵資料：夾角 0° 時每點約 50%，60° 時約 58%，90° 時約 71%。夾角越大，同樣一個人掛上去，每個點承受的力就越大——這直接決定了保護點的選擇與佈局。",
    "q.m07#2.p" to "從受力角度看，保護點之間的夾角應該怎麼處理？",
    "q.m07#2.o0" to "儘量小，讓受力方向接近一致",
    "q.m07#2.o1" to "儘量大，分散到不同方向",
    "q.m07#2.o2" to "必須保持 90°",
    "q.m07#2.o3" to "夾角不影響受力",
    "q.m07#2.e" to "夾角越小，兩個點分擔的力道越接近 50/50；夾角一大，每點受力都會上升。實踐中常說的「把扁帶夾角控制在 60° 以內」，正是基於這組資料得出的經驗值。",
    "q.m07#3.p" to "【多選】評估一個確保站時，應該考慮的維度包括？",
    "q.m07#3.o0" to "牢固：每個點的強度足夠",
    "q.m07#3.o1" to "冗餘：多個彼此獨立的保護點",
    "q.m07#3.o2" to "均衡：負荷合理分配",
    "q.m07#3.o3" to "不延展：某點失效時不產生衝擊性延展",
    "q.m07#3.o4" to "對稱：佈局整齊、視覺平衡",
    "q.m07#3.e" to "這四項就是確保站評估的基本框架。其中「不延展」最容易被忽略：點與點之間留了松餘，某點崩脫時其餘點會承受突然的衝擊載荷。衝擊力遠大於靜載，很多人想不到這一點。",
    "q.m07#4.p" to "【配對】把保護點型別與它對應的介質與做法對應起來。",
    "q.m07#4.l0" to "天然保護點",
    "q.m07#4.l1" to "雪地保護點",
    "q.m07#4.l2" to "冰面保護點",
    "q.m07#4.r0" to "岩柱、大樹、大石——需確認其完整性與穩固度",
    "q.m07#4.r1" to "雪錐、死掛、T 型雪槽——可靠性高度依賴雪質與埋設質量",
    "q.m07#4.r2" to "冰錐——需確認冰體密實、無空腔或蜂窩化",
    "q.m07#4.e" to "三類介質對應三套完全不同的判斷標準。最常見的事故原因之一，就是拿岩壁經驗去判斷雪地或冰面——例如「看起來挺結實」在雪地裡幾乎不能作為依據。",
    "q.m07#5.p" to "下列哪種做法屬於「假冗餘」？",
    "q.m07#5.o0" to "使用強度不同的兩種器材",
    "q.m07#5.o1" to "兩個保護點實際依賴同一條岩縫或同一塊岩體",
    "q.m07#5.o2" to "保護點之間用扁帶連線",
    "q.m07#5.o3" to "設定了三個保護點",
    "q.m07#5.e" to "冗餘的本質要求是「獨立失效」。如果兩點共用同一條岩縫，岩縫崩開時兩點同時失效——形式上像「兩點」，實際只有一點。這是很常見、也很致命的假冗餘。",
    "q.m07#6.p" to "為什麼要預先收緊、做到「不延展」？",
    "q.m07#6.o0" to "美觀整齊",
    "q.m07#6.o1" to "避免某點失效時其餘點承受突然的衝擊載荷",
    "q.m07#6.o2" to "節省扁帶長度",
    "q.m07#6.o3" to "便於快速拆除",
    "q.m07#6.e" to "衝擊載荷遠大於靜載——同樣一個人，突然受力比靜止懸掛產生的力大得多。留有松餘的確保站，看似「更靈活」，實際上是把一次失效放大成了對整個系統的衝擊。",
    "q.m07#7.p" to "【排序】把搭建確保站的步驟按合理順序排列。",
    "q.m07#7.o0" to "觀察周圍，選出可用且相互獨立的保護點位置",
    "q.m07#7.o1" to "逐個設定保護點，並確認每個點自身牢固",
    "q.m07#7.o2" to "用扁帶/繩索連線各點，控制夾角並預先收緊",
    "q.m07#7.o3" to "檢查整個系統，確認無假冗餘、無延展",
    "q.m07#7.e" to "順序背後是「先選位置、再做單點、然後連繫統、最後做複核」。把複核放在最後不是形式——搭的過程中你會專注於每個點的操作，反而容易忽略整體關係（比如兩點其實同源）。",
    "q.m07#8.p" to "使用天然保護點時，最需要確認的是什麼？",
    "q.m07#8.o0" to "它是不是足夠大",
    "q.m07#8.o1" to "它的完整性——是否鬆動、風化或與主體分離",
    "q.m07#8.o2" to "它是不是好看",
    "q.m07#8.o3" to "它是不是好掛扁帶",
    "q.m07#8.e" to "天然點的危險往往在於「看起來很大但已經鬆動」。判斷重點是它與主體是否真正連為一體、岩體是否有裂縫與風化跡象。大、粗、顯眼都不等於牢固。",
    "q.m07#9.p" to "為什麼確保站要儘量搭得快？",
    "q.m07#9.o0" to "為了節省體力",
    "q.m07#9.o1" to "因為搭建過程本身就是暴露在風險中的時間",
    "q.m07#9.o2" to "因為隊友會催促",
    "q.m07#9.o3" to "因為裝備容易丟失",
    "q.m07#9.e" to "搭建確保站時你往往處於無保護或保護不足的狀態——這段「暴露時間」越短越好。這就是確保站評估裡除了牢固、冗餘、均衡之外，還要看「效率」與「及時性」的原因。",
    "q.m07#10.p" to "雪地保護點的可靠性主要取決於什麼？",
    "q.m07#10.o0" to "器材品牌",
    "q.m07#10.o1" to "雪質與埋設質量",
    "q.m07#10.o2" to "海拔高度",
    "q.m07#10.o3" to "繩索顏色",
    "q.m07#10.e" to "同樣的雪錐或死掛，在深雪、溼雪與雪橋邊緣的承載能力差異極大。雪地保護點必須現場判斷雪層結構，而不能照搬固定流程——這也讓雪地保護成為技術含量最高的部分之一。",
    "q.m07#11.p" to "如果一個確保站只有單一保護點，最大的問題是什麼？",
    "q.m07#11.o0" to "受力太大",
    "q.m07#11.o1" to "沒有任何容錯——該點失效即等於系統失效",
    "q.m07#11.o2" to "不好操作",
    "q.m07#11.o3" to "不美觀",
    "q.m07#11.e" to "單點確保站意味著「把命完全交給一個不確定的因素」。現實中有時確實只能用單點（例如只有一個可靠冰錐），此時的做法是把它做得儘可能可靠，並儘量減少系統在它上面的暴露時間。",
    // ---------- q.m08 ----------
    "q.m08#0.p" to "崗什卡主峰的海拔是？",
    "q.m08#0.o0" to "5,005 m",
    "q.m08#0.o1" to "5,150 m",
    "q.m08#0.o2" to "5,254.5 m",
    "q.m08#0.o3" to "5,396 m",
    "q.m08#0.e" to "主峰 5,254.5 m。注意這組數字的層級：三峰 5,005 m < 衛峰 5,150 m < 主峰 5,254.5 m——三個高度對應三種難度，這也是崗什卡常被當作「循序進階」目標的原因。",
    "q.m08#1.p" to "崗什卡三峰的海拔與定位是？",
    "q.m08#1.o0" to "5,005 m，初級技術型，新手登頂率約 95%",
    "q.m08#1.o1" to "5,254 m，高難度技術型",
    "q.m08#1.o2" to "5,150 m，純徒步型",
    "q.m08#1.o3" to "5,396 m，冰川型",
    "q.m08#1.e" to "三峰 5,005 m，屬於初級技術型。新手登頂率約 95%，說明路線難度可控、後勤成熟，很適合第一次真正穿上技術裝備。",
    "q.m08#2.p" to "崗什卡主峰在地理上的意義是？",
    "q.m08#2.o0" to "崑崙山脈最高峰",
    "q.m08#2.o1" to "祁連山脈東段的最高峰",
    "q.m08#2.o2" to "青藏高原最高峰",
    "q.m08#2.o3" to "橫斷山脈最高峰",
    "q.m08#2.e" to "崗什卡是祁連山脈東段的最高峰，位於青海省海北州門源縣。它也是國內距離城市最近的高海拔雪山之一——交通可達性直接影響了它作為訓練峰的普及度。",
    "q.m08#3.p" to "崗什卡三峰的徒步距離與大致耗時是？",
    "q.m08#3.o0" to "約 3 km / 2 小時",
    "q.m08#3.o1" to "約 10 km / 6 小時",
    "q.m08#3.o2" to "約 25 km / 兩天",
    "q.m08#3.o3" to "約 1 km / 30 分鐘",
    "q.m08#3.e" to "約 10 km、約 6 小時。這個強度正好適合作為第一次技術攀登的目標：不是靠長時間消耗取勝，而是把精力集中在技術操作與判斷上。",
    "q.m08#4.p" to "哈巴雪山的海拔是？",
    "q.m08#4.o0" to "5,005 m",
    "q.m08#4.o1" to "5,254 m",
    "q.m08#4.o2" to "5,396 m",
    "q.m08#4.o3" to "5,642 m",
    "q.m08#4.e" to "哈巴雪山 5,396 m，位於雲南香格里拉。它的價值在於——雪線以上有真實冰坡，需要冰爪與冰鎬，但又不像 6000 公尺級那樣伴隨嚴格的高原適應壓力。",
    "q.m08#5.p" to "哈巴雪山對攀登者的技術要求主要體現在？",
    "q.m08#5.o0" to "需要攀岩能力",
    "q.m08#5.o1" to "雪線以上有冰坡，需要冰爪與冰鎬",
    "q.m08#5.o2" to "需要潛水能力",
    "q.m08#5.o3" to "不需要任何技術裝備",
    "q.m08#5.e" to "哈巴的關鍵詞是「雪線以上有冰坡」。這意味著你必須能用冰爪在冰面上穩定移動、用冰鎬做支撐與制動——這些正是 5000 公尺進階單元前面幾課的內容。",
    "q.m08#6.p" to "厄爾布魯士峰的海拔與地位是？",
    "q.m08#6.o0" to "5,642 m，歐洲最高峰",
    "q.m08#6.o1" to "5,895 m，非洲最高峰",
    "q.m08#6.o2" to "5,254 m，祁連山最高峰",
    "q.m08#6.o3" to "6,178 m，崑崙山高峰",
    "q.m08#6.e" to "厄爾布魯士峰 5,642 m，是歐洲最高峰，位於俄羅斯高加索山脈。它在攀登體系裡的位置很特殊：高度屬於 5000 公尺級，但需要冰川行進與結組——是徒步型向技術型的經典跨越點。",
    "q.m08#7.p" to "厄爾布魯士對攀登者的基本要求是？",
    "q.m08#7.o0" to "只需要體能",
    "q.m08#7.o1" to "需要冰爪與冰鎬，冰川行進與結組是基本要求",
    "q.m08#7.o2" to "需要人工氧氣",
    "q.m08#7.o3" to "需要攀岩能力",
    "q.m08#7.e" to "厄爾布魯士的路線涉及冰川，因此結組、冰裂縫意識與冰爪使用都是基本要求。它和乞力馬紮羅常被放在一起對比：同樣在 5000 公尺級，一個是純徒步，一個需要真正的技術操作。",
    "q.m08#8.p" to "【多選】從徒步型轉向技術型，應該優先補上的能力是？",
    "q.m08#8.o0" to "技術裝備的正確使用（冰爪、冰鎬、安全帶）",
    "q.m08#8.o1" to "滑墜制動等基本技術動作",
    "q.m08#8.o2" to "結組行進與基礎保護系統",
    "q.m08#8.o3" to "對「什麼時候不該繼續」的判斷力",
    "q.m08#8.o4" to "購買更昂貴的裝備",
    "q.m08#8.e" to "前三項是「能力」，第四項是「約束」。很多人只補前三項，結果技術越熟練越敢走——反而把風險抬高了。技術訓練與判斷訓練必須同步進行，這也是本單元把技術課和山峰課放在一起的原因。",
    "q.m08#9.p" to "【排序】把下面幾座目標山峰按難度遞進排序。",
    "q.m08#9.o0" to "奧太娜（徒步型，零技術難度）",
    "q.m08#9.o1" to "崗什卡三峰（初級技術型）",
    "q.m08#9.o2" to "哈巴雪山 / 厄爾布魯士（混合型，需冰爪與結組）",
    "q.m08#9.o3" to "南坡玉珠峰（6000 公尺級混合型）",
    "q.m08#9.e" to "這條路徑的關鍵在於「每次只加一個新變數」：從零技術→接觸技術裝備→在真實冰坡上使用→疊加高海拔。很多人的問題不是跳級，而是把難度和海拔同時拉滿，導致無法定位自己到底哪裡不行。",
    "q.m08#10.p" to "為什麼「三峰→主峰」是一條合理的進階路徑？",
    "q.m08#10.o0" to "因為三峰離主峰最近",
    "q.m08#10.o1" to "因為同一座山的不同路線可以分離「技術難度」與「環境難度」兩個變數",
    "q.m08#10.o2" to "因為主峰更便宜",
    "q.m08#10.o3" to "因為三峰更容易迷路",
    "q.m08#10.e" to "在同一座山上進階的好處是：天氣、交通、後勤、嚮導這些「環境變數」基本不變，你能清楚感受到難度的提升來自哪裡。反之，如果每座山都換地方，出了問題往往分不清是技術不夠還是適應不夠。",
    "q.m08#11.p" to "關於選擇 5000 公尺進階目標，正確的態度是？",
    "q.m08#11.o0" to "直接選最高的一座，一步到位",
    "q.m08#11.o1" to "按「每次只增加一個新難度」的原則選擇，並優先保證有可靠後援",
    "q.m08#11.o2" to "選最便宜的",
    "q.m08#11.o3" to "只看登頂率，不看技術要求",
    "q.m08#11.e" to "登山能力的增長是累積性的，而每一次「跳級」都會把風險放大。可靠的後援（嚮導、救援、撤退方案）則是所有入門階段共同的安全基礎——它無法防止你犯錯，但能保證錯誤不至於致命。",
    // ---------- q.m09 ----------
    "q.m09#0.p" to "高原用藥的兩類基本目標是？",
    "q.m09#0.o0" to "治癒高山症、替代下降",
    "q.m09#0.o1" to "提高適應速度、為下撤爭取時間",
    "q.m09#0.o2" to "提升體能、增強耐力",
    "q.m09#0.o3" to "預防感冒、改善睡眠",
    "q.m09#0.e" to "分清這兩類非常關鍵：乙醯唑胺屬於前者（加快適應），地塞米松與硝苯地平屬於後者（爭取時間）。把「爭取時間」的藥當成「治好了」的依據，是高山症處置中最危險的誤判。",
    "q.m09#1.p" to "地塞米松對身體的適應過程有影響嗎？",
    "q.m09#1.o0" to "有，能加快適應",
    "q.m09#1.o1" to "沒有，它對適應性沒有任何影響",
    "q.m09#1.o2" to "有，會減慢適應",
    "q.m09#1.o3" to "只在長期服用時才有影響",
    "q.m09#1.e" to "教材說得很直白：地塞米松只緩解腦水腫症狀，對適應性沒有任何影響，對肺水腫也沒有治療作用。這意味著它純粹是在「買時間」——時間買到了，就必須用來下降。",
    "q.m09#2.p" to "硝苯地平最需要警惕的副作用是？",
    "q.m09#2.o0" to "讓人嗜睡",
    "q.m09#2.o1" to "可能導致血壓迅速下降，起身過快可能暈倒",
    "q.m09#2.o2" to "引起耳鳴",
    "q.m09#2.o3" to "導致食慾下降",
    "q.m09#2.e" to "這個副作用在實際場景裡很危險：在陡坡上或夜間出帳篷時因體位性低血壓暈倒，後果可能比高山症本身更直接。教材也提到，硝苯地平可能對徒步者有幫助，但並不是登山者的最佳選擇。",
    "q.m09#3.p" to "關於高原用藥，下列哪種態度是正確的？",
    "q.m09#3.o0" to "記住劑量就可以自行使用",
    "q.m09#3.o1" to "屬於藥物決策，必須由醫生評估後遵醫囑使用",
    "q.m09#3.o2" to "可以在隊友之間互相分享",
    "q.m09#3.o3" to "副作用不影響使用",
    "q.m09#3.e" to "這幾種藥都有明確的適應證、禁忌與副作用（硝苯地平降血壓、阿司匹林有出血風險、地塞米松是類固醇）。它們不是「高原常識」，而是醫學干預——這也是本課反覆強調「遵醫囑」的原因。",
    "q.m09#4.p" to "服用地塞米松後症狀緩解，此時應該怎麼做？",
    "q.m09#4.o0" to "繼續按計劃上升",
    "q.m09#4.o1" to "仍不宜繼續上升，應儘快下撤",
    "q.m09#4.o2" to "加大劑量後繼續上升",
    "q.m09#4.o3" to "立即停藥觀察",
    "q.m09#4.e" to "藥物讓症狀消失，但腦水腫的成因（低氧）依然存在。教材的結論很明確：服藥後即使症狀緩解，也不宜繼續上升海拔。下降是唯一能真正消除病因的動作。",
    "q.m09#5.p" to "阿司匹林用於緩解高山反應頭痛時，屬於哪種用法？",
    "q.m09#5.o0" to "痛了才吃",
    "q.m09#5.o1" to "提前開始、規律服用的預防性用法",
    "q.m09#5.o2" to "只在睡前服用",
    "q.m09#5.o3" to "只在下降後服用",
    "q.m09#5.e" to "教材給出的用法是海拔上升前 1 天開始、每日 3 次每次 320 毫克，直至適應過程結束——是預防性的規律服用，而不是「痛了再吃」。兩種用法的思路完全不同。",
    "q.m09#6.p" to "乙醯唑胺與地塞米松的根本區別在於？",
    "q.m09#6.o0" to "一個便宜一個貴",
    "q.m09#6.o1" to "一個提高適應速度，一個只緩解症狀",
    "q.m09#6.o2" to "一個口服一個注射",
    "q.m09#6.o3" to "兩者作用完全相同",
    "q.m09#6.e" to "這個區別決定了後續所有的判斷：吃的如果是乙醯唑胺，症狀改善可以理解為身體確實在適應；吃的如果是地塞米松，症狀改善只是被掩蓋了——兩種情況下該不該繼續上升，答案完全相反。",
    "q.m09#7.p" to "【多選】關於高原用藥，下列哪些認識是對的？",
    "q.m09#7.o0" to "藥物不能替代下降",
    "q.m09#7.o1" to "藥物劑量與時機需要醫生指導",
    "q.m09#7.o2" to "不同藥物針對不同病症，不能混用",
    "q.m09#7.o3" to "症狀被藥物掩蓋後，判斷難度反而上升",
    "q.m09#7.o4" to "症狀緩解後即可放心繼續上升",
    "q.m09#7.e" to "這四條都是關鍵認識。其中「症狀被藥物掩蓋後判斷難度上升」最容易被忽略：藥物讓症狀消失後，你失去了最直接的病情晴雨表，只能依靠更客觀的指標（步態、意識、呼吸）來判斷——所以給藥之後反而更要盯緊這三項。",
    "q.m09#8.p" to "為什麼說“什麼藥都不吃、儘快下降”往往是最穩當的選擇？",
    "q.m09#8.o0" to "因為藥物都沒用",
    "q.m09#8.o1" to "因為下降直接消除病因，而藥物只是間接手段",
    "q.m09#8.o2" to "因為藥物太貴",
    "q.m09#8.o3" to "因為藥物不方便攜帶",
    "q.m09#8.e" to "高山症的病因就是低氧，而低氧直接來自海拔。下降把病因拿掉，藥物只是改變身體對病因的反應。只要條件允許，下降永遠是優先順序最高的處置。",
    "q.m09#9.p" to "【排序】發現隊友出現疑似重度高山症症狀時，合理的處置順序是？",
    "q.m09#9.o0" to "立即停止上升，評估意識、步態與呼吸",
    "q.m09#9.o1" to "安排下撤（至少下降 1000 公尺），必要時吸氧",
    "q.m09#9.o2" to "在醫療監護下給予相應藥物（如地塞米松）",
    "q.m09#9.o3" to "無法立即下撤時使用高壓氧艙並聯系救援",
    "q.m09#9.e" to "順序體現了優先順序：先判斷、再下降、藥物輔助、最後才是爭取時間的手段。現實中最常見的錯誤是把順序倒過來——先忙著找藥，忘了下降才是確定性治療。",
    "q.m09#10.p" to "為什麼「與醫生提前溝透過用藥方案」對高海拔行程特別重要？",
    "q.m09#10.o0" to "因為山上買不到藥",
    "q.m09#10.o1" to "因為山上無法臨時獲取專業意見，且嘔吐等狀況會改變給藥方式",
    "q.m09#10.o2" to "因為藥物會過期",
    "q.m09#10.o3" to "因為嚮導要求",
    "q.m09#10.e" to "高海拔現場既沒有醫生，也沒有檢查手段；更麻煩的是，患者可能正在嘔吐而無法口服。這意味著用藥方案必須在出發前就與醫生討論好，包括劑量、時機、給藥方式與禁忌。",
    "q.m09#11.p" to "【配對】把藥物與其主要作用對應起來。",
    "q.m09#11.l0" to "乙醯唑胺",
    "q.m09#11.l1" to "地塞米松",
    "q.m09#11.l2" to "硝苯地平",
    "q.m09#11.r0" to "提高適應速度，用於預防",
    "q.m09#11.r1" to "降低顱內壓、緩解腦水腫",
    "q.m09#11.r2" to "緩解肺動脈收縮，用於肺水腫",
    "q.m09#11.e" to "三張牌各管一段：乙醯唑胺管「適應」，地塞米松管「腦」，硝苯地平管「肺」。先分清患者是哪種情況，再決定用哪張牌——而不是把所有藥都當成「高原藥」。",
    // ---------- q.m10 ----------
    "q.m10#0.p" to "什麼是「天氣窗口」？",
    "q.m10#0.o0" to "天氣預報裡降水機率最低的那天",
    "q.m10#0.o1" to "可以安全完成目標的那段時間",
    "q.m10#0.o2" to "日照時間最長的時段",
    "q.m10#0.o3" to "風力最小的時間",
    "q.m10#0.e" to "天氣窗口是一個綜合概念：它同時滿足「天氣允許」與「隊伍有能力完成」兩個條件。因此同一個天氣條件下，強隊與弱隊的窗口寬度完全不同——窗口是相對的，不是絕對的。",
    "q.m10#1.p" to "為什麼山區的天氣預報精度相對有限？",
    "q.m10#1.o0" to "因為氣象站太少",
    "q.m10#1.o1" to "因為地形複雜導致局地差異極大，同一區域不同海拔與坡向的天氣可能完全不同",
    "q.m10#1.o2" to "因為預報員不用心",
    "q.m10#1.o3" to "因為高海拔沒有氣象資料",
    "q.m10#1.e" to "山區地形的抬升、阻擋與繞流會讓天氣在小尺度上劇烈分化——幾公里之外可能就是另一個世界。所以區域預報只能當作「背景」，現場觀察才是決策依據。",
    "q.m10#2.p" to "雲層明顯加厚、雲底降低，通常預示？",
    "q.m10#2.o0" to "天氣轉好",
    "q.m10#2.o1" to "天氣轉壞，能見度可能迅速惡化",
    "q.m10#2.o2" to "即將放晴",
    "q.m10#2.o3" to "沒有任何含義",
    "q.m10#2.e" to "雲底降低意味著空氣溼度上升、抬升凝結高度下降，往往是降水系統的前兆。在山上，它同時也意味著視野會迅速收縮——這本身就是一項獨立的風險。",
    "q.m10#3.p" to "氣壓「趨勢」比氣壓「數值」更有意義，原因是？",
    "q.m10#3.o0" to "因為數值總是錯的",
    "q.m10#3.o1" to "因為天氣變化由氣壓的變化趨勢驅動，而不同海拔的基準值本來就不同",
    "q.m10#3.o2" to "因為趨勢更容易記憶",
    "q.m10#3.o3" to "因為數值波動太大",
    "q.m10#3.e" to "同一氣壓值在不同海拔、不同地點的含義完全不同，所以孤立地看數值沒有參照系。而「持續下降」這個趨勢在任何地方都指向同一件事：天氣在轉壞。",
    "q.m10#4.p" to "蒲福風級的實用價值主要在於？",
    "q.m10#4.o0" to "讓風看起來更專業",
    "q.m10#4.o1" to "把風速換算成可感知、可傳遞的等級，便於判斷行動能力與溝通",
    "q.m10#4.o2" to "測量降水量",
    "q.m10#4.o3" to "判斷氣溫",
    "q.m10#4.e" to "風力是需要被「說出來」的資訊：隊伍需要一套共同語言來判斷「現在還能不能繼續」。蒲福風級把抽象的風速變成可觀察的現象（樹葉、雪粒、體感），使判斷可以在隊伍內快速傳遞。",
    "q.m10#5.p" to "【多選】下列哪些屬於天氣正在轉壞的現場訊號？",
    "q.m10#5.o0" to "氣壓持續下降",
    "q.m10#5.o1" to "雲層迅速加厚、雲底降低",
    "q.m10#5.o2" to "風力明顯增強並頻繁轉向",
    "q.m10#5.o3" to "遠處出現垂直髮展的積雨雲",
    "q.m10#5.o4" to "氣壓持續上升、風力逐漸減弱",
    "q.m10#5.e" to "這四項是教材體系裡最主要的轉壞訊號。它們的共同特點是「趨勢」而非「瞬時值」——所以關鍵是養成定時觀察的習慣，只有有了對比，趨勢才有意義。",
    "q.m10#6.p" to "出現雷暴時，最應該避免的做法是？",
    "q.m10#6.o0" to "停止行進並下撤",
    "q.m10#6.o1" to "停留在山脊、峰頂或開闊水面等暴露位置",
    "q.m10#6.o2" to "收好金屬裝備",
    "q.m10#6.o3" to "低姿蹲下等待",
    "q.m10#6.e" to "雷暴中最危險的是「成為周圍最高的目標」。山脊與峰頂恰恰是最暴露的位置，一旦雷電臨近必須儘快離開。同時要把金屬裝備收攏、與身體拉開距離。",
    "q.m10#7.p" to "為什麼衝頂多安排在凌晨出發？",
    "q.m10#7.o0" to "為了避開人流",
    "q.m10#7.o1" to "因為清晨通常是全天最穩定的時段，午後對流增強、天氣惡化機率上升",
    "q.m10#7.o2" to "因為凌晨體力最好",
    "q.m10#7.o3" to "因為白天太熱",
    "q.m10#7.e" to "這背後是天氣的日變化規律：白天日照加熱地面產生對流，雲量與降水機率在午後上升。把高強度、最關鍵的行軍段安排在凌晨，就是在爭取一個更寬容的天氣窗口。",
    "q.m10#8.p" to "天氣窗口與折返時間之間的關係是？",
    "q.m10#8.o0" to "兩者無關",
    "q.m10#8.o1" to "折返時間應當根據天氣窗口來設定，窗口變窄則折返時間提前",
    "q.m10#8.o2" to "折返時間總是固定的",
    "q.m10#8.o3" to "天氣好就不需要折返時間",
    "q.m10#8.e" to "折返時間不是一個固定數字，而是根據當日天氣窗口推算出來的：需要多少時間登頂、多少時間下撤、窗口從幾點開始收窄——反推出最晚必須轉身的時刻。",
    "q.m10#9.p" to "【排序】把一次日常天氣判斷的步驟按合理順序排列。",
    "q.m10#9.o0" to "出發前檢視區域預報與氣壓趨勢",
    "q.m10#9.o1" to "行進中定時觀察雲、風、能見度的變化",
    "q.m10#9.o2" to "把現場觀察與預報對比，判斷趨勢方向",
    "q.m10#9.o3" to "根據趨勢調整行程或提前折返",
    "q.m10#9.e" to "關鍵是第三步——很多人做到第二步就停了，只是「感覺到天氣在變」，卻沒有把它轉化為明確的判斷與行動。觀察不轉化為決策，就等於沒觀察。",
    "q.m10#10.p" to "天氣窗口變窄時，最先應該考慮放棄的是什麼？",
    "q.m10#10.o0" to "安全裝備",
    "q.m10#10.o1" to "登頂目標本身",
    "q.m10#10.o2" to "隊伍成員",
    "q.m10#10.o3" to "通訊裝置",
    "q.m10#10.e" to "這是決策優先順序問題：當窗口不足以同時容納登項與安全下撤時，應當保留的是「安全下撤」，放棄的是「登頂」。這個優先順序必須在出發前就想清楚，而不是在山上臨時權衡。",
    "q.m10#11.p" to "關於「白化」天氣，正確的認識是？",
    "q.m10#11.o0" to "只是能見度差，沒有危險",
    "q.m10#11.o1" to "失去所有視覺參照，人會本能地沿錯誤方向前進，必須優先定位",
    "q.m10#11.o2" to "會帶來降水",
    "q.m10#11.o3" to "只發生在夜間",
    "q.m10#11.e" to "白化最危險的地方不在於看不清，而在於「你以為自己看得很清」。失去視覺參照後，人的方向感會系統性偏移——所以第一件事是定位與記錄朝向，而不是繼續走。",
    // ---------- q.m11 ----------
    "q.m11#0.p" to "玉珠峰的海拔與位置是？",
    "q.m11#0.o0" to "6,178 m，青海格爾木，崑崙山脈東段",
    "q.m11#0.o1" to "6,206 m，西藏當雄，念青唐古拉山脈",
    "q.m11#0.o2" to "6,119 m，尼泊爾昆布",
    "q.m11#0.o3" to "6,189 m，尼泊爾昆布",
    "q.m11#0.e" to "玉珠峰 6,178 m，位於青海格爾木境內的崑崙山脈東段。它的南坡路線相對溫和、交通可達性好，因此是很多人 6000 公尺級的第一選擇。",
    "q.m11#1.p" to "啟孜峰的海拔與所在山脈是？",
    "q.m11#1.o0" to "6,178 m，崑崙山脈",
    "q.m11#1.o1" to "6,206 m，念青唐古拉山脈",
    "q.m11#1.o2" to "6,119 m，喜馬拉雅山脈",
    "q.m11#1.o3" to "6,189 m，喀喇崑崙山脈",
    "q.m11#1.e" to "啟孜峰 6,206 m，位於西藏當雄的念青唐古拉山脈。它的特點是雪坡穩定、交通便利——穩定的雪坡意味著雪崩與冰裂縫風險相對可控，適合作為進階訓練。",
    "q.m11#2.p" to "羅布切東峰的海拔與位置是？",
    "q.m11#2.o0" to "6,119 m，尼泊爾昆布地區",
    "q.m11#2.o1" to "6,189 m，尼泊爾昆布地區",
    "q.m11#2.o2" to "6,206 m，西藏當雄",
    "q.m11#2.o3" to "6,178 m，青海格爾木",
    "q.m11#2.e" to "羅布切東峰 6,119 m，位於尼泊爾昆布地區——就在珠峰徒步路線的旁邊。這個位置意味著適應條件與後勤都相對成熟，而雪坡較陡，是往更高海拔過渡的好臺階。",
    "q.m11#3.p" to "島峰（Imja Tse）最典型的技術特徵是？",
    "q.m11#3.o0" to "完全不需要技術裝備",
    "q.m11#3.o1" to "需要結組與冰裂縫行進",
    "q.m11#3.o2" to "需要人工氧氣",
    "q.m11#3.o3" to "需要攀岩能力",
    "q.m11#3.e" to "島峰 6,189 m，是經典的 6000 公尺級技術峰——需要結組、需要應對冰裂縫。這也解釋了為什麼它常被作為 7000 公尺級別的準備：它把「冰川行進 + 結組」這套系統真正用上了。",
    "q.m11#4.p" to "6000 公尺級相比 5000 公尺級，最顯著上升的風險是？",
    "q.m11#4.o0" to "落石",
    "q.m11#4.o1" to "高海拔適應壓力（高山症風險）",
    "q.m11#4.o2" to "蚊蟲",
    "q.m11#4.o3" to "裝備重量",
    "q.m11#4.e" to "海拔上到 6000 公尺，高山症的發生率與嚴重程度明顯上升——這正是 6000 公尺單元把高山症作為核心章節的原因。技術上可能只是循序漸進，但生理上的臺階是真實存在的。",
    "q.m11#5.p" to "【多選】進入 6000 公尺級之前，應當已經掌握的內容包括？",
    "q.m11#5.o0" to "冰爪與冰鎬的基本使用",
    "q.m11#5.o1" to "基礎繩結與結組行進",
    "q.m11#5.o2" to "高山症的識別與處置原則",
    "q.m11#5.o3" to "冰裂縫風險的基本認識",
    "q.m11#5.o4" to "獨立領攀 WI5 冰瀑的能力",
    "q.m11#5.e" to "這四項分別對應 5000 入門與進階兩個單元的內容。6000 公尺單元並不是重新學一遍，而是把已掌握的內容放在更嚴苛的環境裡去用——基礎不牢就直接上 6000 公尺，風險是成倍放大的。",
    "q.m11#6.p" to "為什麼「南坡玉珠峰」常被當作 6000 公尺級的第一站？",
    "q.m11#6.o0" to "因為它最便宜",
    "q.m11#6.o1" to "因為路線相對溫和、交通與後勤條件成熟，能把注意力集中在適應上",
    "q.m11#6.o2" to "因為它沒有危險",
    "q.m11#6.o3" to "因為它不需要嚮導",
    "q.m11#6.e" to "第一站的價值在於「只增加一個新變數」。南坡路線把技術難度壓在可控範圍，讓你能專注應對真正的挑戰——高海拔適應。如果選一座技術門檻就很高的 6000 公尺，你很難分清問題出在哪裡。",
    "q.m11#7.p" to "【排序】把下列目標山峰按海拔從低到高排列。",
    "q.m11#7.o0" to "羅布切東峰（6,119 m）",
    "q.m11#7.o1" to "玉珠峰（6,178 m）",
    "q.m11#7.o2" to "島峰（6,189 m）",
    "q.m11#7.o3" to "啟孜峰（6,206 m）",
    "q.m11#7.e" to "這四座山的海拔差距其實很小（6,119～6,206 m，不足 90 公尺）。這恰好說明一件事：在 6000 公尺這個區間，選山看的不應該是海拔，而是路線型別、後援條件與你的短板。",
    "q.m11#8.p" to "為什麼 6000 公尺級必須「假設冰裂縫存在」？",
    "q.m11#8.o0" to "因為冰裂縫會發出聲音",
    "q.m11#8.o1" to "因為冰川上雪橋可能被新雪完全覆蓋，外觀與普通雪面無異",
    "q.m11#8.o2" to "因為冰裂縫在夜間才會出現",
    "q.m11#8.o3" to "因為冰裂縫很容易辨認",
    "q.m11#8.e" to "這正是冰裂縫最致命的地方：它不像落石那樣有明顯徵兆。因此 6000 公尺級的正確心態是「預設到處都有」，用結組與裝備把風險管住，而不是靠「看起來安全」來判斷。",
    "q.m11#9.p" to "在 6000 公尺級選峰時，比海拔更值得關注的指標是？",
    "q.m11#9.o0" to "山峰的知名度",
    "q.m11#9.o1" to "路線型別（徒步型/混合型/技術型）、後援條件與上升節奏",
    "q.m11#9.o2" to "登山費用",
    "q.m11#9.o3" to "社交媒體熱度",
    "q.m11#9.e" to "同類海拔的山峰，技術難度與適應壓力可能相差很大。把「路線型別 + 後援條件 + 上升節奏」這三項組合起來看，才能得出「這座山適不適合現在的我」這個答案。",
    "q.m11#10.p" to "關於「6000 公尺級的技術門檻」，正確的認識是？",
    "q.m11#10.o0" to "技術門檻很低，主要靠體能",
    "q.m11#10.o1" to "技術門檻不算高，但不能零基礎，且冰川行進能力是必備項",
    "q.m11#10.o2" to "必須有攀岩基礎",
    "q.m11#10.o3" to "必須掌握人工氧氣使用",
    "q.m11#10.e" to "6000 公尺級的典型畫像：技術難度中等，但你已經必須能結組、能判斷冰裂縫風險、能在冰川上自主行進。它是「能用系統保護自己」的起點，而不是「看別人怎麼做」的階段。",
    "q.m11#11.p" to "為什麼高海拔山峰的「最佳攀登季節」對行程如此關鍵？",
    "q.m11#11.o0" to "因為淡季門票便宜",
    "q.m11#11.o1" to "因為山峰的可攀登窗口高度依賴季節性天氣模式，錯季可能幾乎沒有窗口",
    "q.m11#11.o2" to "因為季節影響雪的顏色",
    "q.m11#11.o3" to "因為嚮導只在旺季工作",
    "q.m11#11.e" to "不同山峰的窗口成因不同：有的是避開季風帶來的降水，有的是避開冬季的極端低溫與大風。理解「為什麼這個季節適合」，比記住「幾月去」重要得多——因為氣候變化正在讓這些規律發生漂移。",
    // ---------- q.m12 ----------
    "q.m12#0.p" to "3:1 的 Z 系統（Z-drag）為什麼能獲得三倍拉力？",
    "q.m12#0.o0" to "因為使用了更粗的繩索",
    "q.m12#0.o1" to "因為抓結與滑輪配合，把拉繩行程放大成三倍",
    "q.m12#0.o2" to "因為重力協助",
    "q.m12#0.o3" to "因為滑輪本身會自動省力",
    "q.m12#0.e" to "機械優勢的本質是「用行程換力量」：你拉出三公尺繩，被拉物體上升一公尺。代價是拉昇速度變慢——在裂縫救援中，這個代價完全可以接受。",
    "q.m12#1.p" to "滑輪在救援系統中的主要作用是？",
    "q.m12#1.o0" to "提供額外強度",
    "q.m12#1.o1" to "減少繩索摩擦損耗，提高系統效率",
    "q.m12#1.o2" to "固定繩索",
    "q.m12#1.o3" to "保護繩索不受磨損",
    "q.m12#1.e" to "摩擦是機械優勢的隱形殺手：每經過一個轉折點都會損失一部分力。滑輪把滑動摩擦換成滾動摩擦，讓理論上的 3:1 更接近實際的 3:1。",
    "q.m12#2.p" to "如果沒有滑輪，救援系統還能搭建嗎？",
    "q.m12#2.o0" to "完全不能搭建",
    "q.m12#2.o1" to "能用主鎖代替，但摩擦損耗明顯增加、效率下降",
    "q.m12#2.o2" to "能用繩子直接代替，效率相同",
    "q.m12#2.o3" to "必須等待裝備送達",
    "q.m12#2.e" to "系統可以用主鎖代替滑輪，這也是為什麼許多隊伍把「備用主鎖」當作必帶項。區別在於實際獲得的機械優勢會明顯低於理論值——知道這一點，才能在裝備不全時做好心理與體力準備。",
    "q.m12#3.p" to "【多選】教材列出的常見結組救援裝備包括？",
    "q.m12#3.o0" to "2～3 個雪錐或冰錐",
    "q.m12#3.o1" to "2～5 把主鎖與 2～5 條扁帶",
    "q.m12#3.o2" to "1 個制動滑輪",
    "q.m12#3.o3" to "2～3 個抓結與 1 個上升器",
    "q.m12#3.o4" to "1 個便攜爐頭與氣罐",
    "q.m12#3.e" to "這份清單的特點——「每名結組隊員都應準備足夠的救援裝備」——這意味著救援裝備不是隊伍共享的公共物資，而是每個人自己的標配。因為墜落髮生時，你身上的裝備就是唯一可用的裝備。",
    "q.m12#4.p" to "上升器的制動原理是？",
    "q.m12#4.o0" to "靠彈簧夾緊繩索",
    "q.m12#4.o1" to "靠鋼刺與繩索產生的逆向摩擦制動",
    "q.m12#4.o2" to "靠磁力吸附",
    "q.m12#4.o3" to "靠繩索自身的重量",
    "q.m12#4.e" to "理解原理直接關係到使用：因為是靠鋼刺「咬」住繩纖維，所以用力過猛會損傷繩索，嚴重時可在受力處切斷纖維。這也是為什麼教材強調儘量配合輔助制動方法使用。",
    "q.m12#5.p" to "使用上升器時用力過猛會造成什麼後果？",
    "q.m12#5.o0" to "沒有任何影響",
    "q.m12#5.o1" to "鋼刺會損傷繩索",
    "q.m12#5.o2" to "上升器會卡死",
    "q.m12#5.o3" to "會導致上升器脫落",
    "q.m12#5.e" to "上升器靠鋼刺與繩子的逆向摩擦制動，用力過猛會在繩皮上留下傷痕，累積起來可能成為斷裂點。會看到很多人習慣性地猛拽上升器——這是一個用習慣換取風險的動作。",
    "q.m12#6.p" to "【排序】搭建 3:1 Z 系統時，合理的順序是？",
    "q.m12#6.o0" to "確認確保站可靠，並把墜落者的重量轉移到確保站",
    "q.m12#6.o1" to "在受力繩上裝主抓結，並加裝置份抓結",
    "q.m12#6.o2" to "在抓結上連線滑輪或主鎖，形成 Z 形路徑",
    "q.m12#6.o3" to "檢查系統完整後開始拉昇，每拉一段重新收緊",
    "q.m12#6.e" to "第一步是整件事的地基：不先把重量轉移出去，你的雙手就被佔用在維持制動上。而最後一步的「每拉一段重新收緊」很容易被省略，結果就是拉了半天又滑回去。",
    "q.m12#7.p" to "【配對】把救援器材與其在系統中的作用對應起來。",
    "q.m12#7.l0" to "抓結",
    "q.m12#7.l1" to "滑輪",
    "q.m12#7.l2" to "制動滑輪",
    "q.m12#7.l3" to "上升器",
    "q.m12#7.r0" to "單向抓握，使系統能前進而不後退",
    "q.m12#7.r1" to "減少摩擦損耗，提高效率",
    "q.m12#7.r2" to "可單向鎖止，用於控制放出與收緊",
    "q.m12#7.r3" to "沿繩上升，也可用於系統固定",
    "q.m12#7.e" to "四者在系統裡分工不同：抓結提供「單向性」，滑輪降低摩擦，制動器提供控制，上升器提供移動能力。少了任何一環，系統要麼效率低，要麼不可控。",
    "q.m12#8.p" to "為什麼在主抓結之外還要設定備份抓結？",
    "q.m12#8.o0" to "為了美觀",
    "q.m12#8.o1" to "因為抓結可能因結冰、泥汙或繩徑不匹配而失效，失效時系統會瞬間失去機械優勢",
    "q.m12#8.o2" to "因為規範如此要求",
    "q.m12#8.o3" to "為了防止繩索扭結",
    "q.m12#8.e" to "抓結靠摩擦工作，而摩擦受很多因素影響。一旦主抓結滑動，墜落者會在毫無預警的情況下再次下墜——備份抓結的作用是接住這一瞬間。",
    "q.m12#9.p" to "2:1 與 3:1 系統相比，選擇依據是？",
    "q.m12#9.o0" to "2:1 總是更好",
    "q.m12#9.o1" to "根據人力、繩長與地形條件選擇：機械優勢越大，所需繩長越長、速度越慢",
    "q.m12#9.o2" to "3:1 總是更好",
    "q.m12#9.o3" to "兩者完全相同",
    "q.m12#9.e" to "機械優勢不是無條件的好：3:1 需要更多繩長，而裂縫救援中繩長往往有限。所以實際選擇是「在可用繩長與人力條件下能完成的那一個」，而不是理論最優的那個。",
    "q.m12#10.p" to "為什麼機械優勢系統不能替代判斷？",
    "q.m12#10.o0" to "因為系統可能會壞",
    "q.m12#10.o1" to "因為系統只能把人力放大，但無法判斷該不該拉、往哪個方向拉",
    "q.m12#10.o2" to "因為系統太重",
    "q.m12#10.o3" to "因為需要很多人操作",
    "q.m12#10.e" to "救援現場真正的難點從來不是力學，而是判斷：往哪拉、經過哪個邊緣、傷員能不能承受。系統是工具，方向由人判斷——方向錯了，力氣越大反而越危險。",
    "q.m12#11.p" to "抓結失效的常見原因不包括？",
    "q.m12#11.o0" to "繩徑不匹配",
    "q.m12#11.o1" to "結冰或泥汙",
    "q.m12#11.o2" to "纏繞圈數不足",
    "q.m12#11.o3" to "主繩顏色較淺",
    "q.m12#11.e" to "繩徑、潔淨度與纏繞圈數都會直接影響摩擦，而顏色完全與力學無關。這也說明抓結的可靠性無法從外觀判斷——只能靠事前的搭配確認與實地測試。",
    "q.m12#12.p" to "為什麼系統中常常使用「制動滑輪」而不是普通滑輪？",
    "q.m12#12.o0" to "因為更輕",
    "q.m12#12.o1" to "因為它可單向鎖止，能在控制釋放的同時保持系統不倒退",
    "q.m12#12.o2" to "因為更便宜",
    "q.m12#12.o3" to "因為顏色更醒目",
    "q.m12#12.e" to "救援過程中往往需要「一邊拉昇一邊調整」，普通滑輪雙向自由，一旦鬆手就會倒退。可單向鎖止的部件把「保持位置」變成了系統自身的能力——這就是器材選型影響操作安全性的例子。",
    "q.m12#13.p" to "填空：Z 系統的機械優勢比是（ ）:1。",
    "q.m12#13.a0" to "3",
    "q.m12#13.a1" to "三",
    "q.m12#13.e" to "3:1。記住這個數字的實用價值在於容量估算：一個成人連同裝備可能重達 80～100 公斤，3:1 意味著你仍需付出約 30 公斤的拉力——比想象中吃力得多，這也是救援必須由多人協作的原因。",
    "q.m12#14.p" to "【多選】系統完成後的檢查應包括？",
    "q.m12#14.o0" to "抓結纏繞圈數與受力方向是否正確",
    "q.m12#14.o1" to "滑輪/主鎖是否鎖閉",
    "q.m12#14.o2" to "連線點是否連線在安全帶的正確位置",
    "q.m12#14.o3" to "是否已設定備份並確認無卡繩",
    "q.m12#14.o4" to "繩索與隊友的顏色是否統一",
    "q.m12#14.e" to "這四項對應四類典型失誤：抓結裝反、鎖門未鎖、接到錯誤掛環、以及沒裝置份。救援系統的失誤往往不是「不懂」，而是「在緊張與黑暗中漏了一步」——所以靠清單而不是靠記憶。",
    "q.m12#15.p" to "為什麼救援系統必須在出發前演練？",
    "q.m12#15.o0" to "為了應付考核",
    "q.m12#15.o1" to "因為實際救援時需要在高海拔、低溫、黑暗中憑本能完成一整套複雜操作",
    "q.m12#15.o2" to "為了熟悉器材",
    "q.m12#15.o3" to "因為規範要求演練時長",
    "q.m12#15.e" to "救援現場的條件幾乎總是最差的：風大、手冷、光線暗、同伴正在惡化。在這種條件下能完成的操作，只有那些以前重複過很多次的操作——臨場學習是不可能完成的。",
    // ---------- q.m13 ----------
    "q.m13#0.p" to "為什麼 7000 公尺級把「自救能力」列為硬門檻？",
    "q.m13#0.o0" to "因為隊友不願意救援",
    "q.m13#0.o1" to "因為高海拔環境中同伴可能無法及時到達，你必須能處理自己的狀況",
    "q.m13#0.o2" to "因為救援裝備不夠",
    "q.m13#0.o3" to "因為規定要求",
    "q.m13#0.e" to "海拔越高，救援的代價越大、時間越長。夥伴可能正在與自己的高山症作鬥爭，天氣也可能不允許任何移動。把自己完全交給外部救援，等於接受一個無法保障的前提。",
    "q.m13#1.p" to "抓結自我上升的基本原理是？",
    "q.m13#1.o0" to "靠手臂力量向上拉",
    "q.m13#1.o1" to "用兩個抓結交替：一個承重，另一個沿繩上移",
    "q.m13#1.o2" to "靠上升器一個人完成",
    "q.m13#1.o3" to "靠腿夾住繩索",
    "q.m13#1.e" to "單個抓結只能固定位置、無法移動，所以必須兩個交替：下面承重時上面上移，上面承重時下面上移。這個「交替」動作需要在安全場地練熟——它會在你最需要的時候決定你能不能上去。",
    "q.m13#2.p" to "為什麼抓結上升時必須始終保持至少一個抓結承重？",
    "q.m13#2.o0" to "為了省力",
    "q.m13#2.o1" to "因為一旦兩個抓結同時鬆開，就會直接滑回起點甚至下墜",
    "q.m13#2.o2" to "為了保持繩索整潔",
    "q.m13#2.o3" to "為了讓上升速度更快",
    "q.m13#2.e" to "這就是「三點固定」原則在繩索上的體現：任何時候都要保留一個可靠支撐點。在裂縫裡，一次滑落不僅消耗體力，還可能讓繩索繼續切入雪簷，把救援難度整體抬高。",
    "q.m13#3.p" to "【排序】把結組救援的四步按正確順序排列。",
    "q.m13#3.o0" to "立即自制動，穩住自己",
    "q.m13#3.o1" to "建立獨立確保站",
    "q.m13#3.o2" to "把重量轉移到確保站",
    "q.m13#3.o3" to "用 3:1 系統拉昇",
    "q.m13#3.e" to "這四步在 6000 公尺單元已經學過，這裡要強調的是「能在壓力下執行」。實戰與練習最大的區別是：實戰中你必須在幾十秒內完成前三步，而練習時你可能花了五分鐘。",
    "q.m13#4.p" to "隊伍遭遇雷暴時，隊員之間應該保持多遠距離？",
    "q.m13#4.o0" to "緊靠在一起",
    "q.m13#4.o1" to "約 50 公尺",
    "q.m13#4.o2" to "約 500 公尺",
    "q.m13#4.o3" to "不限制",
    "q.m13#4.e" to "教材建議彼此保持 50 公尺左右——目的是避免一次雷擊同時擊傷多人，保留能實施急救的人。這個數字背後是「不要把所有籌碼押在一處」的思路。",
    "q.m13#5.p" to "雷暴時減小危險唯一有效的辦法是？",
    "q.m13#5.o0" to "扔掉冰鎬等金屬裝備",
    "q.m13#5.o1" to "儘快撤離制高點和暴露區域，儘量保持低姿態",
    "q.m13#5.o2" to "蹲下抱住膝蓋",
    "q.m13#5.o3" to "拉開所有拉鍊",
    "q.m13#5.e" to "教材明確否定了幾種常見做法：沒有證據表明冰鎬、帳篷杆這類小型金屬物能吸引雷電，所以不要浪費時間扔掉它們。真正有效的是改變自己的位置——從「周圍最高的目標」變成「不起眼的一部分」。",
    "q.m13#6.p" to "聽到雷聲，說明雷電發生地距離你不會超過？",
    "q.m13#6.o0" to "約 3 公里",
    "q.m13#6.o1" to "約 10～16 公里",
    "q.m13#6.o2" to "約 30 公里",
    "q.m13#6.o3" to "約 50 公里",
    "q.m13#6.e" to "能聽到雷聲意味著雷電在 10～16 公里以內，已經進入需要作出反應的範圍。而能看見閃電則說明距離不超過約 24 公里——兩個數字對應兩個不同的應對等級。",
    "q.m13#7.p" to "如何用閃電與雷聲的時間差估算雷電距離？",
    "q.m13#7.o0" to "秒數 × 0.34 = 距離（公里）",
    "q.m13#7.o1" to "秒數 ÷ 0.34 = 距離（公里）",
    "q.m13#7.o2" to "秒數 × 3.4 = 距離（公里）",
    "q.m13#7.o3" to "無法估算",
    "q.m13#7.e" to "聲音在空氣中傳播速度約為 0.34 公里/秒，所以看到閃電後數秒，每秒對應約 0.34 公里。這個方法的實用價值是「不需要任何裝置」就能判斷雷暴是在靠近還是遠離。",
    "q.m13#8.p" to "小型金屬裝備（冰鎬、帳篷杆）會吸引雷電嗎？",
    "q.m13#8.o0" to "會，必須立即扔掉",
    "q.m13#8.o1" to "沒有證據表明會，不應浪費時間扔掉它們",
    "q.m13#8.o2" to "會，但只在高處",
    "q.m13#8.o3" to "只會在潮溼時",
    "q.m13#8.e" to "這是一個典型的高原迷思。教材的態度很直接：沒有證據支援，不要把寶貴時間花在扔裝備上。真正需要做的是儘快離開暴露位置——那才是決定性的變數。",
    "q.m13#9.p" to "雷暴時最好的躲避地點是？",
    "q.m13#9.o0" to "山頂",
    "q.m13#9.o1" to "遠離頂峰與山脊的林地中央，但千萬不能靠在樹上",
    "q.m13#9.o2" to "草坡中央",
    "q.m13#9.o3" to "帳篷裡",
    "q.m13#9.e" to "林地中央的特點是周圍有更高的目標，但你又不直接靠在導體上。反例是「空曠的山脊上紮營」——教材把這種做法稱為極端愚蠢，因為這意味著你主動住在了當地最高的位置。",
    "q.m13#10.p" to "為什麼不能在積雲正在生成時選擇在山脊紮營？",
    "q.m13#10.o0" to "因為風大",
    "q.m13#10.o1" to "因為積雲發展成積雨雲後就意味著雷電，而山脊正是最暴露的位置",
    "q.m13#10.o2" to "因為視野不好",
    "q.m13#10.o3" to "因為地面不平",
    "q.m13#10.e" to "積雲到積雨雲的發展往往只有一兩個小時。在山脊紮營等於把自己放在雷暴路徑的最前端——而且是帶著全部裝備與帳篷、幾乎無法快速撤離的狀態。",
    "q.m13#11.p" to "有人被雷電擊中後，首要處置是什麼？",
    "q.m13#11.o0" to "先檢查有無外傷",
    "q.m13#11.o1" to "立即檢查呼吸與心跳，必要時進行心肺復甦，並儘快送醫",
    "q.m13#11.o2" to "先換乾衣物",
    "q.m13#11.o3" to "先移動到低處",
    "q.m13#11.e" to "雷擊可能造成心跳驟停與內傷，而外表可能看不出異常。因此檢查呼吸心跳優先於其他處置，而且即使患者清醒也必須送醫——電流對心臟的影響可能延遲出現。",
    "q.m13#12.p" to "【多選】自救能力通常包括哪些內容？",
    "q.m13#12.o0" to "抓結自我上升",
    "q.m13#12.o1" to "自制動與自我保護",
    "q.m13#12.o2" to "在無夥伴協助下建立保護",
    "q.m13#12.o3" to "判斷何時原地等待、何時自行脫困",
    "q.m13#12.o4" to "能在無保護狀態下徒手攀岩",
    "q.m13#12.e" to "前三項是能力，第四項是判斷。特別要注意「判斷何時原地等待、何時自行脫困」這一項：不是所有情況都應該自行脫困——如果已受傷或天氣惡化，停在原地等救援可能比貿然移動更安全。",
    "q.m13#13.p" to "為什麼「等隊友來救」不能作為主要安全策略？",
    "q.m13#13.o0" to "因為隊友可能不願意",
    "q.m13#13.o1" to "因為隊友本身也可能處於危險、受傷或無法行動的狀態",
    "q.m13#13.o2" to "因為救援裝置不夠",
    "q.m13#13.o3" to "因為規則不允許",
    "q.m13#13.e" to "結組的意義是互相保護，但不能假設隊友一定有餘力。在高海拔，一個隊員同時應對兩個人的困境往往超出能力——所以自救是「必需項」，互救是「加分項」。",
    // ---------- q.m14 ----------
    "q.m14#0.p" to "危險判斷真正要回答的問題是？",
    "q.m14#0.o0" to "有沒有危險",
    "q.m14#0.o1" to "這個風險是否可以接受，依據是什麼",
    "q.m14#0.o2" to "危險有多大",
    "q.m14#0.o3" to "隊友會不會害怕",
    "q.m14#0.e" to "「有沒有危險」幾乎總是「有」——沒有任何山地活動是零風險的。所以真正的判斷是「與收益相比，這個風險是否值得承擔，我們憑什麼這麼認為」。這直接決定了判斷必須能被說出來、被討論。",
    "q.m14#1.p" to "什麼是「事故鏈」？",
    "q.m14#1.o0" to "指一次事故的傷亡人數",
    "q.m14#1.o1" to "指多個小失誤依次疊加、最終導致事故的過程",
    "q.m14#1.o2" to "指救援的時間線",
    "q.m14#1.o3" to "指裝備失效的鏈條",
    "q.m14#1.e" to "事故鏈這個概念最有價值的地方在於——它把事故從「倒黴」變成了「可干預的過程」。只要在鏈條任意一環做出不同選擇，結果就會不同。",
    "q.m14#2.p" to "打斷事故鏈最有效的方式是？",
    "q.m14#2.o0" to "在任何一環做出更保守的選擇",
    "q.m14#2.o1" to "只關注最後一環",
    "q.m14#2.o2" to "增加裝備",
    "q.m14#2.o3" to "提高隊伍體能",
    "q.m14#2.e" to "任何一環都行——早上早點出發、到點就撤、不為趕時間簡化保護。這也是為什麼「留餘量」比「補救」有效：餘量作用在鏈條早期，而補救往往發生在最後一環。",
    "q.m14#3.p" to "【多選】下列哪些屬於常見的決策偏誤？",
    "q.m14#3.o0" to "沉沒成本",
    "q.m14#3.o1" to "隊伍壓力",
    "q.m14#3.o2" to "目標執念",
    "q.m14#3.o3" to "風險正常化",
    "q.m14#3.o4" to "對裝備品牌的迷信",
    "q.m14#3.e" to "四者會疊加起作用：已經投入了很多（沉沒成本）＋隊友都在往上走（隊伍壓力）＋就差一點（目標執念）＋上次也這樣沒事（風險正常化）——這四條同時出現時，判斷幾乎必然向冒險傾斜。",
    "q.m14#4.p" to "沉沒成本如何影響登山判斷？",
    "q.m14#4.o0" to "讓人更謹慎",
    "q.m14#4.o1" to "因為已經投入了大量時間與金錢，所以不願承認應該放棄",
    "q.m14#4.o2" to "讓人體力更好",
    "q.m14#4.o3" to "沒有影響",
    "q.m14#4.e" to "沉沒成本的特點是不可回收，但它在心理上卻變成了「繼續投入的理由」。在山上，它與目標執念疊加後，會把「理性撤退」變成「放棄」——而人對「放棄」有天然的心理抗拒。",
    "q.m14#5.p" to "什麼是「風險正常化」？",
    "q.m14#5.o0" to "把危險控制在可接受範圍",
    "q.m14#5.o1" to "多次安全透過某個條件後，不自覺地把這個條件重新歸類為「安全」",
    "q.m14#5.o2" to "學習風險評估方法",
    "q.m14#5.o3" to "使用標準化的風險評級",
    "q.m14#5.e" to "風險正常化是慢慢發生的，因此當事人幾乎察覺不到。同一個人第一次走某個陡坡時可能非常謹慎，第十次時已經不再繫繩——坡沒變，是判斷變了。",
    "q.m14#6.p" to "為什麼在高風險環境中「少數服從多數」有問題？",
    "q.m14#6.o0" to "因為效率太低",
    "q.m14#6.o1" to "因為多數決會讓少數人的合理擔憂被壓制",
    "q.m14#6.o2" to "因為投票不一定公平",
    "q.m14#6.o3" to "因為隊里人數不等",
    "q.m14#6.e" to "危險訊號往往只被一兩個人注意到（比如某人看到了雪層裂紋），而這種觀察是「少數人持有、但一旦為真就致命」的資訊。用投票去決定它的去留，等於系統性地忽略低機率高後果的訊號。",
    "q.m14#7.p" to "為什麼「最保守的意見優先」？",
    "q.m14#7.o0" to "因為保守的人更資深",
    "q.m14#7.o1" to "因為在不確定情況下，保守選項的錯誤代價遠低於冒險選項",
    "q.m14#7.o2" to "因為規則要求",
    "q.m14#7.o3" to "為了讓所有人都滿意",
    "q.m14#7.e" to "這是不對稱代價的典型場景：保守可能白走一趟，冒險可能致命。當兩者代價不對稱時，決策應該倒向代價可控的那一側——而這種倒向必須在出發前就說好，否則現場很難執行。",
    "q.m14#8.p" to "【配對】把決策偏誤與其典型表現對應起來。",
    "q.m14#8.l0" to "沉沒成本",
    "q.m14#8.l1" to "隊伍壓力",
    "q.m14#8.l2" to "目標執念",
    "q.m14#8.l3" to "風險正常化",
    "q.m14#8.r0" to "走了這麼遠，現在回去太可惜",
    "q.m14#8.r1" to "大家都想繼續，我不好意思說撤",
    "q.m14#8.r2" to "就差最後一段了",
    "q.m14#8.r3" to "上次這樣也沒出事",
    "q.m14#8.e" to "有意思的是，這四句話在事故覆盤裡出現頻率極高，而且說的人往往是經驗豐富的攀登者。這正說明它們不是「新手問題」，而是人的認知結構問題。",
    "q.m14#9.p" to "為什麼「經驗豐富」不等於「判斷更準」？",
    "q.m14#9.o0" to "因為經驗會讓人變慢",
    "q.m14#9.o1" to "因為經驗會讓人對風險的接受度逐步提高",
    "q.m14#9.o2" to "因為經驗不重要",
    "q.m14#9.o3" to "因為老手更固執",
    "q.m14#9.e" to "經驗帶來的是「熟悉」，而熟悉會降低警覺。因此經驗豐富的隊伍更需要外部約束（固定折返時間、量化的天氣門檻），用規則來對抗已經鈍化的直覺。",
    "q.m14#10.p" to "【排序】做出撤退決策的合理流程是？",
    "q.m14#10.o0" to "對照出發前約定的客觀訊號（時間、天氣、隊員狀態）",
    "q.m14#10.o1" to "核對實際狀況是否已經觸發其中任一條",
    "q.m14#10.o2" to "由預先指定的決策人宣佈撤退",
    "q.m14#10.o3" to "執行撤退並通知後方",
    "q.m14#10.e" to "流程的價值在於「先對標準、再看情況」——而不是先看情況、再討論標準。順序反了，標準就會被現場情緒一點點修改，最後變成「再看看」。",
    "q.m14#11.p" to "為什麼要事前指定「誰有權說撤」？",
    "q.m14#11.o0" to "為了方便追責",
    "q.m14#11.o1" to "因為現場很難自發產生一個敢於逆著隊伍情緒行動的人",
    "q.m14#11.o2" to "為了提升隊長威信",
    "q.m14#11.o3" to "為了記錄流程",
    "q.m14#11.e" to "撤退意味著否定全隊的期待，這在群體氛圍裡很難主動發起。把「說撤」變成一個事先授予的職責，而不是個人的勇敢行為——它才能真的發生。",
    "q.m14#12.p" to "什麼情況下應該考慮終止行程？",
    "q.m14#12.o0" to "只要還有可能登頂就不該終止",
    "q.m14#12.o1" to "觸發了預先約定的任一客觀訊號時",
    "q.m14#12.o2" to "只有隊員受傷時才終止",
    "q.m14#12.o3" to "由體力最差的人決定",
    "q.m14#12.e" to "「觸發即終止」是量化標準的全部意義：它把決策從「要不要」變成了「是否觸發」。前者需要爭論與說服，後者只需要核實事實——這也是它能在現場被執行的原因。",
    "q.m14#13.p" to "對抗目標執念最有效的做法是？",
    "q.m14#13.o0" to "靠個人意志力",
    "q.m14#13.o1" to "出發前把標準量化，讓「放寬」變成需要向隊友解釋的顯式行為",
    "q.m14#13.o2" to "不設定目標",
    "q.m14#13.o3" to "多帶裝備",
    "q.m14#13.e" to "心理偏誤無法靠「提醒自己別犯」來避免。可行的方法是把預設狀態設成「到時就撤」，而想繼續的人需要主動提出理由——這一下就把舉證責任反轉了。",
    "q.m14#14.p" to "為什麼「沒人反對」不等於「大家都同意」？",
    "q.m14#14.o0" to "因為大家可能沒聽見",
    "q.m14#14.o1" to "因為沉默可能只是不願破壞隊伍氣氛，而真實的疑慮未被表達",
    "q.m14#14.o2" to "因為有人睡著了",
    "q.m14#14.o3" to "因為反對無效",
    "q.m14#14.e" to "這就是為什麼好的隊伍會主動「製造反對」——比如領隊明確問「誰覺得不該繼續」，或者輪流讓每個人表個態。沉默在山上不代表同意，它只代表沒有表達。",
    "q.m14#15.p" to "填空：在不確定情況下做決策，應當優先採納最（ ）的意見。",
    "q.m14#15.a0" to "保守",
    "q.m14#15.e" to "「保守優先」是一條可以在現場直接執行的規則：不需要判斷誰的論據更強，只需要看哪個選項更保守。它的代價是可能白走一趟，但這是值得的代價。",
    "q.m14#16.p" to "情景：7000 公尺衝頂日的天氣惡化",
    "q.m14#16.c" to "你們在 7000 公尺的衝頂日，凌晨 3 點出發。上午 8 點到達距離頂峰約 2 小時的位置。此時風速明顯增強，雲層從西側快速壓過來，氣溫下降。隊伍中一名隊員開始出現持續咳嗽，速度明顯變慢。",
    "q.m14#16.e" to "這段情景的核心不是任何單點答案，而是順序：先核對事實 → 識別危險訊號 → 抵抗心理阻力 → 妥善執行撤退。四步裡最容易出錯的是第一步（被跳過）與第三步（被情緒接管）。",
    "q.m14#16.s0.p" to "第 1 步：此刻最先要做的判斷是什麼？",
    "q.m14#16.s0.o0" to "確認隊伍狀態與天氣趨勢，對照出發前約定的折返訊號",
    "q.m14#16.s0.o1" to "加快速度趕在天氣惡化前登頂",
    "q.m14#16.s0.o2" to "原地等待天氣好轉",
    "q.m14#16.s0.o3" to "讓速度慢的隊員獨自下撤",
    "q.m14#16.s0.e" to "任何決策都應從「事實核對」開始：隊員狀態如何、天氣在轉好還是轉壞、是否觸發了預設訊號。跳過這一步直接做決定，等於讓情緒代替判斷。",
    "q.m14#16.s1.p" to "第 2 步：隊員出現持續咳嗽，最合理的處理是？",
    "q.m14#16.s1.o0" to "只是被冷空氣刺激，繼續走",
    "q.m14#16.s1.o1" to "在高海拔需高度警惕與肺水腫相關的表現，應停止上升並儘快下撤",
    "q.m14#16.s1.o2" to "給他吃止咳藥後繼續",
    "q.m14#16.s1.o3" to "讓他休息 10 分鐘後繼續",
    "q.m14#16.s1.e" to "在 7000 公尺，靜息或輕微活動下的持續咳嗽是需要高度警惕的訊號。這個海拔上，「再觀察一段時間」的代價可能遠大於立刻下撤的代價。",
    "q.m14#16.s2.p" to "第 3 步：你已到達離頂峰兩小時的位置卻決定下撤，最大的心理阻力是什麼？",
    "q.m14#16.s2.o0" to "體力不足",
    "q.m14#16.s2.o1" to "沉沒成本與目標執念——「都走到這裡了」",
    "q.m14#16.s2.o2" to "裝備問題",
    "q.m14#16.s2.o3" to "對路線不熟",
    "q.m14#16.s2.e" to "這正是折返時間存在的意義：把決定提前到理性狀態下做出。當「就差一點」出現時，你需要的不是重新判斷，而是核對事先定好的規則。",
    "q.m14#16.s3.p" to "第 4 步：下撤過程中，隊伍應如何安排？",
    "q.m14#16.s3.o0" to "體力好的人先走，回營地做準備",
    "q.m14#16.s3.o1" to "保持全隊一起、由狀態最好的人帶路把控節奏，並把隊員狀況告知後方",
    "q.m14#16.s3.o2" to "分頭下撤以加快速度",
    "q.m14#16.s3.o3" to "讓狀態差的隊員單獨慢走",
    "q.m14#16.s3.e" to "在高海拔，隊伍一旦分散就失去了互相照應；而下撤階段恰恰是事故高發段。整隊行動、有人把控節奏、讓後方知情，三項缺一不可。",
    // ---------- q.m15 ----------
    "q.m15#0.p" to "雲圖判讀最核心的價值是？",
    "q.m15#0.o0" to "讓登山看起來更專業",
    "q.m15#0.o1" to "提供天氣變化的提前量",
    "q.m15#0.o2" to "代替氣象預報",
    "q.m15#0.o3" to "測量海拔",
    "q.m15#0.e" to "天氣預報可以提前一天知道，但山區天氣在小尺度上變很快。雲是「此刻就在你頭頂的預報」——它給的提前量可能只有一兩個小時，而這一兩個小時恰好是決定撤不撤的窗口。",
    "q.m15#1.p" to "積雲的垂直髮展說明什麼？",
    "q.m15#1.o0" to "天氣穩定",
    "q.m15#1.o1" to "對流強烈，可能向積雨雲發展",
    "q.m15#1.o2" to "即將降溫",
    "q.m15#1.o3" to "地面風力減弱",
    "q.m15#1.e" to "積雲本身並不危險，但它是一個「正在生長的訊號」。觀察的關鍵不是看它是積雲，而是看它在長大、長高、變暗——這個過程就是天氣在積累能量。",
    "q.m15#2.p" to "積雨雲的砧狀雲頂意味著什麼？",
    "q.m15#2.o0" to "正在形成階段",
    "q.m15#2.o1" to "已經發展到成熟階段，雷電、冰雹與強降水都可能出現",
    "q.m15#2.o2" to "即將消散",
    "q.m15#2.o3" to "只是高空風大",
    "q.m15#2.e" to "砧狀頂是雲頂被高空風吹開的形狀，說明上升氣流已經抵達對流層頂、無法再升高——這正是雷暴成熟階段的標誌。看到砧狀頂，意味著反應時間已經很少了。",
    "q.m15#3.p" to "積雲的形成多集中在一天中的什麼時候？",
    "q.m15#3.o0" to "凌晨",
    "q.m15#3.o1" to "上午",
    "q.m15#3.o2" to "下午",
    "q.m15#3.o3" to "深夜",
    "q.m15#3.e" to "原因在於日照：地面在白天被加熱，產生上升氣流與對流。這正是「早起衝頂、及時下撤」這條經驗背後的物理機制——而不是一句老話。",
    "q.m15#4.p" to "莢狀雲（蕈狀、盤狀）通常預示什麼？",
    "q.m15#4.o0" to "無風天氣",
    "q.m15#4.o1" to "強風",
    "q.m15#4.o2" to "即將降雨",
    "q.m15#4.o3" to "氣溫升高",
    "q.m15#4.e" to "莢狀雲是氣流翻越山脊時形成的駐波雲——它的存在本身就說明高空風速很大。在山上，這意味著暴露的山脊可能會有極強的陣風，而陣風是導致失去平衡的直接原因。",
    "q.m15#5.p" to "捲雲（絲縷狀、高空薄雲）明顯增多，通常預示？",
    "q.m15#5.o0" to "天氣系統正在靠近",
    "q.m15#5.o1" to "嚴寒即將結束",
    "q.m15#5.o2" to "即將無風",
    "q.m15#5.o3" to "紫外線會減弱",
    "q.m15#5.e" to "捲雲往往是天氣系統最外圍的「先頭部隊」——它出現時天氣還沒變，但它意味著變天正在路上。這可是很有用的提前量，特別對需要提前返回的行程。",
    "q.m15#6.p" to "層雲壓低、雲底明顯下降，最直接的影響是？",
    "q.m15#6.o0" to "氣溫升高",
    "q.m15#6.o1" to "能見度迅速惡化，地形判斷變困難",
    "q.m15#6.o2" to "風力減弱",
    "q.m15#6.o3" to "降水停止",
    "q.m15#6.e" to "層雲壓低帶來的不是「雨」，而是「看不見」——而去失視野本身就是獨立的風險：你可能已經偏離路線、可能接近雪簷、也可能錯過撤退岔口。",
    "q.m15#7.p" to "【多選】下列哪些雲的變化提示天氣正在轉壞？",
    "q.m15#7.o0" to "雲量迅速增加、雲層加厚",
    "q.m15#7.o1" to "雲底持續降低",
    "q.m15#7.o2" to "雲色變暗、垂直髮展明顯",
    "q.m15#7.o3" to "出現砧狀雲頂",
    "q.m15#7.o4" to "雲量開始減少、天空逐漸轉晴",
    "q.m15#7.e" to "這四項其實是同一個過程的不同階段：雲量增加 → 雲底降低 → 雲體變暗發展 → 出現砧狀頂。能按順序識別它們，就等於把「變天」從一瞬間的事件變成了可提前預警的過程。",
    "q.m15#8.p" to "為什麼山區的雲比平原發展得更劇烈？",
    "q.m15#8.o0" to "因為海拔高氣溫低",
    "q.m15#8.o1" to "因為地形強迫空氣抬升，加劇了對流",
    "q.m15#8.o2" to "因為紫外線強",
    "q.m15#8.o3" to "因為空氣稀薄",
    "q.m15#8.e" to "風碰到山體被強行抬升，就像被推上一道斜坡——抬升直接產生冷卻與凝結，因此雲的生成比平原更迅速、更區域性。這也是為什麼山區的天氣可以在很短時間內完全變樣。",
    "q.m15#9.p" to "如何判斷雲在「發展」而不是「消散」？",
    "q.m15#9.o0" to "看雲的顏色",
    "q.m15#9.o1" to "連續觀察雲的體積、高度與邊緣輪廓是否在增長與變硬",
    "q.m15#9.o2" to "看氣溫",
    "q.m15#9.o3" to "看積雪深度",
    "q.m15#9.e" to "關鍵在於「連續觀察」——單次看到的是狀態，兩次對比才能得出趨勢。發展中的雲體積在漲、雲頂在升高、邊緣由模糊變清晰；消散則相反。所以定時抬頭看一眼，成本幾乎為零，價值卻很高。",
    "q.m15#10.p" to "【配對】把雲型與其天氣含義對應起來。",
    "q.m15#10.l0" to "積雨雲（砧狀頂）",
    "q.m15#10.l1" to "莢狀雲",
    "q.m15#10.l2" to "捲雲",
    "q.m15#10.l3" to "低層雲",
    "q.m15#10.r0" to "雷暴、冰雹與強降水",
    "q.m15#10.r1" to "高空強風，山脊陣風猛烈",
    "q.m15#10.r2" to "天氣系統即將靠近",
    "q.m15#10.r3" to "能見度下降，地形判斷變困難",
    "q.m15#10.e" to "這四種雲覆蓋了山上最常遇到的四類天氣資訊。值得提醒的是：雲圖判讀需要看圖練習，本應用目前只有文字描述題——影象化的雲圖識別題等圖片管線接入後再補。",
    "q.m15#11.p" to "為什麼雲圖判讀必須和氣壓趨勢結合？",
    "q.m15#11.o0" to "為了資料完整",
    "q.m15#11.o1" to "因為雲反映的是當下狀態，氣壓趨勢才反映變化方向",
    "q.m15#11.o2" to "因為氣壓計更準",
    "q.m15#11.o3" to "為了計算海拔",
    "q.m15#11.e" to "兩者是不同的維度：雲告訴你「現在有什麼」，氣壓告訴你「正在往哪個方向走」。只看雲容易把「正在變壞」誤讀為「暫時陰天」——加上趨勢，判斷就完整了。",
    "q.m15#12.p" to "白化（whiteout）天氣的主要成因是？",
    "q.m15#12.o0" to "降雪過大",
    "q.m15#12.o1" to "雲、霧與雪面顏色接近，地面與天空的界線消失",
    "q.m15#12.o2" to "氣溫過低",
    "q.m15#12.o3" to "紫外線過強",
    "q.m15#12.e" to "白化不是「雪大」，而是「沒有對比」。雪面與雲層亮度接近時，地平線消失，人對距離與坡度的感知完全失真——這解釋了什麼它比普通降雪危險得多。",
    "q.m15#13.p" to "為什麼「區域性有雨」這類預報在山區意義有限？",
    "q.m15#13.o0" to "因為預報不準",
    "q.m15#13.o1" to "因為山區的天氣差異尺度遠小於預報網格，現場情況可能完全不同",
    "q.m15#13.o2" to "因為登山者不看預報",
    "q.m15#13.o3" to "因為降水不重要",
    "q.m15#13.e" to "預報的網格尺度可能是幾十公里，而一條山脊兩側的天氣就可能完全不同。預報提供的是「背景風險」，而現場判斷決定「今天能不能走」——兩者不能相互替代。",
    "q.m15#14.p" to "如果天氣預報說「晴天」但現場看到積雲在快速垂直髮展，應該相信哪個？",
    "q.m15#14.o0" to "相信預報，繼續按計劃",
    "q.m15#14.o1" to "相信現場觀察，按可能轉壞的假設做決策",
    "q.m15#14.o2" to "兩者取平均",
    "q.m15#14.o3" to "繼續觀察一小時再說",
    "q.m15#14.e" to "預報的時效與尺度都很粗，而現場觀察是「此刻此地」。當事物衝突時，現場證據優先——這也是整個天氣判斷體系的基本立場：預報定背景，現場定行動。",
    "q.m15#15.p" to "填空：看到閃電後數秒，每秒對應的距離約為（ ）公里。",
    "q.m15#15.a0" to "0.34",
    "q.m15#15.a1" to ".34",
    "q.m15#15.a2" to "零點三四",
    "q.m15#15.e" to "0.34 公里/秒是聲音在空氣中的傳播速度。這個換算讓「數秒」變成了可用的判斷工具——不需要任何裝置，就能知道雷暴是在靠近還是遠離。",
    "q.m15#16.p" to "【多選】下列哪些情況需要認真考慮立即下撤？",
    "q.m15#16.o0" to "積雲已發展為砧狀頂的積雨雲",
    "q.m15#16.o1" to "出現「whumpf」雪層塌陷聲",
    "q.m15#16.o2" to "能見度迅速下降且無法定位",
    "q.m15#16.o3" to "隊伍出現進行性加重的高原症狀",
    "q.m15#16.o4" to "隊員表示有點累，想原地休息十分鐘",
    "q.m15#16.e" to "這四項分別來自天氣、雪層、導航與生理四個維度——而它們的共同點是「都是進行性的」，這意味著現在的代價遠小於十分鐘後。下撤的決定越早，代價越低。",
    "q.m15#17.p" to "請在圖上點選代表「零度層（Freezing Level）」的那條曲線。",
    "q.m15#17.c" to "這份預報用分層的方式展示同一座山不同高度的天氣。圖例中的紫色曲線表示零度層——也就是雨雪分界線所在的高度。",
    "q.m15#17.e" to "零度層曲線是這份預報裡最有價值的資訊之一：它標出雨雪分界線當前在哪個高度。曲線上抬，說明暖溼氣流增強、降水形式會從雪轉雨；曲線下沉，說明冷空氣到位、高處會轉為降雪。判斷自己所在高度會不會遭遇降雪，看它比看氣溫數字更直接。",
    "q.m15#18.p" to "這是攀登季提前結束時的同一座山預報。Fri 25 三個時段（AM / PM / night）的降雪量分別是多少公分？請填入三者之和。",
    "q.m15#18.a0" to "280",
    "q.m15#18.e" to "58 + 88 + 134 = 280 公分。單日近 2.8 公尺的降雪量意味著：路線被徹底埋掉、雪崩風險急劇升高、營地存在被壓塌的可能。這種量級已經不是「能不能登頂」的問題，而是「能不能安全撤離」的問題——這也是攀登季被一個氣旋提前終結的典型方式。",
    "q.m15#19.p" to "情景：讀懂一份高海拔氣象預報",
    "q.m15#19.c" to "嚮導把兩份馬納斯魯的氣象預報擺在你面前——一份是正常攀登窗口，另一份是攀登季提前結束時的記錄。看懂它們，比記住任何數字都重要。",
    "q.m15#19.e" to "氣象判斷的落點從來不是「明天什麼天氣」，而是「這個窗口能不能行動」。同樣的介面，一份說明可以繼續，一份說明必須結束——區別不在會不會看圖，而在知不知道什麼條件下該停。",
    "q.m15#19.s0.p" to "第 1 步：在正常窗口那份預報裡，頂峰高度（8,163 m）那一行的粉色方塊代表什麼？",
    "q.m15#19.s0.o0" to "該時段預計的降雪量",
    "q.m15#19.s0.o1" to "該時段的降雨量",
    "q.m15#19.s0.o2" to "該時段的體感溫度",
    "q.m15#19.s0.o3" to "該時段的風速",
    "q.m15#19.s0.e" to "粉色代表降雪、藍色代表降雨——這份預報把不同高度的降水形式分開標註，正是因為它要回答的核心問題是「我所在的高度會下雪還是下雨」。頂部一行粉塊小而稀疏，說明頂峰有零星降雪但量級不大。",
    "q.m15#19.s1.p" to "第 2 步：對比攀登季結束那份預報，最顯著的變化是什麼？",
    "q.m15#19.s1.o0" to "只有氣溫下降",
    "q.m15#19.s1.o1" to "降雪量與風速同時劇增，降水覆蓋到全部高度層",
    "q.m15#19.s1.o2" to "降雨替代了降雪",
    "q.m15#19.s1.o3" to "零度層高度大幅上升",
    "q.m15#19.s1.e" to "降雪從「零星的 1–4 公分」變成「單日 280 公分」，風速從 25–30 km/h 升到 55–60 km/h，而且降水帶貫穿了從 8,163 m 到 1,500 m 的所有高度層。這三件事同時出現，就是一個天氣系統正面過境的簽名。",
    "q.m15#19.s2.p" to "第 3 步：如果你的隊伍正處在這種預報的窗口裡，正確的決策是什麼？",
    "q.m15#19.s2.o0" to "趁著天氣還沒完全變壞，加快衝頂",
    "q.m15#19.s2.o1" to "立即停止衝頂嘗試，按預案下撤併準備撤離",
    "q.m15#19.s2.o2" to "在高營原地等待天氣好轉",
    "q.m15#19.s2.o3" to "隊伍分成兩組，一組衝頂一組留守",
    "q.m15#19.s2.e" to "當預報顯示的是天氣系統正面過境，而不是短暫波動時，「等它過去」往往意味著在高海拔多暴露數天，而營地補給與帳篷狀態都撐不住。這也是為什麼很多攀登季的結束方式不是「登完了」，而是「必須撤了」——做出這個決定需要的資訊，恰好就是這兩張圖能給出的。",
    "q.m15#20.p" to "情景：讀懂一份逐小時預報",
    "q.m15#20.c" to "這是貢嘎山（7,556 m）某一天的逐小時預報。它的資訊密度比 16 天概覽高得多，但也更容易看錯行——關鍵在於知道每一行到底在說什麼。",
    "q.m15#20.e" to "逐小時預報回答的是概覽回答不了的問題：哪個具體時段能行動。零度層決定降水形式，體感溫度決定人扛不扛得住，風速和日照決定窗口有多寬。幾項疊在一起看，才能做出能執行的判斷。",
    "q.m15#20.s0.p" to "第 1 步：表中 Freeze 行顯示零度層高度在 4895～5304 m 之間，而貢嘎峰頂是 7556 m。這個組合意味著什麼？",
    "q.m15#20.s0.o0" to "山上的降水全部以雪的形式出現",
    "q.m15#20.s0.o1" to "峰頂會有降雨",
    "q.m15#20.s0.o2" to "零度層以下也會下雪",
    "q.m15#20.s0.o3" to "無法據此判斷降水形式",
    "q.m15#20.s0.e" to "零度層是雨雪分界線。它穩定在 4,900～5,300 m，而所有攀登路線都在這個高度之上。也就是說，整條路線都在零度層以上，任何降水都會以雪的形式落下。一個數就能回答「我會遇到什麼形式的降水」，這就是零度層比氣溫數字好用的地方。",
    "q.m15#20.s1.p" to "第 2 步：Feels °C 一行顯示 -18 至 -21，而 Max / Min °C 只有 -10 至 -11。這個差異主要來自什麼？",
    "q.m15#20.s1.o0" to "天氣預報誤差",
    "q.m15#20.s1.o1" to "風寒效應——風速越大，體感溫度越低",
    "q.m15#20.s1.o2" to "海拔高度造成的溫差",
    "q.m15#20.s1.o3" to "溼度變化的影響",
    "q.m15#20.s1.e" to "同一時段風速在 20～30 km/h。風吹過裸露皮膚會加快散熱，所以體感（Feels）比實測氣溫低了近 10℃。在高原，能不能待得住看的是體感溫度，不是氣溫。同樣是 -10℃，有風和沒風完全是兩回事。",
    "q.m15#20.s2.p" to "第 3 步：綜合這份預報（風速 20～30 km/h、零星降雪 2/1/1 公分、體感約 -20℃、日照 6:56–19:15），對這個窗口的判斷是？",
    "q.m15#20.s2.o0" to "天氣惡劣，應完全放棄行動",
    "q.m15#20.s2.o1" to "屬於相對可行動的窗口，主要挑戰是低溫與風寒而非降水",
    "q.m15#20.s2.o2" to "降水過多，存在雪崩風險",
    "q.m15#20.s2.o3" to "資料不足，無法判斷",
    "q.m15#20.s2.e" to "風速 20～30 km/h 還在可行動範圍，降雪量也很小，只有幾公分。真正的壓力來自 -20℃ 左右的體感，凍傷和失溫才是要防的。這類窗口的判斷邏輯是：降水和風都還好，溫度和時長才是問題。所以要縮短暴露時間、加強末端保暖，折返時間也要往前提。",
    "q.m15#21.p" to "同一份貢嘎預報裡，實測氣溫約 -11℃，而體感最低到 -21℃。兩者相差多少攝氏度？",
    "q.m15#21.a0" to "10",
    "q.m15#21.e" to "10℃。計算是 -11 -（-21）= 10。這個差值本身就是決策資訊：穿多少要按體感準備，不能按氣溫。也解釋了為什麼有人在 -10℃ 裡凍傷，他們是照著氣溫穿的衣服。",
    "q.m15#22.p" to "這份預報把風速顯示為綠色圓圈，最可能代表什麼？",
    "q.m15#22.o0" to "該時段風速處於適宜攀登的範圍內",
    "q.m15#22.o1" to "該時段風速達到了危險水平",
    "q.m15#22.o2" to "該時段有降雨",
    "q.m15#22.o3" to "該時段風速資料缺失",
    "q.m15#22.e" to "專業登山氣象服務通常會按風速對行動的影響做顏色編碼。20～30 km/h 標成綠色，說明落在「可以行動」的區間；再往上，顏色會轉黃或紅。\n但顏色只是服務商的建議，不是你的判斷標準。不同路線、不同隊伍對同一風速的承受能力並不一樣。讀懂數字，比讀懂顏色更重要。",
    "q.m15#23.p" to "這張專業介面把 8000 / 6000 / 4000 / 2000 公尺分成四行並列展示溫度。這樣設計的主要價值是什麼？",
    "q.m15#23.o0" to "可以直接讀出自己所在高度的預報，不必從低海拔資料外推",
    "q.m15#23.o1" to "讓頁面看起來更豐富",
    "q.m15#23.o2" to "表示這四行之間沒有關聯",
    "q.m15#23.o3" to "只是為了方便印刷成紙質表格",
    "q.m15#23.e" to "普通天氣預報給的是某一個地點的資料，通常來自最近的城市或機場。你要自己按遞減率推算山上的情況，這一步既容易算錯，也丟掉了地形細節。\n專業登山氣象服務反過來做：先把山按高度切成層，再分別給出每層的預報。你只要找到「明天自己會待在哪個高度」那一行，直接讀。判斷一份氣象服務夠不夠用，這也是個簡單標準：它有沒有按高度分層。",
    "q.m15#24.p" to "圖中「雲底高度（米）」一行在多數時段顯示為空（—）。正確的理解是？",
    "q.m15#24.o0" to "該時段雲底高度為零，即雲層貼地",
    "q.m15#24.o1" to "該時段沒有提供雲底資料，不能當作「雲底為 0」",
    "q.m15#24.o2" to "表示該時段完全沒有云",
    "q.m15#24.o3" to "表示雲底高度超過了山峰高度",
    "q.m15#24.e" to "氣象表裡的「空」和「零」是兩件完全不同的事。空值表示這個專案在這一時段沒有資料，可能是不覆蓋，也可能是給不出有意義的估計，它不等於「值為零」。\n把空值當成零，會得出「雲層貼地、能見度極差」這種跟事實無關的結論。讀任何氣象表，先分清這兩者。這是看預報最容易出錯、也最少被提醒的一個細節。",
    "q.m15#25.p" to "這份介面的風速行裡，除了數字還帶有箭頭符號。箭頭最可能表示什麼？",
    "q.m15#25.o0" to "風速的變化趨勢",
    "q.m15#25.o1" to "風的方向",
    "q.m15#25.o2" to "降水機率",
    "q.m15#25.o3" to "氣溫升降",
    "q.m15#25.e" to "風速和風向在高海拔要一起看。同樣是 30 km/h，迎風面和背風面的體感完全不同，對雪層的影響也兩樣：風會把雪搬到背風坡，堆成雪板。這是判斷雪崩時最關鍵的資訊之一。\n只看風速數字、不看風向，等於丟了一半資訊。專業介面把箭頭放在數字旁邊，就是因為這兩者不能分開讀。",
    "q.m15#26.p" to "這張 16 天預報圖上，紅色標記（Snow）集中在約 6000 公尺帶，藍色標記（Rain）出現在 5000 公尺以下。這說明什麼？",
    "q.m15#26.o0" to "雨雪分界線大約在 5,500～6,000 公尺之間",
    "q.m15#26.o1" to "山上只下雪不下雨",
    "q.m15#26.o2" to "降雨會一直持續到峰頂",
    "q.m15#26.o3" to "無法從這張圖判斷",
    "q.m15#26.e" to "這張圖不告訴你「某地幾點下什麼」，它直接回答「降水會落在哪個高度帶」。對登山者來說，這正是最要緊的資訊。\n紅色出現在 6,000 公尺帶、藍色都在 5,000 公尺以下，說明雨雪分界線大致在 5,500～6,000 公尺之間。再配合圖例裡的紫色零度層曲線（它從約 6,000 公尺下降到約 4,800 公尺），還能看出這條分界線在預報期內會繼續下移：原本下雨的高度帶，會慢慢轉成下雪。\n同樣的降水量，下雨還是下雪，對行程的影響完全不同。",
    "q.m15#27.p" to "同一張圖的逐小時預報裡，下午 5 點出現了閃電圖示。在高原，這個訊號意味著什麼？",
    "q.m15#27.o0" to "只是圖示好看，無需特別處理",
    "q.m15#27.o1" to "雷暴風險，應把行程安排在上午，並在午後離開山脊與暴露區域",
    "q.m15#27.o2" to "說明馬上要下大雨，帶好雨衣即可",
    "q.m15#27.o3" to "表示風速會增大到危險水平",
    "q.m15#27.e" to "高原的午後雷暴很常見，也很危險。地形抬升讓積雲在下午迅速長起來。所以「早出發」不只是為了雪坡更硬，也是為了在雷暴成形前離開暴露地形。\n遭遇雷暴時的要點：遠離山頂、山脊、孤立大樹與水面；不要平躺在地面；隊伍彼此拉開約 50 公尺距離，避免一次雷擊造成多人受傷。雷電距離可以用「閃電與雷聲的秒數差 × 0.34」估算公里數。",
    "q.m15#28.p" to "關於兩種地形資料來源裡「有沒有峰頂地標」這件事，正確的取捨是？",
    "q.m15#28.o0" to "有地標就一定更準確，應當只信有地標的圖",
    "q.m15#28.o1" to "地標便於快速定位與溝通，但要精確判斷地形仍須回到等高線",
    "q.m15#28.o2" to "沒有地標的圖沒有使用價值",
    "q.m15#28.o3" to "地標只會干擾判讀，應當忽略",
    "q.m15#28.e" to "慕士塔格這張谷歌地圖上，峰頂被一個紅色地標直接標出。定位和溝通時這很好用：你能立刻知道目標在哪，也能向隊友說清是哪個位置。\n但地標不解決「這段坡有多陡、營地能設在哪」。精確的地形判斷還是要靠等高線，地標本身不參與這個判斷。\n更實際的做法是：用地標快速定位，再用高精度等高線（比如 SRTM 那版）讀坡度和地形細節。兩者各幹各的活。",
    // ---------- q.m16 ----------
    "q.m16#0.p" to "進階雪崩判斷需要綜合哪三個尺度？",
    "q.m16#0.o0" to "氣溫、風速、降水",
    "q.m16#0.o1" to "區域預報、地形、雪層",
    "q.m16#0.o2" to "海拔、坡度、日照",
    "q.m16#0.o3" to "隊伍人數、裝備、時間",
    "q.m16#0.e" to "三個尺度回答三個不同問題：預報答「今天整體風險多大」，地形答「這個坡能不能積雪並滑動」，雪層答「此刻它穩不穩」。只看預報，等於拿區域平均去判斷腳下這一個坡。",
    "q.m16#1.p" to "雪崩危險等級中，哪一級的事故最集中？",
    "q.m16#1.o0" to "1（低）",
    "q.m16#1.o1" to "3（相當危險）",
    "q.m16#1.o2" to "5（極高）",
    "q.m16#1.o3" to "沒有差別",
    "q.m16#1.e" to "等級 5 時人們普遍迴避，事故反而少；等級 3 時地形「看起來可以走」，於是大量人進入雪崩地形。最危險的從來不是極端條件，而是被低估的中等條件。",
    "q.m16#2.p" to "大多數雪崩集中發生的坡度區間是？",
    "q.m16#2.o0" to "10°～25°",
    "q.m16#2.o1" to "34°～45°",
    "q.m16#2.o2" to "55°～70°",
    "q.m16#2.o3" to "沒有規律",
    "q.m16#2.e" to "約 96% 的雪崩發生在 30°～50° 之間，其中大多數集中在 34°～45°。這個角度恰好是登山路線最常經過的區間——它既陡到能滑動，又緩到能積雪。",
    "q.m16#3.p" to "【多選】透過雪崩地形時的正確做法包括？",
    "q.m16#3.o0" to "拉開間距、一人一人透過",
    "q.m16#3.o1" to "指定位於安全位置的觀察員",
    "q.m16#3.o2" to "提前規劃撤離路線",
    "q.m16#3.o3" to "全隊同時快速透過以縮短暴露時間",
    "q.m16#3.e" to "前兩項把風險限制在單個人身上；第三項保證事發生時有退路。而「全隊同時透過」恰好相反——它把風險從「可能埋一個人」變成「可能埋全隊」，是最不該選的選項。",
    "q.m16#4.p" to "觀察員應該站在什麼位置？",
    "q.m16#4.o0" to "正在透過的坡面上",
    "q.m16#4.o1" to "能清楚看到透過者、且自身安全的位置",
    "q.m16#4.o2" to "坡頂最高處",
    "q.m16#4.o3" to "谷底",
    "q.m16#4.e" to "觀察員有兩個任務：目送回透過者（知道被埋位置），以及在事故發生時立即行動。站在坡面上或谷底都會讓他自身成為第二個受害者——觀察員自身安全是履行職責的前提。",
    "q.m16#5.p" to "挖雪坑觀察的目的是？",
    "q.m16#5.o0" to "為了休息",
    "q.m16#5.o1" to "直接檢視雪層結構、弱層位置與硬度差異",
    "q.m16#5.o2" to "為了測量溫度",
    "q.m16#5.o3" to "為了拍照記錄",
    "q.m16#5.e" to "雪崩是由「弱層 + 上覆板層」共同導致的，而這個結構必須切開才能看到。雪坑把看不見的內部結構變成了可見的證據——這是從「推測風險」到「觀察風險」的關鍵一步。",
    "q.m16#6.p" to "為什麼「跟著前人足跡走」很危險？",
    "q.m16#6.o0" to "因為足跡不清晰",
    "q.m16#6.o1" to "因為足跡可能是幾小時前留下的，而雪層條件早已改變",
    "q.m16#6.o2" to "因為會走錯路",
    "q.m16#6.o3" to "因為足跡會阻礙行走",
    "q.m16#6.e" to "雪層條件隨溫度、風與降雪持續變化，幾小時就足以從「勉強穩定」變成「隨時可能觸發」。足跡只能證明「當時有人過去了」，不能證明「現在安全」。",
    "q.m16#7.p" to "風載（wind loading）如何影響雪崩風險？",
    "q.m16#7.o0" to "風會把雪吹平，降低風險",
    "q.m16#7.o1" to "風把雪搬到背風坡堆積，形成額外的雪板與弱層，大幅提高風險",
    "q.m16#7.o2" to "風與雪崩無關",
    "q.m16#7.o3" to "風只會影響能見度",
    "q.m16#7.e" to "風是最被低估的「雪崩製造者」：它能在短時間內把大量雪搬到背風坡，堆出厚的雪板並在內部形成弱層。所以即便沒有下雪，大風之後也可能出現新的雪崩危險。",
    "q.m16#8.p" to "雪簷（cornice）的主要危險是？",
    "q.m16#8.o0" to "影響視線",
    "q.m16#8.o1" to "它可能自己在任何時刻斷裂，也可能在斷裂後觸發下方坡面的雪崩",
    "q.m16#8.o2" to "顏色與雪面不同",
    "q.m16#8.o3" to "阻礙前進路線",
    "q.m16#8.e" to "雪簷的危險是雙重的：你站上去可能隨著它一起塌，或者你從下方透過時它帶著大量雪一起砸下來。因此一般選擇從遠離簷脊的一側繞行，而且絕不在簷上休息。",
    "q.m16#9.p" to "【排序】透過雪崩地形的完整流程是？",
    "q.m16#9.o0" to "出發前檢視當日雪崩預報，並標出需避開的坡面",
    "q.m16#9.o1" to "接近前觀察現場訊號（裂縫、塌陷聲、風載雪面）",
    "q.m16#9.o2" to "確定觀察員、透過順序與撤離路線",
    "q.m16#9.o3" to "一人一人透過，保持間距並在安全點匯合",
    "q.m16#9.e" to "前三步都在「進入之前」完成——這才是雪崩安全的真實工作重心。一旦踏上坡面，剩下的選擇已經很少了；大多數事故的根因都在「沒做前兩步」。",
    "q.m16#10.p" to "為什麼雪崩救援必須由同伴立即完成？",
    "q.m16#10.o0" to "因為專業救援收費高",
    "q.m16#10.o1" to "因為被埋者的存活窗口只有十幾分鍾",
    "q.m16#10.o2" to "因為專業救援不願上山",
    "q.m16#10.o3" to "因為同伴更熟悉地形",
    "q.m16#10.e" to "十幾分鐘的存活窗口意味著「能救你的人只有身邊的同伴」。這也直接解釋了為什麼雪崩三件套必須隨身、且必須練熟——帶著不會用，等於沒帶。",
    "q.m16#11.p" to "【配對】把雪崩危險等級與其含義對應起來。",
    "q.m16#11.l0" to "1 級",
    "q.m16#11.l1" to "3 級",
    "q.m16#11.l2" to "4 級",
    "q.m16#11.l3" to "5 級",
    "q.m16#11.r0" to "低：自然與人為觸發都很少",
    "q.m16#11.r1" to "相當危險：人為觸發可能，且最容易被低估",
    "q.m16#11.r2" to "高：自然觸發可能，應避免雪崩地形",
    "q.m16#11.r3" to "極高：大規模自然雪崩很可能發生",
    "q.m16#11.e" to "等級數字背後是「觸發可能性」與「後果規模」的組合。入門者最容易犯的錯是把 3 級當成「還好」——而它恰恰是事故最集中的等級。",
    "q.m16#12.p" to "雪崩氣囊的作用與侷限分別是？",
    "q.m16#12.o0" to "能完全防止被埋；沒有侷限",
    "q.m16#12.o1" to "增加被埋深度變淺的機率；但不能替代信標、探杆與雪鏟，也不能避免創傷",
    "q.m16#12.o2" to "只用於滑雪場",
    "q.m16#12.o3" to "能自動呼救",
    "q.m16#12.e" to "氣囊的原理是「體積變大、更可能浮在雪面上」，它能提高倖存率但不能保證。而且雪崩致死的相當一部分來自創傷而不是窒息——這一點讓氣囊無法成為唯一依靠。",
    "q.m16#13.p" to "為什麼「看起來不太陡」的坡反而最危險？",
    "q.m16#13.o0" to "因為雪更厚",
    "q.m16#13.o1" to "因為 34°～45° 正是雪崩最集中區間，而人眼容易低估坡度",
    "q.m16#13.o2" to "因為走的人少",
    "q.m16#13.o3" to "因為坡度變化快",
    "q.m16#13.e" to "人在沒有參照物時對坡度的估計誤差很大，往往把 35° 看成 25°。而 30°～35° 恰好是「看起來能走、實際能滑動」的區間。坡角計與地形圖是這個偏差的解藥。",
    "q.m16#14.p" to "【多選】進入雪崩地形前，隊伍應該完成哪些準備？",
    "q.m16#14.o0" to "確認每個人都會使用信標、探杆與雪鏟",
    "q.m16#14.o1" to "明確透過順序與觀察員",
    "q.m16#14.o2" to "約定集合點與撤離路線",
    "q.m16#14.o3" to "檢查信標處於發射狀態",
    "q.m16#14.o4" to "反覆用力跺腳測試雪層穩定性",
    "q.m16#14.e" to "這四項都屬於「進入前的最後檢查」，全部只需幾分鐘。它們之所以重要，是因為一旦進入坡面，你就只剩「祈禱不會發生」這一個選項了。",
    "q.m16#15.p" to "雪層發出「whumpf」塌陷聲，正確的反應是？",
    "q.m16#15.o0" to "繼續前進，只是雪層壓實",
    "q.m16#15.o1" to "立即停止前進並重新評估，說明弱層已開始破壞",
    "q.m16#15.o2" to "加快速度透過",
    "q.m16#15.o3" to "原地休息十分鐘",
    "q.m16#15.e" to "whumpf 是弱層正在崩陷的直接證據——它意味著你剛剛用一個很輕的載荷觸發了區域性破壞。繼續前進等於在問「再加一點會不會全崩」。",
    "q.m16#16.p" to "填空：約 96% 的雪崩發生在 30°～50° 的坡面上，其中大多數集中在 34°～（ ）° 之間。",
    "q.m16#16.a0" to "45",
    "q.m16#16.a1" to "四十五",
    "q.m16#16.e" to "34°～45°。這個區間值得記住，因為它既是雪崩高發區，也是登山路線最常經過的坡度——兩個事實重疊在一起，才讓雪崩成為高山攀登最主要的客觀危險之一。",
    "q.m16#17.p" to "情景：透過一段雪崩地形",
    "q.m16#17.c" to "路線必須穿過一段 35° 左右的雪坡，長度約 200 公尺。當日雪崩預報為「相當危險（3 級）」，近期有 30 公分新雪，風向西北，坡面朝東南。",
    "q.m16#17.e" to "這段情景檢驗的是雪崩判斷的完整流程：讀地形與雪況 → 進入前完成準備 → 用隊形控制後果。每一步都不難，難的是在「看起來能走」的坡面前把它們全部執行。",
    "q.m16#17.s0.p" to "第 1 步：這段坡面最需要警惕的是什麼？",
    "q.m16#17.s0.o0" to "落石",
    "q.m16#17.s0.o1" to "風載形成的雪板與坡面本身的坡度",
    "q.m16#17.s0.o2" to "高溫",
    "q.m16#17.s0.o3" to "地表植被",
    "q.m16#17.s0.e" to "35° 正好落在 34°–45° 的高發區間；西北風會把雪搬到背風坡（這裡是東南坡），形成額外雪板。兩個因素疊加，正是「看似能走、實際能滑」的典型組合。",
    "q.m16#17.s1.p" to "第 2 步：接近坡面時，應該先做什麼？",
    "q.m16#17.s1.o0" to "直接開始透過",
    "q.m16#17.s1.o1" to "先觀察現場訊號，確定觀察員、透過順序與撤離路線",
    "q.m16#17.s1.o2" to "先在坡面上用力跺腳測試",
    "q.m16#17.s1.o3" to "全隊同時快速透過",
    "q.m16#17.s1.e" to "所有準備工作都應在「進入之前」完成。用力跺腳不僅不能驗證穩定性，還可能直接觸發本已接近臨界狀態的雪層。",
    "q.m16#17.s2.p" to "第 3 步：透過時隊形應如何安排？",
    "q.m16#17.s2.o0" to "一人一人透過，其餘人在安全點等待",
    "q.m16#17.s2.o1" to "全隊手拉手一起走",
    "q.m16#17.s2.o2" to "兩人並行以便互相照應",
    "q.m16#17.s2.o3" to "排成一列緊跟前行",
    "q.m16#17.s2.e" to "一人透過把風險限制在單個人身上，也讓觀察員能專注目送一個人。而全隊同時暴露，會把後果從「可能埋一人」放大為「可能埋全隊」。",
    "q.m16#18.p" to "請在圖上點選馬納斯魯峰頂所在的大致區域。",
    "q.m16#18.c" to "這是一張由 NASA SRTM 高程資料生成的馬納斯魯等高線地形圖，等高距 50 公尺，圖上標註的是各條等高線的海拔。",
    "q.m16#18.e" to "峰頂在地形圖上的特徵很明確：閉合等高線層層向內收攏，海拔標註逐級升高（7600 → 7750 → 7900 → 7950 …）。找到那個被一圈圈小閉合曲線包住的點，就是最高處。\n反過來，等高線向外發散、標註持續下降的方向，就是山體下坡的方向——這也順便告訴你哪一側是攀登路線會走的坡面。",
    "q.m16#19.p" to "同一張圖上，東北—東側的等高線極為密集，這說明什麼？",
    "q.m16#19.o0" to "該側坡度極陡，是冰崩與落石的高發區",
    "q.m16#19.o1" to "該側是緩坡，適合建營地",
    "q.m16#19.o2" to "該側海拔較低，風險較小",
    "q.m16#19.o3" to "等高線密集說明該區域地形平坦",
    "q.m16#19.e" to "等高線越密集，說明同樣的水平距離內海拔變化越大——也就是坡越陡。圖中東北側從 7950 m 一路降到 5750 m，幾十條等高線擠在很短的水平距離裡，這是典型的陡壁。\n在計劃路線時，這種讀圖能力直接關係到兩件事：會不會經過冰崩與落石區，以及遇到意外時有沒有可用的撤退地形。圖中相對平緩、等高線稀疏的區域，才是更可能設定營地的地方。",
    "q.m16#20.p" to "情景：兩種地形資料來源的對比",
    "q.m16#20.c" to "嚮導給了你同一座山的兩種地形圖：一張來自谷歌地圖，一張由 NASA SRTM 高程資料生成。兩張圖都沒有錯，但它們回答問題的能力並不一樣。",
    "q.m16#20.e" to "地形資料的核心差別不是準不準，而是等高距。等高距決定你能看出多細的坡度變化。直觀當然有價值，能幫你快速建立整體印象；但要判斷某一段到底陡不陡、能不能過，還是得回到等高線密度這個能量化、能比較的依據。",
    "q.m16#20.s0.p" to "第 1 步：在這張谷歌地圖上，等高線的海拔標註依次是 6200、6400、6600、6800…。它的等高距是多少？",
    "q.m16#20.s0.o0" to "50 公尺",
    "q.m16#20.s0.o1" to "100 公尺",
    "q.m16#20.s0.o2" to "200 公尺",
    "q.m16#20.s0.o3" to "500 公尺",
    "q.m16#20.s0.e" to "相鄰標註相差 200 公尺，說明這條等高線系統裡每兩條線之間就上升 200 公尺。200 公尺等高距適合看整體山形，但兩線之間的地形細節（比如一段 40 公尺落差的岩壁）在圖上就完全消失了。",
    "q.m16#20.s1.p" to "第 2 步：SRTM 這張圖的等高距是 50 公尺。相比谷歌那張 200 公尺的圖，它最實質的優勢是什麼？",
    "q.m16#20.s1.o0" to "畫面更好看",
    "q.m16#20.s1.o1" to "同樣的水平距離裡線更密，能分辨 4 倍細的坡度變化",
    "q.m16#20.s1.o2" to "顏色更鮮豔",
    "q.m16#20.s1.o3" to "標註的文字更大",
    "q.m16#20.s1.e" to "等高距越小，能分辨的地形細節越多。判斷「這段坡能不能走」靠的正是等高線密度：200 公尺間距的畫法會把一段 150 公尺的陡坎「抹平」成緩坡，而 50 公尺間距能把它如實畫出來。\n這也是為什麼技術路線的地形評估更依賴 SRTM 這類高精度資料來源。",
    "q.m16#20.s2.p" to "第 3 步：谷歌地圖那版有明顯的深淺陰影，看起來很「立體」。判斷坡面陡緩時應當如何看待這些陰影？",
    "q.m16#20.s2.o0" to "陰影越深說明坡越陡，可以直接作為依據",
    "q.m16#20.s2.o1" to "陰影只是光照與坡向的關係，不能直接當作坡度依據",
    "q.m16#20.s2.o2" to "陰影表示積雪覆蓋區域",
    "q.m16#20.s2.o3" to "陰影表示海拔高於 7000 公尺的區域",
    "q.m16#20.s2.e" to "地形陰影（relief shading）模擬的是陽光從某個方向照過來時坡面的明暗關係。深色只說明這個坡背光，不代表它陡。一個朝北的緩坡，可能比朝南的陡坡更暗。\n把陰影當坡度用，是地形判讀裡常見也很危險的誤讀。陰影適合建立整體印象；要量化坡度，還得看等高線密度，最好再用帶海拔標註的高精度資料複核一遍。",
    "q.m16#21.p" to "關於「谷歌地圖直觀但精度不高、SRTM 精度高但不直觀」這個說法，正確的理解是？",
    "q.m16#21.o0" to "SRTM 更準確，所以谷歌地圖沒有使用價值",
    "q.m16#21.o1" to "兩者應當配合使用：先用直觀圖建立整體印象，再用高精度等高線做量化判斷",
    "q.m16#21.o2" to "谷歌地圖更直觀，因此判斷坡面時應優先相信它",
    "q.m16#21.o3" to "兩者只是配色不同，資訊量相同",
    "q.m16#21.e" to "這兩種資料來源解決的是不同問題。谷歌地圖的地形陰影和地名標註，幫你快速建立空間感：山在哪、大體什麼形狀、路線朝哪邊。SRTM 的 50 公尺等高線，用來做可量化的判斷：這段坡多少度、有沒有能設營的地方。\n用直觀圖做篩查，用高精度圖做確認，這樣最實際。只用其中一種，要麼慢，要麼錯。",
    "q.m16#22.p" to "請在圖上點選珠穆朗瑪峰峰頂所在的大致區域。",
    "q.m16#22.c" to "這是珠峰–洛子峰一帶的 SRTM 等高線地形圖，圖上同時能看到兩座 8000 公尺級山峰。",
    "q.m16#22.e" to "判斷峰頂，找海拔標註最高的閉合等高線。圖上這一帶的標註升到 8600、8700 m，閉合圈層層向內收攏，最裡面就是峰頂（8,848 m）。\n注意區分「高」和「陡」：峰頂區域往往不是坡面最陡的地方，最陡的坡在等高線最密的地方。判斷路線風險時這一點很關鍵：登頂考驗的是適應和體能，技術風險主要在上下山途中的幾段坡上。",
    "q.m16#23.p" to "同一張圖上，珠峰與洛子峰兩處密集閉合等高線之間，有一片等高線明顯變稀、並略微下凹的區域。它在地形上是什麼？",
    "q.m16#23.o0" to "一處冰川源頭",
    "q.m16#23.o1" to "兩峰之間的鞍部",
    "q.m16#23.o2" to "山脊的最高點",
    "q.m16#23.o3" to "一條陡崖",
    "q.m16#23.e" to "兩處密集閉合的高點之間，等高線變稀、地勢下凹，那就是鞍部（山坳）。珠峰和洛子峰之間的這個鞍部就是南坳（South Col，約 7,900 m），珠峰南坡路線的四號營地就設在這裡，也是衝頂前的最後一站。\n在等高線圖上認出鞍部很實用。它通常意味著強風、暴露，但地形相對平緩。適合紮營，卻不適合久留，所以衝頂營地大多設在鞍部，而且當天夜裡就走。",
    "q.m16#24.p" to "請在圖上點選慕士塔格峰峰頂所在的大致區域。",
    "q.m16#24.c" to "這是慕士塔格峰（7,509 m）的 SRTM 等高線地形圖。它的頂部不是尖峰，而是一片寬廣的穹狀雪原。",
    "q.m16#24.e" to "慕士塔格的峰頂形態很有代表性：一座穹狀山，頂部平緩寬闊，最高處的閉合等高線分佈得很散，不像尖峰那樣層層緊收。找這類峰頂，看海拔標註的最高值（這裡是 7,500 m）和它所在的閉合環。\n形態會直接影響攀登體驗。穹狀山意味著頂峰段不陡，但要走很久；起伏小、沒有明顯地標，下撤時容易在雪原上失去方向感。這也是慕士塔格常被提到的一個風險點。",
    // ---------- q.m17 ----------
    "q.m17#0.p" to "高海拔營地管理的核心目標是？",
    "q.m17#0.o0" to "把營地建得舒適",
    "q.m17#0.o1" to "用最小的消耗維持戰鬥力",
    "q.m17#0.o2" to "節省燃料",
    "q.m17#0.o3" to "拍出好看的照片",
    "q.m17#0.e" to "高海拔的每一分體力都是有限資源，而營地是唯一能「回血」的地方。因此營地管理的一切決定都應當回答同一個問題：這樣做能不能讓隊伍明天狀態更好？",
    "q.m17#1.p" to "營地選址時，首要考慮的因素是？",
    "q.m17#1.o0" to "風景與視野",
    "q.m17#1.o1" to "避開雪崩路徑、冰崩區、雪簷下方與冰裂縫",
    "q.m17#1.o2" to "離水源近",
    "q.m17#1.o3" to "離路線起點近",
    "q.m17#1.e" to "選址的第一原則是「不被客觀危險砸到」——因為營地是你要停留數小時甚至整天、並且幾乎無法快速移動的地方。視野與便利都是次要變數。",
    "q.m17#2.p" to "為什麼不能在雪簷下方紮營？",
    "q.m17#2.o0" to "因為地面不平",
    "q.m17#2.o1" to "因為雪簷可能在任何時刻斷裂，大量雪冰會直接砸向營地",
    "q.m17#2.o2" to "因為風大",
    "q.m17#2.o3" to "因為看不見風景",
    "q.m17#2.e" to "雪簷的斷裂沒有可預測的預警：它可能在午後升溫時、也可能在凌晨最冷時崩落。把營地放在它下方，等於接受一個「無法監測、無法提前反應」的持續威脅。",
    "q.m17#3.p" to "【多選】營地選址應當避開的區域包括？",
    "q.m17#3.o0" to "雪崩路徑下方",
    "q.m17#3.o1" to "雪簷正下方或上方",
    "q.m17#3.o2" to "明顯的冰裂縫區",
    "q.m17#3.o3" to "冰崩可及範圍",
    "q.m17#3.o4" to "風景開闊、視野良好的觀景點",
    "q.m17#3.e" to "這四類都是「客觀危險恰好落點在營地」的情形。它們的共同特點是難以監測、且一旦發生就是團體級後果——所以營地的選址標準應當比行進路線更保守。",
    "q.m17#4.p" to "燃料與食品應該怎麼分配？",
    "q.m17#4.o0" to "全部集中由一人保管",
    "q.m17#4.o1" to "按日子分裝，並預留應急份額",
    "q.m17#4.o2" to "全部放在帳篷門口",
    "q.m17#4.o3" to "按人數平攤，不留餘量",
    "q.m17#4.e" to "按日分裝讓消耗可追蹤，預留應急份額則保證任何情況下都還有「安全下撤所需的能量」。在山上，燃料不只是煮飯——它也是化雪取水、烘乾衣物、維持體溫的手段。",
    "q.m17#5.p" to "為什麼要預留應急份額？",
    "q.m17#5.o0" to "因為食物會變質",
    "q.m17#5.o1" to "為了保證在任何情況下都有安全下撤所需的燃料與食物",
    "q.m17#5.o2" to "因為商家要求",
    "q.m17#5.o3" to "為了減輕返回時的負重",
    "q.m17#5.e" to "應急份額針對的是最壞情形：天氣變差、被迫多停留一天、有人受傷需要緩慢下撤。如果所有資源都按「最佳時間表」分配，一旦延誤就會變成「既沒有補給也無法前進」的困境。",
    "q.m17#6.p" to "夜間應該如何處理電子裝置（手機、相機、頭燈電池）？",
    "q.m17#6.o0" to "放在帳篷外面",
    "q.m17#6.o1" to "貼身或放入睡袋保溫",
    "q.m17#6.o2" to "放在揹包最外層",
    "q.m17#6.o3" to "不需要處理",
    "q.m17#6.e" to "鋰電池在低溫下容量大幅下降，甚至可能直接關機。保溫不是「保護裝置」，而是保證第二天頭燈能亮、GPS 能開——這些是安全裝備，不是個人用品。",
    "q.m17#7.p" to "溼衣物應該怎麼處理？",
    "q.m17#7.o0" to "掛在帳篷外凍幹",
    "q.m17#7.o1" to "儘量貼身或放進睡袋，靠體溫烘乾",
    "q.m17#7.o2" to "堆在帳篷角落",
    "q.m17#7.o3" to "直接塞進揹包",
    "q.m17#7.e" to "高海拔夜間溫度極低，晾在外面的溼衣物會直接結冰。而靠體溫烘乾雖不徹底，但至少能保證第二天穿的時候不是冰的——這是「把體溫當作資源來用」的一個典型例子。",
    "q.m17#8.p" to "為什麼營地要隨時保持「能立刻打包走」的狀態？",
    "q.m17#8.o0" to "為了方便出發",
    "q.m17#8.o1" to "因為天氣或隊員狀態可能要求隨時緊急撤離",
    "q.m17#8.o2" to "為了節省打包時間",
    "q.m17#8.o3" to "為了保持整潔",
    "q.m17#8.e" to "高營的天氣窗口可能突然關閉，隊員也可能突然出現高原症狀。此時「需要多久才能出發」直接決定了風險大小——而把東西鋪得滿帳篷都是，可能就要多耗半小時。",
    "q.m17#9.p" to "高海拔睡眠困難的主要原因不包括？",
    "q.m17#9.o0" to "週期性呼吸導致反覆微醒",
    "q.m17#9.o1" to "缺氧與心率偏快",
    "q.m17#9.o2" to "寒冷與不適",
    "q.m17#9.o3" to "帳篷顏色太亮",
    "q.m17#9.e" to "前三項都是真實的生理原因，其中週期性呼吸最典型：高海拔夜間呼吸會不自主地出現間歇，反覆把人從睡眠中拉回淺層。而睡眠質量又直接影響適應——所以「睡不好」不是小事。",
    "q.m17#10.p" to "【排序】建立與撤離營地的合理順序是？",
    "q.m17#10.o0" to "到達前觀察周邊是否存在雪崩、冰崩、雪簷等威脅",
    "q.m17#10.o1" to "確定帳篷位置，整理平整地面並做好固定",
    "q.m17#10.o2" to "分配物資、化雪取水、安排次日的行程與睡眠",
    "q.m17#10.o3" to "撤離前清點裝備與垃圾，恢復營地原狀",
    "q.m17#10.e" to "第一步最容易被跳過——尤其是在疲勞時，看到一塊平地就想紮營。但營地一旦建好，再想搬運的成本極高，所以「先看周邊、再定位置」應當成為固定習慣。",
    "q.m17#11.p" to "為什麼說營地也是撤退的支點？",
    "q.m17#11.o0" to "因為營地有物資",
    "q.m17#11.o1" to "因為撤退往往需要先回到營地，再決定繼續下撤還是等待天氣",
    "q.m17#11.o2" to "因為營地有通訊裝置",
    "q.m17#11.o3" to "因為嚮導在營地",
    "q.m17#11.e" to "從高處下撤往往不是一口氣到底，而是先回到最近的營地恢復、觀察、決策。這意味著營地本身必須是「可靠的目的地」——不能是一個你自己都不敢回的地方。",
    "q.m17#12.p" to "帳篷為什麼要保持通風？",
    "q.m17#12.o0" to "為了涼快",
    "q.m17#12.o1" to "避免一氧化碳積聚與內部結霜，避免窒息與中毒風險",
    "q.m17#12.o2" to "為了方便出入",
    "q.m17#12.o3" to "為了減少風阻",
    "q.m17#12.e" to "在高原用爐具煮飯時，密閉帳篷內的一氧化碳濃度可能迅速上升，而這種中毒往往在睡眠中發生、且症狀（頭痛、乏力）與高山症反應極難區分。這些因素疊加起來，讓通風成為一條硬要求。",
    "q.m17#13.p" to "帳篷內使用爐具時，最需要警惕的是？",
    "q.m17#13.o0" to "燃料洩漏",
    "q.m17#13.o1" to "一氧化碳中毒",
    "q.m17#13.o2" to "帳篷被燙壞",
    "q.m17#13.o3" to "噪音",
    "q.m17#13.e" to "一氧化碳無色無味，中毒早期症狀（頭痛、思睡）與高山症反應高度重疊——這正是它危險的地方：人會在「以為是高反」的判斷中睡過去。使用爐具必須保持通風。",
    "q.m17#14.p" to "【多選】營地裡應當主動維護的健康事項包括？",
    "q.m17#14.o0" to "足量飲水（化雪取水）",
    "q.m17#14.o1" to "足量進食，即使沒有胃口",
    "q.m17#14.o2" to "保持衣物乾燥",
    "q.m17#14.o3" to "互相觀察隊員的狀態與步態",
    "q.m17#14.o4" to "用咖啡與能量飲料代替正餐",
    "q.m17#14.e" to "前三項是自我維護，第四項是團隊維護——而且它往往比前三項更有效：高山症的早期體徵（步態不穩、反應遲鈍）自己很難發現，但同伴一眼就能看出來。",
    "q.m17#15.p" to "填空：高營以上，燃料與食品通常按（ ）分裝並預留應急份額。",
    "q.m17#15.a0" to "日",
    "q.m17#15.a1" to "天",
    "q.m17#15.a2" to "每日",
    "q.m17#15.a3" to "按日",
    "q.m17#15.e" to "按日分裝。這樣既能讓消耗進度一目瞭然，也能在行程延誤時第一時間發現「還剩幾天份」——而不是到用完了才意識到問題。",
    // ---------- q.m18 ----------
    "q.m18#0.p" to "慕士塔格峰的海拔是？",
    "q.m18#0.o0" to "6,812 m",
    "q.m18#0.o1" to "7,126 m",
    "q.m18#0.o2" to "7,134 m",
    "q.m18#0.o3" to "7,509 m",
    "q.m18#0.e" to "慕士塔格峰 7,509 m，位於新疆阿克陶。它是國內 7000 公尺級的首選目標，也是四座裡海拔最高的一座。",
    "q.m18#1.p" to "慕士塔格被稱為「冰山之父」，主要因為？",
    "q.m18#1.o0" to "它是世界最高峰",
    "q.m18#1.o1" to "它的冰川與雪量極大，遠望如巨大的冰蓋",
    "q.m18#1.o2" to "它是第一個被登頂的 7000 公尺",
    "q.m18#1.o3" to "它在當地傳說中是神山",
    "q.m18#1.e" to "這個稱呼來自它的外觀：頂部被巨大的冰帽覆蓋、雪坡綿延很廣，所以遠看像一座白色的巨山。與之對應的「冰山之父」形象也解釋了它的攀登特點——雪坡長、路線緩但耗時。",
    "q.m18#2.p" to "攀登慕士塔格的技術特點是？",
    "q.m18#2.o0" to "垂直冰壁為主，技術難度極高",
    "q.m18#2.o1" to "雪坡漫長、技術難度中等，但對適應與體能要求很高",
    "q.m18#2.o2" to "幾乎不需要技術裝備",
    "q.m18#2.o3" to "主要是攀岩地形",
    "q.m18#2.e" to "這是很典型的 7000 公尺級畫像：路線本身可能不難，但長時間在高海拔負重行軍會放大每一個小問題。因此真正的準備重點是適應與體能，而不是高難度技術。",
    "q.m18#3.p" to "阿瑪達布朗峰的實際海拔是？",
    "q.m18#3.o0" to "6,812 m",
    "q.m18#3.o1" to "7,126 m",
    "q.m18#3.o2" to "7,509 m",
    "q.m18#3.o3" to "8,027 m",
    "q.m18#3.e" to "阿瑪達布朗 6,812 m，位於尼泊爾昆布地區。按海拔它是 6000 公尺級，但把它放進 7000 公尺單元，是因為它的技術難度對標 7000 公尺以上。",
    "q.m18#4.p" to "為什麼阿瑪達布朗雖然只有 6,812 m，卻被歸入 7000 公尺單元？",
    "q.m18#4.o0" to "因為它的行政歸屬屬於 7000 公尺級",
    "q.m18#4.o1" to "因為它的仰角岩雪混合地形與強暴露感使技術難度對標 7000 公尺以上",
    "q.m18#4.o2" to "因為它的登頂率很低",
    "q.m18#4.o3" to "因為它位於 7000 公尺的山區",
    "q.m18#4.e" to "這是本課最值得記住的一點：山峰的難度不等於海拔。阿瑪達布朗是典型例證——它的海拔低於很多 7000 公尺峰，但技術門檻與心理壓力可能更大。選山只看海拔是一件危險的事。",
    "q.m18#5.p" to "列寧峰的海拔與位置是？",
    "q.m18#5.o0" to "7,126 m，尼泊爾",
    "q.m18#5.o1" to "7,134 m，帕米爾高原",
    "q.m18#5.o2" to "7,509 m，新疆",
    "q.m18#5.o3" to "6,812 m，尼泊爾昆布",
    "q.m18#5.e" to "列寧峰 7,134 m，位於帕米爾高原。它在 7000 公尺級裡屬於相對溫和的選擇，因此常被作為第一座 7000 公尺目標。",
    "q.m18#6.p" to "希姆隆峰的海拔是？",
    "q.m18#6.o0" to "7,126 m",
    "q.m18#6.o1" to "7,134 m",
    "q.m18#6.o2" to "7,509 m",
    "q.m18#6.o3" to "6,812 m",
    "q.m18#6.e" to "希姆隆峰 7,126 m，位於尼泊爾境內。它的路線雪坡與冰壁混合，在尼泊爾 7000 公尺級中較受歡迎。",
    "q.m18#7.p" to "【排序】把下列山峰按海拔從低到高排列。",
    "q.m18#7.o0" to "阿瑪達布朗峰（6,812 m）",
    "q.m18#7.o1" to "希姆隆峰（7,126 m）",
    "q.m18#7.o2" to "列寧峰（7,134 m）",
    "q.m18#7.o3" to "慕士塔格峰（7,509 m）",
    "q.m18#7.e" to "這個排序恰好暴露了一個常見誤區：如果按海拔選難度，你會把阿瑪達布朗排在慕士塔格之前——但真實技術難度可能相反。再次說明：海拔只是眾多變數之一。",
    "q.m18#8.p" to "【多選】7000 公尺級相比 6000 公尺級，主要變化包括？",
    "q.m18#8.o0" to "適應週期更長，需要更多高營輪換",
    "q.m18#8.o1" to "天氣窗口更窄，對時機要求更高",
    "q.m18#8.o2" to "撤退難度上升，自救能力成為硬要求",
    "q.m18#8.o3" to "技術地形與暴露感普遍增加",
    "q.m18#8.o4" to "人工氧氣成為標準裝備",
    "q.m18#8.e" to "四項變化是疊加的，而不是相加的——適應不良會讓你錯過窗口，錯過窗口會讓你在更差的條件下撤退，而撤退難度又因海拔和技術地形而放大。這就是為什麼 7000 公尺被稱為分水嶺。",
    "q.m18#9.p" to "為什麼說 7000 公尺是「分水嶺」？",
    "q.m18#9.o0" to "因為 7000 公尺以上才需要冰鎬",
    "q.m18#9.o1" to "因為從此開始，技術、判斷、體能、後勤四者同時作用，單靠某一項優勢無法彌補",
    "q.m18#9.o2" to "因為 7000 公尺以上才能看到冰川",
    "q.m18#9.o3" to "因為 7000 公尺以上才有商業隊伍",
    "q.m18#9.e" to "5000 公尺級的失敗往往是單點原因（適應或體能），6000 公尺級開始疊加，而 7000 公尺級要求全部到位。這也是本單元為何把技術、判斷、天氣、自救與營地管理放在一起——它們本來就是一套東西。",
    "q.m18#10.p" to "選擇 7000 公尺目標時，最應關注的指標是？",
    "q.m18#10.o0" to "海拔高度",
    "q.m18#10.o1" to "路線型別、後勤條件、適應節奏與撤退方案的綜合匹配",
    "q.m18#10.o2" to "登山費用",
    "q.m18#10.o3" to "登頂率",
    "q.m18#10.e" to "單看任何一項都不夠：海拔高不一定難，登頂率高不一定安全，費用低不一定划算。真正的判斷是「這四件事組合起來，是不是現在的我能承擔的」。",
    "q.m18#11.p" to "攀登慕士塔格時，為什麼「漫長雪坡」本身也是風險？",
    "q.m18#11.o0" to "因為雪坡太滑",
    "q.m18#11.o1" to "因為長時間暴露在高原環境中，體力與判斷力會持續下降，且撤退距離很長",
    "q.m18#11.o2" to "因為雪坡會經常雪崩",
    "q.m18#11.o3" to "因為雪坡無法結組",
    "q.m18#11.e" to "「不難但很長」是 7000 公尺級的典型風險模型：它不給任何單點難點，但持續消耗你。長時間的暴露意味著體能、注意力與決策質量都在緩慢下滑——而下降的這部分恰好是安全餘量。",
    "q.m18#12.p" to "【配對】把山峰與其典型特點對應起來。",
    "q.m18#12.l0" to "慕士塔格峰",
    "q.m18#12.l1" to "阿瑪達布朗峰",
    "q.m18#12.l2" to "列寧峰",
    "q.m18#12.l3" to "希姆隆峰",
    "q.m18#12.r0" to "冰山之父：雪坡漫長，考驗適應與體能",
    "q.m18#12.r1" to "仰角岩雪混合，暴露感強，8000 公尺試金石",
    "q.m18#12.r2" to "帕米爾高原，7000 公尺級中相對溫和",
    "q.m18#12.r3" to "尼泊爾境內，雪坡與冰壁混合",
    "q.m18#12.e" to "這四種畫像其實對應四種不同的準備重點：慕士塔格練適應、阿瑪達布朗練技術與心理、列寧峰作為進階跳板、希姆隆峰綜合檢驗。把它們放在一起看，就能按自己的短板來選。",
    "q.m18#13.p" to "如果目標是 8000 公尺，從 7000 公尺單元選峰時最合理的思路是？",
    "q.m18#13.o0" to "選海拔最高的那座",
    "q.m18#13.o1" to "重點看哪座能補上自己的短板（技術、適應或暴露感）",
    "q.m18#13.o2" to "選最便宜的",
    "q.m18#13.o3" to "選登頂率最高的",
    "q.m18#13.e" to "把 7000 公尺級當作「針對短板的訓練場」，比當作「刷等級」更有價值。例如技術不夠就選阿瑪達布朗，適應不好就選雪坡漫長、高營輪換完善的慕士塔格。",
    "q.m18#14.p" to "關於 7000 公尺級的準備週期，正確的認識是？",
    "q.m18#14.o0" to "與 6000 公尺級差不多",
    "q.m18#14.o1" to "明顯更長，需要足夠的高營輪換與適應時間",
    "q.m18#14.o2" to "只需要體能訓練",
    "q.m18#14.o3" to "可以在上一次攀登後立即開始",
    "q.m18#14.e" to "適應是累積過程，而 7000 公尺級往往需要多次高營輪換。行程設計得緊、沒有把適應時間算進去，是很多 7000 公尺級隊伍無法登頂甚至發生意外的直接原因。",
    "q.m18#15.p" to "為什麼本單元要把「危險判斷」放在「技術課程」之後？",
    "q.m18#15.o0" to "因為判斷比技術容易",
    "q.m18#15.o1" to "因為技術能力會提高你進入困難地形的底氣，因此更需要判斷來約束",
    "q.m18#15.o2" to "因為課程篇幅限制",
    "q.m18#15.o3" to "因為技術不重要",
    "q.m18#15.e" to "這是一個很現實的設計：技術越熟練，能去的路線就越難，因此「限制自己」的需求反而上升。把判斷課放在技術課之後，正是對應了現實中這個順序——先有能力，再有剋制。",
    // ---------- q.m19 ----------
    "q.m19#0.p" to "「死亡地帶」通常指的是？",
    "q.m19#0.o0" to "7000 公尺以上",
    "q.m19#0.o1" to "8000 公尺以上",
    "q.m19#0.o2" to "5500 公尺以上",
    "q.m19#0.o3" to "6000 公尺以上",
    "q.m19#0.e" to "8000 公尺以上被稱為死亡地帶，原因很直接：這個高度的氧分壓已低到人體無論怎麼適應都無法長期維持平衡。它不是修辭，而是生理事實——也是 8000 公尺級與 7000 公尺級最本質的分界線。",
    "q.m19#1.p" to "8000 公尺處的大氣壓大約相當於海平面的？",
    "q.m19#1.o0" to "一半",
    "q.m19#1.o1" to "三分之二",
    "q.m19#1.o2" to "三分之一",
    "q.m19#1.o3" to "五分之一",
    "q.m19#1.e" to "約為三分之一。這意味著每次呼吸吸入的氧分子只有海平面的三成左右——而攀登又需要數倍於休息時的耗氧量。這個供需缺口就是一切 8000 公尺級風險的源頭。",
    "q.m19#2.p" to "為什麼人體無法在 8000 公尺以上長期停留？",
    "q.m19#2.o0" to "因為太冷",
    "q.m19#2.o1" to "因為氧分壓低於維持人體代謝所需的下限，身體會持續衰退",
    "q.m19#2.o2" to "因為食物不夠",
    "q.m19#2.o3" to "因為風太大",
    "q.m19#2.e" to "長期停留意味著「消耗大於修復」：即使在休息，身體也在持續流失肌肉與體重、認知能力下降。這解釋了為什麼 8000 公尺的行程必須「快進快出」——沒有等待條件變好的選項。",
    "q.m19#3.p" to "缺氧最先影響的能力通常是？",
    "q.m19#3.o0" to "腿部力量",
    "q.m19#3.o1" to "判斷力與認知能力",
    "q.m19#3.o2" to "視力",
    "q.m19#3.o3" to "聽力",
    "q.m19#3.e" to "這是 8000 公尺級最危險的機制：判斷力下降的人無法判斷自己判斷力下降了。反過來，腿沒力氣你能立刻感覺到，而“我還能繼續”這種想法卻可能已經是缺氧的產物。",
    "q.m19#4.p" to "為什麼說「判斷力下降」在 8000 公尺格外危險？",
    "q.m19#4.o0" to "因為會迷路",
    "q.m19#4.o1" to "因為你需要用已經受損的判斷力去判斷是否應該繼續或撤退",
    "q.m19#4.o2" to "因為會影響隊友",
    "q.m19#4.o3" to "因為會降低攀登速度",
    "q.m19#4.e" to "這是一個遞迴的陷阱：越是需要作出關鍵決定的時候（繼續還是撤退），你的決策能力越不可靠。“再走一段看看”在 4000 公尺可能合理，在 8000 公尺可能已經是在缺氧驅動下的錯誤判斷。",
    "q.m19#5.p" to "【多選】缺氧導致認知能力下降的典型表現包括？",
    "q.m19#5.o0" to "反應變慢、說話含糊",
    "q.m19#5.o1" to "計算與判斷出錯",
    "q.m19#5.o2" to "對風險的評估變得過於樂觀",
    "q.m19#5.o3" to "情緒波動、易怒或冷漠",
    "q.m19#5.o4" to "手指與腳趾的凍傷感減退",
    "q.m19#5.e" to "四項都是典型表現，而且共同點是當事人自己很難察覺。因此可靠的做法是外部化：用清單代替記憶，用固定時間代替“感覺差不多”，讓同伴互相監督而不是靠自我評估。",
    "q.m19#6.p" to "面對判斷力下降的風險，最有效的對策是？",
    "q.m19#6.o0" to "靠意志力提醒自己保持清醒",
    "q.m19#6.o1" to "把決策外化為事前寫好的清單與固定規則（時間、氧氣量、天氣閾值）",
    "q.m19#6.o2" to "多喝熱水",
    "q.m19#6.o3" to "放慢速度",
    "q.m19#6.e" to "意志力本身就是缺氧最先削弱的東西。可靠的辦法是在狀態還好時把規則寫下來：幾點必須轉身、氧氣剩餘多少必須下撤——到時只需核對事實，不需重新判斷。",
    "q.m19#7.p" to "為什麼 8000 公尺行程強調「早出發、早返回」？",
    "q.m19#7.o0" to "為了避開人流",
    "q.m19#7.o1" to "因為午後天氣惡化機率上升，而低溫、大風會急劇消耗體力與氧氣",
    "q.m19#7.o2" to "因為路線上午更短",
    "q.m19#7.o3" to "因為嚮導的習慣",
    "q.m19#7.e" to "在 8000 公尺，「晚」的代價被放得很大：同樣的路，下午走要多耗一倍體力，而且一旦天黑，溫度與判斷力雙重下降。“下山太晚”幾乎總是那條事故鏈的共同起點。",
    "q.m19#8.p" to "為什麼 8000 公尺級需要「簡化決策」？",
    "q.m19#8.o0" to "為了省時間",
    "q.m19#8.o1" to "因為認知資源有限，應當把它留給真正關鍵的決定",
    "q.m19#8.o2" to "因為高原上不想思考",
    "q.m19#8.o3" to "因為隊友會幫忙決定",
    "q.m19#8.e" to "具體做法包括：裝備固定位置與順序、操作流程化為清單、行程提前固定。把“今天穿什麼、先做什麼”變成不需思考的預設動作，才能把寶貴的判斷力留給“繼續還是撤”這類決定。",
    "q.m19#9.p" to "為什麼即使經驗豐富的攀登者在 8000 公尺也需要使用檢查清單？",
    "q.m19#9.o0" to "因為記憶不可靠",
    "q.m19#9.o1" to "因為缺氧會優先損傷工作記憶，而清單不依賴記憶",
    "q.m19#9.o2" to "因為規定要求",
    "q.m19#9.o3" to "為了讓新人學習",
    "q.m19#9.e" to "這與航空業的邏輯相同：在高負荷、高後果的環境裡，人不能依賴“我應該不會忘”。清單的作用不是教新人，而是給即使專家也會出現的失誤上一道保險。",
    "q.m19#10.p" to "高海拔體重持續下降的主要原因是？",
    "q.m19#10.o0" to "因為食物不好吃",
    "q.m19#10.o1" to "因為身體在缺氧狀態下持續消耗自身組織，且食慾下降導致攝入不足",
    "q.m19#10.o2" to "因為運動量大",
    "q.m19#10.o3" to "因為飲水不足",
    "q.m19#10.e" to "兩個因素同時作用：一方面缺氧使身體處於分解大於合成的狀態；另一方面高山症反應本身就會抑制食慾。這也是為什麼“吃得下”在高原是一項能力，而不是享受。",
    "q.m19#11.p" to "為什麼在 8000 公尺容易睡不好？",
    "q.m19#11.o0" to "因為帳篷不舒服",
    "q.m19#11.o1" to "因為低氧導致週期性呼吸，呼吸會反覆出現間歇，把人從睡眠中拉回",
    "q.m19#11.o2" to "因為風大",
    "q.m19#11.o3" to "因為白天睡太多",
    "q.m19#11.e" to "週期性呼吸是高海拔睡眠的典型現象：呼吸驅動不穩定，導致反覆出現“呼吸暫停→驚醒”。而睡眠質量又直接影響次日的適應與體力——所以“能睡”在高營也是核心競爭力。",
    "q.m19#12.p" to "【排序】把缺氧對身體機能的影響按「通常出現順序」排列。",
    "q.m19#12.o0" to "呼吸加快、心率上升（代償）",
    "q.m19#12.o1" to "長時間活動耐力下降",
    "q.m19#12.o2" to "判斷力與計算能力下降",
    "q.m19#12.o3" to "意識改變、共濟失調",
    "q.m19#12.e" to "前兩項是身體在“想辦法”，後兩項是“快撐不住了”。危險的是第三項——它出現在明顯的意識改變之前，所以“看起來還正常”不等於“腦子還清楚”。",
    "q.m19#13.p" to "對付 8000 公尺缺氧最直接、最可靠的手段是？",
    "q.m19#13.o0" to "增加進食",
    "q.m19#13.o1" to "使用輔助氧氣",
    "q.m19#13.o2" to "多休息",
    "q.m19#13.o3" to "降低行進速度",
    "q.m19#13.e" to "其他手段都在“減少消耗”或“加快適應”的層面上起作用，而補充氧氣直接抬高了吸入氧分壓——它改變了那個根源變數。這也是為什麼輔助氧氣在 8000 公尺級屬於標準安全裝備。",
    "q.m19#14.p" to "關於「適應上限」，正確的理解是？",
    "q.m19#14.o0" to "適應可以無止境進行",
    "q.m19#14.o1" to "適應存在上限，超過一定海拔後無論如何適應都無法完全代償",
    "q.m19#14.o2" to "適應只需一天",
    "q.m19#14.o3" to "適應與海拔無關",
    "q.m19#14.e" to "適應是一個有極限的過程，而不是可以持續升高的曲線。這也是 8000 公尺以上必須依靠氧氣與“快速進出”策略的根本原因——不是準備不夠，而是生理上就不存在“適應好了再待著”這個選項。",
    "q.m19#15.p" to "為什麼 8000 公尺級事故的根因往往不是單一事件？",
    "q.m19#15.o0" to "因為運氣差",
    "q.m19#15.o1" to "因為缺氧會同時削弱判斷、體力與協調，使多個環節同時變脆",
    "q.m19#15.o2" to "因為裝備不行",
    "q.m19#15.o3" to "因為人多",
    "q.m19#15.e" to "在低海拔，一個失誤往往還有餘量補救；在 8000 公尺，判斷、體力與動作控制同時下降，小失誤更容易直接串聯成事故。因此 8000 公尺級的安全策略必須是“多加幾層保險”，而不是“更小心一點”。",
    "q.m19#16.p" to "【多選】8000 公尺級的主要致死原因包括？",
    "q.m19#16.o0" to "雪崩與冰崩",
    "q.m19#16.o1" to "滑墜",
    "q.m19#16.o2" to "失溫",
    "q.m19#16.o3" to "高海拔疾病及其併發症",
    "q.m19#16.o4" to "雪盲與曬傷等環境損傷",
    "q.m19#16.e" to "四類都常見，而且常常互相疊加：滑墜後無法自救 → 在低溫中等待 → 失溫 → 高海拔疾病加重。這也解釋了為什麼 8000 公尺級培訓不能只盯“高山症”，而必須把技術、判斷與體系統統納入。",
    "q.m19#17.p" to "填空：8000 公尺以上被稱為「（ ）地帶」。",
    "q.m19#17.a0" to "死亡",
    "q.m19#17.a1" to "死",
    "q.m19#17.e" to "死亡地帶。這個術語的實用價值在於它傳遞了一個硬約束：這裡沒有“等一等、緩一緩”的選項。所有計劃、補給與決策都必須圍繞“儘快透過”來設計。",
    "q.m19#18.p" to "如果在 8000 公尺發現自己“特別想繼續登頂”，最應該做的是？",
    "q.m19#18.o0" to "相信自己的直覺，繼續往上",
    "q.m19#18.o1" to "警惕這可能正是缺氧導致的風險低估，立即對照事前設定的折返條件",
    "q.m19#18.o2" to "加快速度趕緊登頂",
    "q.m19#18.o3" to "讓隊友決定",
    "q.m19#18.e" to "這是一個很有代表性的情境：強烈的“想繼續”在低海拔可能只是渴望，在 8000 公尺則可能是判斷力受損的訊號。這時唯一可靠的參照不是感覺，而是出發前寫好的客觀條件。",
    // ---------- q.m20 ----------
    "q.m20#0.p" to "輔助氧氣在 8000 公尺級的主要作用是？",
    "q.m20#0.o0" to "替代體能訓練",
    "q.m20#0.o1" to "提升血氧、降低高山症風險、改善行動能力與判斷力",
    "q.m20#0.o2" to "保暖",
    "q.m20#0.o3" to "減輕裝備重量",
    "q.m20#0.e" to "其中“改善判斷力”這一項最容易被忽略，卻在安全上最關鍵——它直接對沖了 8000 公尺最危險的那個因素。也因此，氧氣在 8000 公尺級屬於標準安全裝備，而不是“省力工具”。",
    "q.m20#1.p" to "輔助氧氣系統的組成部分包括？",
    "q.m20#1.o0" to "氣瓶、調壓器、流量計、面罩/鼻導管",
    "q.m20#1.o1" to "氣瓶與揹包",
    "q.m20#1.o2" to "面罩與保暖層",
    "q.m20#1.o3" to "調壓器與頭盔",
    "q.m20#1.e" to "四部分各司其職：氣瓶儲存、調壓器把高壓降到安全範圍、流量計控制輸出、面罩/鼻導管完成輸送。任何一環出問題都會導致實際吸入量低於預期——這也是為什麼系統需要每段檢查。",
    "q.m20#2.p" to "攀登中常用的氧氣流量範圍大約是？",
    "q.m20#2.o0" to "0.5～1 L/min",
    "q.m20#2.o1" to "2～4 L/min",
    "q.m20#2.o2" to "8～10 L/min",
    "q.m20#2.o3" to "15 L/min 以上",
    "q.m20#2.e" to "2～4 L/min 是攀登中的常用區間，具體數值取決於海拔、體力消耗與個人反應。流量越高越舒適，但消耗越快——這個權衡直接決定了你能在 8000 公尺停留多久。",
    "q.m20#3.p" to "計算氧氣量時，為什麼必須單獨預留「應急備用」？",
    "q.m20#3.o0" to "為了多帶一點",
    "q.m20#3.o1" to "因為行程延誤、隊友需要支援或系統故障都可能額外耗氧",
    "q.m20#3.o2" to "因為氣瓶會漏",
    "q.m20#3.o3" to "因為規定要求",
    "q.m20#3.e" to "氧氣計劃的典型錯誤是“剛好夠用到峰頂”。而實際行程幾乎總比計劃慢，還可能出現隊友氧氣不足、系統洩漏等意外。沒有應急份額，就意味著一旦出現偏差，你只能在最危險的海拔上“賭”。",
    "q.m20#4.p" to "氧氣用完後可能發生什麼？",
    "q.m20#4.o0" to "沒有任何影響",
    "q.m20#4.o1" to "身體狀況可能迅速惡化，因為身體已適應了較高的吸入氧濃度",
    "q.m20#4.o2" to "會立刻高山症發作",
    "q.m20#4.o3" to "會自動切換為呼吸空氣",
    "q.m20#4.e" to "突然從高濃度氧回到環境氧分壓，等同於在 8000 公尺“突然升了一截海拔”。如果此時遠離營地、體力已透支，情況會迅速變得危險——這就是為什麼氧氣餘量必須留得保守。",
    "q.m20#5.p" to "【多選】使用氧氣系統應遵守的紀律包括？",
    "q.m20#5.o0" to "每段行程檢查流量與介面",
    "q.m20#5.o1" to "按計劃流量使用，不隨意調高",
    "q.m20#5.o2" to "記錄剩餘量與預計可支撐時間",
    "q.m20#5.o3" to "預先約定氧氣剩餘到多少就必須下撤",
    "q.m20#5.o4" to "感覺不適時把流量調到最大",
    "q.m20#5.e" to "第四條最關鍵：把“氧氣剩多少就撤”變成一個事先定好的數字，而不是現場討論。因為到那個時刻，需要用到這條規則的人可能已經失去了準確判斷的能力。",
    "q.m20#6.p" to "為什麼說“用氧不是作弊”？",
    "q.m20#6.o0" to "因為規則允許",
    "q.m20#6.o1" to "因為 8000 公尺以上已超出人體可長期代償的生理範圍，用氧是基於生理事實的標準做法",
    "q.m20#6.o2" to "因為大家都用",
    "q.m20#6.o3" to "因為能提高登頂率",
    "q.m20#6.e" to "“作弊”這個說法隱含“多用一點就能矇混過關”的假設，但 8000 公尺的限制不是規則，而是物理與生理約束。使用氧氣只是把生理上限抬高一些，不改變“無法長期停留”這個事實。",
    "q.m20#7.p" to "面罩與鼻導管相比，主要差異是？",
    "q.m20#7.o0" to "面罩能提供更穩定的氧濃度，但活動時更悶、視野受影響",
    "q.m20#7.o1" to "鼻導管可以提供更高濃度",
    "q.m20#7.o2" to "兩者完全相同",
    "q.m20#7.o3" to "面罩更輕",
    "q.m20#7.e" to "面罩封閉度更高，氧濃度穩定，但呼吸阻力大、容易起霧、活動時不舒服；鼻導管舒適、視野好，但實際吸入濃度受呼吸方式影響較大。選擇取決於地形、強度與個人耐受度——而不是簡單的“哪個好”。",
    "q.m20#8.p" to "提高流量與降低流量之間需要權衡什麼？",
    "q.m20#8.o0" to "舒適度與續航時間",
    "q.m20#8.o1" to "重量與價格",
    "q.m20#8.o2" to "沒有任何權衡",
    "q.m20#8.o3" to "海拔與溫度",
    "q.m20#8.e" to "流量越高，身體越“舒服”、判斷力維持得越好，但可支撐時間越短。因此氧氣計劃實質上是“在高海拔能待多久”的預算——它直接決定了衝頂日的時間窗口與折返時間。",
    "q.m20#9.p" to "為什麼氧氣瓶重量會成為後勤難題？",
    "q.m20#9.o0" to "因為體積大",
    "q.m20#9.o1" to "因為瓶體與氣體本身都很重，而高營以上往往需要人力搬運",
    "q.m20#9.o2" to "因為不能託運",
    "q.m20#9.o3" to "因為容易損壞",
    "q.m20#9.e" to "在高海拔，每公斤的代價都被放大，而氧氣瓶屬於“重量大且不可壓縮”的裝備。這就是為什麼氧氣計劃必須與營地佈置、人力分配一起整體設計——它不是一個獨立的裝備問題。",
    "q.m20#10.p" to "為什麼氧氣要在高營提前存放？",
    "q.m20#10.o0" to "為了減輕衝頂日負擔，並保證衝頂日有可用氧",
    "q.m20#10.o1" to "為了防盜",
    "q.m20#10.o2" to "因為山上更冷",
    "q.m20#10.o3" to "為了節省費用",
    "q.m20#10.e" to "衝頂日最關鍵、體力最差，不可能再搬著氧氣爬升。因此氧氣必須提前一趟一趟送上去——這也意味著氧氣量、人力與天氣窗口在計劃階段就互相繫結在一起。",
    "q.m20#11.p" to "如果氧氣系統在途中出現故障，應該怎麼辦？",
    "q.m20#11.o0" to "繼續攀登，回家再修",
    "q.m20#11.o1" to "立即評估剩餘氧氣與自己所在海拔，按預案決定下降或使用備用系統",
    "q.m20#11.o2" to "調大流量嘗試修復",
    "q.m20#11.o3" to "拆開修理",
    "q.m20#11.e" to "氧氣故障意味著你正在以更高海拔的條件“裸奔”。處理它的優先順序高於一切：先判斷能不能靠備用系統繼續，不能就下降——在 8000 公尺，退回是有意義的選擇，而不是失敗。",
    "q.m20#12.p" to "【排序】衝頂日氧氣系統的檢查順序是？",
    "q.m20#12.o0" to "確認瓶內壓力與預計可支撐時間",
    "q.m20#12.o1" to "檢查調壓器、管路與面罩/鼻導管是否完好",
    "q.m20#12.o2" to "開啟流量並確認實際出氣正常",
    "q.m20#12.o3" to "記錄剩餘量並告知同伴與後方",
    "q.m20#12.e" to "前三步是技術檢查，第四步是團隊溝通——後者在高海拔尤其重要：如果隊友知道你的氧氣餘量，在你狀態下滑時就可能比別人更早發現異常。",
    "q.m20#13.p" to "為什麼氧氣不能替代適應？",
    "q.m20#13.o0" to "因為氧氣太貴",
    "q.m20#13.o1" to "因為適應是身體自身產生的生理代償，而氧氣只是抬高吸入濃度",
    "q.m20#13.o2" to "因為氧氣會失效",
    "q.m20#13.o3" to "因為氧氣只對高山症有效",
    "q.m20#13.e" to "適應改變的是“身體怎麼用氧”，氧氣改變的是“進來多少氧”。前者不能靠後者獲得。所以下撤、循序上升與足夠的適應時間，依然是 8000 公尺級不可省略的前置條件。",
    "q.m20#14.p" to "【多選】氧氣系統的常見故障包括？",
    "q.m20#14.o0" to "介面結冰或堵塞",
    "q.m20#14.o1" to "管路洩漏",
    "q.m20#14.o2" to "調壓器故障導致流量不準",
    "q.m20#14.o3" to "氣瓶閥開啟困難",
    "q.m20#14.o4" to "氣瓶重量超出預期",
    "q.m20#14.e" to "四類都與低溫、結冰和操作不便有關——而它們恰好都發生在最難處理的高海拔與疲勞狀態下。這就是為什麼除了備用系統，還需要“故障時的決策預案”。",
    "q.m20#15.p" to "為什麼氧氣計劃必須寫進行程表？",
    "q.m20#15.o0" to "為了好看",
    "q.m20#15.o1" to "因為氧氣量直接決定了可行的折返時間與停留上限",
    "q.m20#15.o2" to "為了記錄開支",
    "q.m20#15.o3" to "為了方便報銷",
    "q.m20#15.e" to "氧氣不是“帶了就行”的物資，而是一個定量預算：多少瓶、什麼流量、能支撐幾小時——這些數字反過來決定了折返時間。因此它必須與時間表一起規劃，而不是分開兩張清單。",
    "q.m20#16.p" to "填空：攀登中常用的氧氣流量範圍約為 2～（ ）L/min。",
    "q.m20#16.a0" to "4",
    "q.m20#16.a1" to "四",
    "q.m20#16.e" to "2～4 L/min。這個區間是在“維持足夠血氧”和“節省氣量”之間取的平衡。氧氣管理說到底就是一個持續分配資源的問題。",
    "q.m20#17.p" to "如果隊友的氧氣不足，你應該怎麼做？",
    "q.m20#17.o0" to "繼續衝頂，各人管各人",
    "q.m20#17.o1" to "立即共享資訊與餘量，按預案決定一起下撤或分配氧氣",
    "q.m20#17.o2" to "讓他自己想辦法",
    "q.m20#17.o3" to "把自己的氧氣全部給他",
    "q.m20#17.e" to "氧氣不足是一個團隊級事件，而不是個人問題：它會影響撤退速度與互相照應能力。最糟的選擇是“繼續衝頂”與“完全放棄自己”兩個極端——合理做法是重新分配資源、優先保證全員下撤。",
    "q.m20#18.p" to "一瓶可用氧氣量按 1,200 升計算。若按 3 L/min 的流量使用，大約可以支撐多少分鐘？",
    "q.m20#18.a0" to "400",
    "q.m20#18.e" to "約 400 分鐘（約 6.7 小時）。演算法：1200 ÷ 3 = 400。這類計算在衝頂日意義很直接——它決定了你能在 8000 公尺停留多久，也直接決定了折返時間該定在幾點。",
    "q.m20#19.p" to "衝頂計劃：上行 5 小時、下行 3 小時，流量按 2 L/min，另需預留 60 分鐘應急用量。所需氧氣總量約為多少升？",
    "q.m20#19.a0" to "1080",
    "q.m20#19.e" to "1080 升。演算法：（5 + 3）小時 × 60 分鐘 × 2 L/min = 960 升，再加應急 60 × 2 = 120 升，合計 1080 升。把「去程 + 回程 + 應急」三部分分開計算，是氧氣計劃最基本的紀律——只算“上去夠不夠”是最常見的錯誤。",
    // ---------- q.m21 ----------
    "q.m21#0.p" to "全球共有多少座海拔超過 8000 公尺的山峰？",
    "q.m21#0.o0" to "10 座",
    "q.m21#0.o1" to "12 座",
    "q.m21#0.o2" to "14 座",
    "q.m21#0.o3" to "18 座",
    "q.m21#0.e" to "14 座，全部集中在喜馬拉雅與喀喇崑崙兩大山脈。這個數字也是登山界“十四座”這一目標的由來。",
    "q.m21#1.p" to "十四座 8000 公尺峰分佈在哪些國家？",
    "q.m21#1.o0" to "中國、尼泊爾、印度、巴基斯坦",
    "q.m21#1.o1" to "中國、尼泊爾、不丹、印度",
    "q.m21#1.o2" to "尼泊爾、巴基斯坦、阿富汗、塔吉克",
    "q.m21#1.o3" to "中國、印度、巴基斯坦、緬甸",
    "q.m21#1.e" to "四國：中國、尼泊爾、印度、巴基斯坦。理解這個分佈很重要——它直接影響了許可、後勤、救援與政治風險，而這些在 8000 公尺級都是計劃的一部分。",
    "q.m21#2.p" to "珠穆朗瑪峰的海拔是？",
    "q.m21#2.o0" to "8,611 m",
    "q.m21#2.o1" to "8,848 m",
    "q.m21#2.o2" to "8,586 m",
    "q.m21#2.o3" to "8,516 m",
    "q.m21#2.e" to "8,848 m（2020 年中尼聯合測定為 8,848.86 m）。作為世界最高峰，它也是商業攀登最成熟的一座；但“成熟”意味著後勤與路線成熟，並不等於風險低——擁堵、成本與判斷難度同樣是真實風險。",
    "q.m21#3.p" to "安納普爾納一號峰在 8000 公尺級歷史中的地位是？",
    "q.m21#3.o0" to "最晚被登頂",
    "q.m21#3.o1" to "第一座被登頂的 8000 公尺峰",
    "q.m21#3.o2" to "死亡率最低",
    "q.m21#3.o3" to "最容易被登頂",
    "q.m21#3.e" to "安納普爾納一號峰 8,091 m，1950 年首次登頂，是人類攀登的第一座 8000 公尺峰。它的死亡率長期居前。最先被登頂，和容易沒有關係。",
    "q.m21#4.p" to "希夏邦馬峰的特點是？",
    "q.m21#4.o0" to "位於尼泊爾境內",
    "q.m21#4.o1" to "是唯一完全位於中國境內的 8000 公尺峰，也是十四座中最晚被登頂的",
    "q.m21#4.o2" to "是最高的一座",
    "q.m21#4.o3" to "是難度最低的一座",
    "q.m21#4.e" to "希夏邦馬 8,027 m，位於西藏，是唯一完全坐落於中國境內的 8000 公尺峰；1964 年由中國登山隊完成首登，也是十四座中最晚被登頂的一座。",
    "q.m21#5.p" to "洛子峰與珠穆朗瑪峰的關係是？",
    "q.m21#5.o0" to "兩者相隔很遠",
    "q.m21#5.o1" to "洛子與珠峰相鄰，且常與珠峰走同一條接近路線",
    "q.m21#5.o2" to "洛子比珠峰高",
    "q.m21#5.o3" to "兩者不在同一山脈",
    "q.m21#5.e" to "洛子峰 8,516 m，緊鄰珠峰，從南側接近時可共用大部分路線與營地。因此在後勤與適應上，兩座峰常常被放在同一行程裡考慮。",
    "q.m21#6.p" to "關於卓奧友峰，常見的評價是？",
    "q.m21#6.o0" to "技術難度最高的 8000 公尺峰",
    "q.m21#6.o1" to "通常被認為是 8000 公尺級中技術難度較低的一座",
    "q.m21#6.o2" to "死亡率最高的 8000 公尺峰",
    "q.m21#6.o3" to "沒有商業隊伍攀登",
    "q.m21#6.e" to "卓奧友 8,188 m，因為路線相對平緩、後勤成熟，常被認為是 8000 公尺級中技術難度較低的一座。但“相對容易”仍然意味著必須在死亡地帶行動數日——這個量級不容低估。",
    "q.m21#7.p" to "南迦帕爾巴特峰以什麼著稱？",
    "q.m21#7.o0" to "溫和的路線",
    "q.m21#7.o1" to "巨大的海拔落差與嚴重的雪崩風險",
    "q.m21#7.o2" to "最便宜的攀登費用",
    "q.m21#7.o3" to "最完善的後勤",
    "q.m21#7.e" to "南迦帕爾巴特 8,126 m，被稱為“裸山”——它從河谷拔起的高度極大，雪崩與落石風險突出。它的歷史攀登代價在 8000 公尺級中相當高。",
    "q.m21#8.p" to "【配對】把山峰與其海拔對應起來。",
    "q.m21#8.l0" to "珠穆朗瑪峰",
    "q.m21#8.l1" to "干城章嘉峰",
    "q.m21#8.l2" to "洛子峰",
    "q.m21#8.l3" to "馬卡魯峰",
    "q.m21#8.r0" to "8,848 m",
    "q.m21#8.r1" to "8,586 m",
    "q.m21#8.r2" to "8,516 m",
    "q.m21#8.r3" to "8,485 m",
    "q.m21#8.e" to "這四座分別是世界第一、第三、第四、第五高峰。記它們別光背數字，要記排序和所在山脈。數字可以查，整體格局得心裡有數。",
    "q.m21#9.p" to "為什麼“十四座”成為登山界的公認目標？",
    "q.m21#9.o0" to "因為是個整數",
    "q.m21#9.o1" to "因為它恰好構成了高海拔攀登的完整邊界，且數量在可追求範圍內",
    "q.m21#9.o2" to "因為商業公司炒作",
    "q.m21#9.o3" to "因為國際登聯規定",
    "q.m21#9.e" to "14 座的獨特之處在於：它有一個客觀而明確的邊界（海拔 >8000 m），數量有限、可被逐一列舉。這讓它既清晰又具備終身挑戰性——也是它成為標杆的原因。",
    "q.m21#10.p" to "【多選】登頂一座 8000 公尺峰通常需要具備哪些條件？",
    "q.m21#10.o0" to "完整的適應週期與高營輪換",
    "q.m21#10.o1" to "技術能力與冰川行進經驗",
    "q.m21#10.o2" to "可靠的氧氣與後勤系統",
    "q.m21#10.o3" to "在 7000 公尺級驗證過的體能與判斷力",
    "q.m21#10.o4" to "專業的跟拍攝影團隊",
    "q.m21#10.e" to "四項對應四個不同維度：生理（適應）、技術、後勤、經驗積累。它們在 8000 公尺同時作用——任何一項缺失都會變成短板，而短板在高海拔會被迅速放大。",
    "q.m21#11.p" to "道拉吉里峰、馬納斯魯峰、安納普爾納峰共同位於哪個國家？",
    "q.m21#11.o0" to "中國",
    "q.m21#11.o1" to "尼泊爾",
    "q.m21#11.o2" to "巴基斯坦",
    "q.m21#11.o3" to "印度",
    "q.m21#11.e" to "三座均位於尼泊爾境內。尼泊爾擁有 8000 公尺級中最多的山峰數量，這也是它的攀登產業如此發達的原因，同時也帶來了許可、管理與環保上的持續壓力。",
    "q.m21#12.p" to "為何 8000 公尺級的“成熟商業路線”依然危險？",
    "q.m21#12.o0" to "因為費用高",
    "q.m21#12.o1" to "因為海拔本身不可改變，擁堵、等待與救援困難會製造新的風險",
    "q.m21#12.o2" to "因為嚮導不專業",
    "q.m21#12.o3" to "因為裝備不好",
    "q.m21#12.e" to "商業化能解決後勤與路線熟悉度，但不能降低海拔本身。相反的，大量隊伍同一窗口衝頂會帶來排隊等待——而在 8000 公尺等待，意味著額外消耗氧氣與體溫。",
    "q.m21#13.p" to "【排序】把下列山峰按海拔從高到低排列。",
    "q.m21#13.o0" to "珠穆朗瑪（8,848）",
    "q.m21#13.o1" to "干城章嘉（8,586）",
    "q.m21#13.o2" to "馬卡魯（8,485）",
    "q.m21#13.o3" to "安納普爾納一號（8,091）",
    "q.m21#13.e" to "排列背後是“世界前五”到“世界第十”的跨度。記住排序比記住精確數字更實用——因為在討論路線、後勤與難度對比時，你需要的往往是相對位置。",
    "q.m21#14.p" to "為什麼學習 8000 公尺峰的知識也要了解首登歷史？",
    "q.m21#14.o0" to "為了考試",
    "q.m21#14.o1" to "因為首登過程往往暴露了該峰的核心難點與風險型別",
    "q.m21#14.o2" to "為了記住人名",
    "q.m21#14.o3" to "與攀登無關",
    "q.m21#14.e" to "早期隊伍的失敗與犧牲往往精準地指向了該峰的主要難點——例如雪崩頻發段、強風段、或路線暴露段。把首登史當作“風險檔案”來讀，比當作故事看有用得多。",
    "q.m21#15.p" to "【多選】下列哪些屬於喜馬拉雅山脈的 8000 公尺峰？",
    "q.m21#15.o0" to "珠穆朗瑪峰",
    "q.m21#15.o1" to "安納普爾納一號峰",
    "q.m21#15.o2" to "希夏邦馬峰",
    "q.m21#15.o3" to "喬戈裡峰 K2",
    "q.m21#15.e" to "前三項屬於喜馬拉雅；K2 屬於喀喇崑崙山脈。兩條山脈在地理上相鄰但地質不同，攀登季節與氣候模式也有差異——這也是為何十四座峰常被按山脈分組討論。",
    "q.m21#16.p" to "“世界最高峰”這一稱號對策略的影響是？",
    "q.m21#16.o0" to "沒有任何影響",
    "q.m21#16.o1" to "意味著媒體與商業關注度最高，也意味著隊伍密度與擁堵風險最大",
    "q.m21#16.o2" to "意味著路線最簡單",
    "q.m21#16.o3" to "意味著救援最方便",
    "q.m21#16.e" to "關注度帶來資源，也帶來人群。當大量隊伍集中在同一窗口時，等待、擁堵與“不願意放棄排隊位置”的心理壓力都會成為新的風險來源——這是“最高峰”特有的策略問題。",
    "q.m21#17.p" to "填空：全球共有（ ）座海拔超過 8000 公尺的山峰。",
    "q.m21#17.a0" to "14",
    "q.m21#17.a1" to "十四",
    "q.m21#17.e" to "14 座。數字雖小，卻代表了高海拔攀登的完整邊界——也是為什麼“十四座”至今仍被視為一個足以投入一生的目標。",
    // ---------- q.m22 ----------
    "q.m22#0.p" to "喀喇崑崙山脈共有多少座 8000 公尺峰？",
    "q.m22#0.o0" to "2 座",
    "q.m22#0.o1" to "4 座",
    "q.m22#0.o2" to "6 座",
    "q.m22#0.o3" to "10 座",
    "q.m22#0.e" to "四座：K2、加舒爾布魯木一號峰、加舒爾布魯木二號峰、布洛阿特峰。它們也被稱為 K2、K4、K5、K3——“K”代表喀喇崑崙。",
    "q.m22#1.p" to "喬戈裡峰 K2 的海拔與公認地位是？",
    "q.m22#1.o0" to "8,611 m，世界第二高峰，技術難度與死亡率最高的 8000 公尺峰之一",
    "q.m22#1.o1" to "8,848 m，世界第一高峰",
    "q.m22#1.o2" to "8,586 m，世界第三高峰",
    "q.m22#1.o3" to "8,051 m，較容易的一座",
    "q.m22#1.e" to "K2 海拔 8,611 m，世界第二高峰。它被公認為最難、最危險的 8000 公尺峰之一，也因此被稱為“登山者的山”——在這裡，技術與判斷的權重遠高於後勤保障。",
    "q.m22#2.p" to "為什麼喀喇崑崙與喜馬拉雅的攀登季節常常不同？",
    "q.m22#2.o0" to "因為經緯度不同",
    "q.m22#2.o1" to "因為兩者受不同氣候系統影響：喀喇崑崙受西風帶影響更明顯",
    "q.m22#2.o2" to "因為海拔不同",
    "q.m22#2.o3" to "因為管理規定不同",
    "q.m22#2.e" to "喜馬拉雅的最佳季節主要與季風週期相關；而喀喇崑崙更受西風帶與地形降水影響。這直接決定了“什麼時候去”——而選錯季節，再好的隊伍也等不到登頂窗口。",
    "q.m22#3.p" to "布洛阿特峰又被稱為什麼？",
    "q.m22#3.o0" to "K1",
    "q.m22#3.o1" to "K2",
    "q.m22#3.o2" to "K3",
    "q.m22#3.o3" to "K5",
    "q.m22#3.e" to "布洛阿特峰又稱 K3，海拔 8,051 m。它的地形相對開闊，但雪量大、強風頻繁——歷史上曾因被低估而出現較多事故。",
    "q.m22#4.p" to "加舒爾布魯木一號峰與二號峰分別又被稱為什麼？",
    "q.m22#4.o0" to "K4 與 K5",
    "q.m22#4.o1" to "K5 與 K4",
    "q.m22#4.o2" to "K2 與 K3",
    "q.m22#4.o3" to "K3 與 K4",
    "q.m22#4.e" to "一號峰為 K5（8,080 m），二號峰為 K4（8,035 m）——編號與海拔順序不一致，這也是容易混淆的地方。記住“K 系編號並不按高度排序”就不會記錯了。",
    "q.m22#5.p" to "十四座 8000 公尺峰全部集中在哪兩條山脈？",
    "q.m22#5.o0" to "喜馬拉雅與天山",
    "q.m22#5.o1" to "喜馬拉雅與喀喇崑崙",
    "q.m22#5.o2" to "喀喇崑崙與阿爾卑斯",
    "q.m22#5.o3" to "念青唐古拉與喜馬拉雅",
    "q.m22#5.e" to "全部集中在喜馬拉雅與喀喇崑崙兩條山脈——它們在地理上相鄰，卻承受著不同的氣候系統。這也再次說明：在 8000 公尺級，地理位置本身就是一條關鍵資訊。",
    "q.m22#6.p" to "【配對】把山峰與其海拔對應起來。",
    "q.m22#6.l0" to "喬戈裡峰 K2",
    "q.m22#6.l1" to "南迦帕爾巴特",
    "q.m22#6.l2" to "加舒爾布魯木一號",
    "q.m22#6.l3" to "希夏邦馬",
    "q.m22#6.r0" to "8,611 m",
    "q.m22#6.r1" to "8,126 m",
    "q.m22#6.r2" to "8,080 m",
    "q.m22#6.r3" to "8,027 m",
    "q.m22#6.e" to "四座分別代表世界第二、第九、第十一、第十四高峰。它們跨度很大，但在“8000 公尺以上”這個類別裡地位相同——這正是 8000 公尺級的特殊之處：邊界清晰，內部差異巨大。",
    "q.m22#7.p" to "關於「8000 公尺排名與難度」的關係，正確的看法是？",
    "q.m22#7.o0" to "海拔越高一定越難",
    "q.m22#7.o1" to "難度主要由技術地形、氣候與後勤決定，與海拔排名並不直接對應",
    "q.m22#7.o2" to "海拔越低一定越容易",
    "q.m22#7.o3" to "難度完全無法比較",
    "q.m22#7.e" to "這是十四座全景最重要的一個認識：8,188 m 的卓奧友被認為相對容易，而 8,611 m 的 K2 則屬於最難分之一一；海拔相差不到 500 m，實際門檻卻判若兩山。",
    "q.m22#8.p" to "【多選】影響 8000 公尺峰實際難度的因素包括？",
    "q.m22#8.o0" to "技術地形與暴露感",
    "q.m22#8.o1" to "氣候與天氣窗口",
    "q.m22#8.o2" to "後勤與接近路線",
    "q.m22#8.o3" to "救援可行性",
    "q.m22#8.o4" to "山峰的海拔排名",
    "q.m22#8.e" to "四項缺一不可。特別是「救援可行性」常被忽視：一座救援幾乎不可能到達的山，即使路線本身不難，風險等級也完全不同——因為“萬一出事”在這裡沒有緩衝。",
    "q.m22#9.p" to "【排序】把下列山峰按海拔從高到低排列。",
    "q.m22#9.o0" to "喬戈裡峰（8,611）",
    "q.m22#9.o1" to "南迦帕爾巴特（8,126）",
    "q.m22#9.o2" to "加舒爾布魯木一號（8,080）",
    "q.m22#9.o3" to "希夏邦馬（8,027）",
    "q.m22#9.e" to "這個排序恰好覆蓋了十四座的“後半”。結合上一課的排序，你就已經掌握了完整的十四座海拔序列——這也是判斷“某座山屬於哪個梯度”的基礎。",
    "q.m22#10.p" to "為什麼說“十四座”是一個門檻極高的目標？",
    "q.m22#10.o0" to "因為費用極高",
    "q.m22#10.o1" to "因為它需要長期維持技術、體能、適應能力與判斷力，且跨越多個國家的後勤體系",
    "q.m22#10.o2" to "因為時間太長",
    "q.m22#10.o3" to "因為許可難拿",
    "q.m22#10.e" to "十四座往往需要十年以上才能完成，期間身體會衰老、生活狀態會變化。它考驗的不僅是攀登能力，更是長期維持能力與風險管理的一致性。",
    "q.m22#11.p" to "為什麼 8000 公尺級的成敗經常取決於“天氣窗口”而不是技術？",
    "q.m22#11.o0" to "因為技術不重要",
    "q.m22#11.o1" to "因為即使技術足夠，在高海拔長時間等待也會消耗掉安全餘量",
    "q.m22#11.o2" to "因為技術可以在山上臨時學",
    "q.m22#11.o3" to "因為嚮導會包辦一切",
    "q.m22#11.e" to "這是 8000 公尺級的現實：技術只是入場券，而窗口決定你能不能“在狀態還夠的時候透過”。這解釋了為何 8000 公尺級的行程計劃往往需要預留大幅餘量天數。",
    "q.m22#12.p" to "如果只能選一座 8000 公尺峰作為第一座，較合理的思路是？",
    "q.m22#12.o0" to "直接選 K2，一次到位",
    "q.m22#12.o1" to "選擇路線成熟、後勤可靠、救援可能的那一座，把“第一次”用在積累經驗上",
    "q.m22#12.o2" to "選海拔最低的那座就行",
    "q.m22#12.o3" to "隨便選一座，都一樣",
    "q.m22#12.e" to "“第一座”的價值在於摸清自己在死亡地帶的真實狀態：氧氣怎麼用、判斷力下降多少、速度如何。把它花在一座門檻更高的山上，等於同時測試多個未知變數。",
    "q.m22#13.p" to "【多選】下列哪些屬於喀喇崑崙山脈的 8000 公尺峰？",
    "q.m22#13.o0" to "喬戈裡峰 K2",
    "q.m22#13.o1" to "加舒爾布魯木一號峰",
    "q.m22#13.o2" to "加舒爾布魯木二號峰",
    "q.m22#13.o3" to "布洛阿特峰",
    "q.m22#13.o4" to "馬納斯魯峰",
    "q.m22#13.e" to "四座全部屬於喀喇崑崙——它們也是這條山脈全部的 8000 公尺峰。“喀喇崑崙四座”因此成為一個固定說法，與喜馬拉雅十座合起來正好十四。",
    "q.m22#14.p" to "學習十四座全景最實用的收益是什麼？",
    "q.m22#14.o0" to "能夠背出所有海拔",
    "q.m22#14.o1" to "能夠理解“為什麼難度與海拔不是一回事”，並據此評估自己的目標",
    "q.m22#14.o2" to "能夠指導他人攀登",
    "q.m22#14.o3" to "能夠寫攻略",
    "q.m22#14.e" to "十四座全景的真正價值在於建立起“多維難度觀”：技術、氣候、後勤、救援四個維度共同決定一座山的真實門檻。這個框架同樣適用於 5000 與 6000 公尺級的選擇。",
    "q.m22#15.p" to "為什麼 8000 公尺峰的“接近路線（approach）”也會成為風險因素？",
    "q.m22#15.o0" to "因為要走很久",
    "q.m22#15.o1" to "因為接近路段往往穿越冰川與雪崩區，而隊伍此時還沒有完全適應",
    "q.m22#15.o2" to "因為風景不好",
    "q.m22#15.o3" to "因為需要許可",
    "q.m22#15.e" to "接近路線往往在海拔上升期進行，而這時正是適應最差、判斷最不穩定的階段，同時又要面對裂縫與雪崩地形。這個“雙重脆弱期”是很多事故的發生時段。",
    "q.m22#16.p" to "如果要在 8000 公尺級建立自己的“目標清單”，最應該先確定什麼？",
    "q.m22#16.o0" to "想去的山峰名稱",
    "q.m22#16.o1" to "自己的短板（技術、適應、判斷或後勤經驗），再匹配能補短板的峰",
    "q.m22#16.o2" to "預算",
    "q.m22#16.o3" to "假期長度",
    "q.m22#16.e" to "按短板選山，是把 8000 公尺級當作“成長路徑”而不是“收整合就”。同一座山對不同人的價值不同——取決於它能補上你的哪一塊。",
    // ---------- q.m23 ----------
    "q.m23#0.p" to "【情境】隊友在 4500 公尺出現頭痛與噁心，堅持“再適應一天就能上”。從環境科學角度，正確的判斷是？",
    "q.m23#0.o0" to "再適應一天肯定能好，鼓勵他堅持",
    "q.m23#0.o1" to "症狀出現說明代償不足，不應在症狀未消退時繼續上升",
    "q.m23#0.o2" to "讓他服藥後繼續上升",
    "q.m23#0.o3" to "降海拔 100 公尺即可",
    "q.m23#0.e" to "這條鏈從最基本的因果開始：氣壓低 → 氧分壓低 → 身體需要時間適應。症狀出現就是“時間不夠”的訊號，而再多待一天並不能保證一定好轉——所以正確做法是停止上升，而不是賭明天。",
    "q.m23#1.p" to "【多選】一名隊員將前往 5000 公尺的硬雪坡，必須確認的裝備包括？",
    "q.m23#1.o0" to "與靴子嚴格匹配的冰爪",
    "q.m23#1.o1" to "符合身高的冰鎬",
    "q.m23#1.o2" to "UV400 雪鏡與高倍防曬",
    "q.m23#1.o3" to "與分層系統匹配的保暖與防水層",
    "q.m23#1.o4" to "登頂拍照用的相機與備用電池",
    "q.m23#1.e" to "四項對應四類風險：打滑（冰爪）、制動（冰鎬）、紫外線（防曬雪鏡）、失溫（分層）。裝備檢查的正確方式是“按風險列清單”，而不是按習慣拿東西。",
    "q.m23#2.p" to "【配對】把三層穿著系統與其職責對應起來。",
    "q.m23#2.l0" to "貼身層",
    "q.m23#2.l1" to "中間層",
    "q.m23#2.l2" to "外層",
    "q.m23#2.l3" to "羽絨層（極寒時）",
    "q.m23#2.r0" to "把汗從皮膚帶走，保持乾爽",
    "q.m23#2.r1" to "固定空氣層保暖（抓絨即使潮溼仍能保暖）",
    "q.m23#2.r2" to "防水防風並透氣，抵受外界天氣",
    "q.m23#2.r3" to "在乾燥環境中提供最高的保暖效率",
    "q.m23#2.e" to "四層各管一件事。看清這個分工，就能理解為何“穿得越多越暖”是錯的：漏掉排汗層會讓身體自帶潮溼環境，而外層不透氣會讓汗氣在內層凝結。",
    "q.m23#3.p" to "【情境】雪坡上行，前方隊員踢的臺階不均勻。最容易出現的後果是？",
    "q.m23#3.o0" to "隊伍行進速度變快",
    "q.m23#3.o1" to "後續隊員需要額外調整重心，體力消耗上升且更易失穩",
    "q.m23#3.o2" to "雪坡會崩塌",
    "q.m23#3.o3" to "沒有什麼影響",
    "q.m23#3.e" to "臺階是整支隊伍的“地基”。不均勻的臺階會讓每個人不斷重新尋找落腳點，加上負擔在高海拔本就稀缺的平衡能力——這是典型的“小問題累積成大風險”。",
    "q.m23#4.p" to "【排序】把冰鎬制動的動作按正確順序排列。",
    "q.m23#4.o0" to "抓穩冰鎬，確認握法正確",
    "q.m23#4.o1" to "翻身轉為俯臥、面朝雪面",
    "q.m23#4.o2" to "用身體重量把鎬尖壓入雪面",
    "q.m23#4.o3" to "抬起雙腳，防止冰爪插入雪面引起翻滾",
    "q.m23#4.e" to "這個動作序列是整個技術體系的地基。它必須做到“不需思考就能執行”——因為實際發生滑墜時，你的思考能力只有一兩秒的窗口，而這兩秒完全由肌肉記憶佔據。",
    "q.m23#5.p" to "【情境】一名攀登者在硬雪坡上滑墜，制動失敗。事後分析最可能的原因是？",
    "q.m23#5.o0" to "冰鎬太短",
    "q.m23#5.o1" to "鎬尖在硬雪上難以咬合，而透過硬雪坡時應優先建立固定繩保護",
    "q.m23#5.o2" to "鞋子不合適",
    "q.m23#5.o3" to "因為沒有戴手套",
    "q.m23#5.e" to "制動在硬雪與冰面上成功率顯著下降，這是技術本身的邊界。因此真正的問題往往在更早的時刻——為什麼在沒有系統保護的情況下走上了硬雪陡坡。",
    "q.m23#6.p" to "【多選】下撤階段容易被忽略的風險包括？",
    "q.m23#6.o0" to "體能下降導致腿部控制變差",
    "q.m23#6.o1" to "目標達成後警覺性下降",
    "q.m23#6.o2" to "雪面結冰或變軟，路況與上升時不同",
    "q.m23#6.o3" to "天色變暗，能見度與判斷力下降",
    "q.m23#6.o4" to "下撤路線通常比上升路線更短",
    "q.m23#6.e" to "四類疊加起來，就解釋了為什麼大量事故發生在下撤途中。所以下撤不是“任務完成後的返程”，而是一段需要單獨計劃的、同樣高風險的路段。",
    "q.m23#7.p" to "【情境】水袋的吸管口在空氣中很快結冰，你該怎麼辦？",
    "q.m23#7.o0" to "改用寬口保溫杯，並每次用後吹回吸管或倒置存放",
    "q.m23#7.o1" to "繼續使用，等它化開",
    "q.m23#7.o2" to "把水袋放在揹包外面",
    "q.m23#7.o3" to "停止飲水",
    "q.m23#7.e" to "這是一個很具體但很關鍵的小技巧：高海拔脫水往往不是“沒帶水”，而是“水凍住了喝不到”。把飲水方案設計成“不會凍住”，才算真正做好了補水準備。",
    "q.m23#8.p" to "填空：海拔每升高 1000 公尺，氣溫平均下降約（ ）℃。",
    "q.m23#8.a0" to "6.5",
    "q.m23#8.a1" to "六點五",
    "q.m23#8.e" to "6.5℃。這個數字貫穿整套課程：它解釋了雪線、決定了裝備厚度、也影響了雪崩與冰況的變化規律。能把它用於推演，才算真正理解。",
    "q.m23#9.p" to "【情境】你在 5000 公尺發現自己的雪鏡起霧嚴重，看不清楚地形。最重要的風險是什麼？",
    "q.m23#9.o0" to "只是不舒服",
    "q.m23#9.o1" to "失去地形判斷能力，可能誤入陡坡、雪簷或裂縫區",
    "q.m23#9.o2" to "會得雪盲",
    "q.m23#9.o3" to "會被隊友抱怨",
    "q.m23#9.e" to "“看不清”的本質是失去判斷依據。而在地形複雜的雪坡上，一兩個錯誤落腳點的代價可能很大。因此“能否看清”應當被當作裝備可靠性的硬指標。",
    "q.m23#10.p" to "【多選】一名隊員在高海拔出現嚴重的食慾下降，應該怎麼做？",
    "q.m23#10.o0" to "主動少量多次進食，選擇高碳水、易消化的食物",
    "q.m23#10.o1" to "保證均勻充足的飲水",
    "q.m23#10.o2" to "把食慾下降當作可能的適應問題訊號加以觀察",
    "q.m23#10.o3" to "靠大量咖啡與能量飲料代替進食",
    "q.m23#10.e" to "前三項都對；第四項錯得很有代表性：咖啡因可以提供“臨時感覺”，但不能替代能量。而在高原，能量攝入不足會直接削弱適應能力，形成惡性迴圈。",
    "q.m23#11.p" to "【情境】你在海拔 5000 公尺的雪坡上，發現手機電量從 40% 突然跳到關機。最合理的處理是？",
    "q.m23#11.o0" to "把手機貼身保溫後再開機",
    "q.m23#11.o1" to "反覆開機嘗試",
    "q.m23#11.o2" to "放棄使用電子裝置",
    "q.m23#11.o3" to "用盡電量傳送求救",
    "q.m23#11.e" to "這是鋰電池在低溫下的典型行為：容量驟降但並未耗盡。貼身保溫後往往能恢復供電。這提醒我們：電子裝置應被當作“可能突然失效的安全裝備”來管理。",
    "q.m23#12.p" to "【排序】把一次完整的裝備檢查流程按合理順序排列。",
    "q.m23#12.o0" to "按風險列清單（地形、天氣、海拔各需要什麼）",
    "q.m23#12.o1" to "逐件檢查完整性與工作狀態",
    "q.m23#12.o2" to "穿戴並試操作關鍵裝備（冰爪、安全帶、頭盔與頭燈）",
    "q.m23#12.o3" to "歸檔並告知同伴你的裝備狀態與備用方案",
    "q.m23#12.e" to "關鍵是第三步“試操作”：裝備完整不等於能用——冰爪卡扣沒扣到底、頭燈裝了舊電池，都只能在穿著並操作時才會暴露。",
    "q.m23#13.p" to "【情境】團隊決定因天氣下撤，但一名隊員堅持繼續，理由是“好不容易走到這裡”。最合適的處理是？",
    "q.m23#13.o0" to "尊重個人選擇，讓他單獨繼續",
    "q.m23#13.o1" to "堅持全員一起下撤——在高海拔不允許單獨行動，且高海拔的堅持本身可能就是缺氧所致",
    "q.m23#13.o2" to "投票決定",
    "q.m23#13.o3" to "讓他等一小時再決定",
    "q.m23#13.e" to "兩個理由：一是高海拔獨行風險極高；二是“好不容易”正是沉沒成本的典型表述——在高海拔，這類情緒與判斷力下降往往交織在一起，不能當作可靠意見。",
    "q.m23#14.p" to "關於“體能好的人是否更容易高山症”，正確的說法是？",
    "q.m23#14.o0" to "體能越好越不容易得",
    "q.m23#14.o1" to "高山症與體能沒有直接關係，而與上升速度、睡眠海拔和個體反應有關",
    "q.m23#14.o2" to "體能越好越容易得",
    "q.m23#14.o3" to "只有體能差的人會得",
    "q.m23#14.e" to "把體能和高原適應混為一談，是入門階段最常見的認知錯誤。事實上體能好的人可能因為“走得太快、升得太高”反而更容易出問題——這是個很現實的陷阱。",
    "q.m23#15.p" to "【多選】下列哪些做法能有效降低滑墜風險？",
    "q.m23#15.o0" to "行進中持續使用冰鎬做自我確保",
    "q.m23#15.o1" to "保持可持續的勻速，不突然發力",
    "q.m23#15.o2" to "按隊伍最慢者的節奏行進",
    "q.m23#15.o3" to "在硬雪與冰坡上架設固定路線繩",
    "q.m23#15.o4" to "下坡時減少制動操作、加快透過",
    "q.m23#15.e" to "四項分別對應個人技術、節奏控制、隊伍協同與系統保護。滑墜預防從來不是單一動作，而是一整層“保險疊保險”的設計。",
    "q.m23#16.p" to "【情境】隊伍在雪坡上休息時，一名隊員把冰鎬插在雪裡離開了。這存在什麼風險？",
    "q.m23#16.o0" to "冰鎬可能丟失",
    "q.m23#16.o1" to "一旦他滑墜，身邊沒有任何制動工具",
    "q.m23#16.o2" to "可能被隊友踩到",
    "q.m23#16.o3" to "沒有風險",
    "q.m23#16.e" to "滑墜發生得極快，而冰鎬是你唯一的制動手段。把冰鎬插在雪裡等於暫時放棄了制動能力——而在雪坡上，“暫時”恰好是最危險的時段。",
    "q.m23#17.p" to "本課考核的核心能力是什麼？",
    "q.m23#17.o0" to "記住所有資料",
    "q.m23#17.o1" to "把環境、裝備、穿著與行走知識拼起來，針對具體情景做出正確判斷",
    "q.m23#17.o2" to "背下所有術語",
    "q.m23#17.o3" to "熟練掌握器材品牌",
    "q.m23#17.e" to "這是整個課程的設計邏輯：單項知識容易記住，但在山上你面對的是“組合題”。能在具體情境下把幾塊知識串起來，才是真正掌握。",
    // ---------- q.m24 ----------
    "q.m24#0.p" to "【情境】隊友墜入冰裂縫，你的身體正獨自承受他的體重。接下來應該優先做什麼？",
    "q.m24#0.o0" to "立即開始拉他上來",
    "q.m24#0.o1" to "先建立確保站並把重量轉移過去，再考慮拉昇",
    "q.m24#0.o2" to "先呼救",
    "q.m24#0.o3" to "先拍照記錄",
    "q.m24#0.e" to "只要重量還壓在你身上，你就沒有能力作業系統。因此“建站→轉荷→拉昇”的順序不可顛倒——這是整個救援體系裡最實用的一條，也是最容易在緊張中被跳過的一步。",
    "q.m24#1.p" to "【配對】把繩結與其用途對應起來。",
    "q.m24#1.l0" to "“8”字結",
    "q.m24#1.l1" to "雙漁人結",
    "q.m24#1.l2" to "抓結",
    "q.m24#1.l3" to "布林結",
    "q.m24#1.r0" to "連線安全帶與固定點",
    "q.m24#1.r1" to "連線兩根繩或做輔繩環",
    "q.m24#1.r2" to "摩擦結，單向抓握",
    "q.m24#1.r3" to "連線固定點，泊船常用",
    "q.m24#1.e" to "四個結覆蓋了冰川行進與基礎保護的絕大多數場景。考核的意義在於：你需要在黑暗中、戴著手套時也能打出來。",
    "q.m24#2.p" to "【情境】兩個保護點的扁帶夾角接近 100°。這意味著什麼？",
    "q.m24#2.o0" to "受力更均勻",
    "q.m24#2.o1" to "每個點承擔的負荷顯著變大（夾角越大單點受力越大）",
    "q.m24#2.o2" to "沒有影響",
    "q.m24#2.o3" to "繩索會自動平衡",
    "q.m24#2.e" to "資料很直觀：夾角 0° 時每點約 50%，60° 時約 58%，90° 時約 71%。夾角 100° 時每個點的負擔已經很大了——因此實踐中常把夾角控制在 60° 以內。",
    "q.m24#3.p" to "【多選】一個符合要求的確保站應具備？",
    "q.m24#3.o0" to "每個點自身牢固",
    "q.m24#3.o1" to "各點彼此獨立失效（無假冗餘）",
    "q.m24#3.o2" to "負荷合理分配、預先收緊",
    "q.m24#3.o3" to "能快速建立，縮短暴露時間",
    "q.m24#3.o4" to "儘量只用一個保護點以節省器材",
    "q.m24#3.e" to "前三項是安全要求，第四項是效率要求——而效率也是安全，因為搭建過程本身就是暴露在風險中的時間。",
    "q.m24#4.p" to "【情境】隊友出現步態不穩與意識模糊。最優先的處置是？",
    "q.m24#4.o0" to "給氧並觀察",
    "q.m24#4.o1" to "立即下降，並在醫療監護下給地塞米松",
    "q.m24#4.o2" to "繼續上升以儘快到達營地",
    "q.m24#4.o3" to "服用止痛藥後休息",
    "q.m24#4.e" to "步態不穩與意識改變是 HACE 的核心體徵，屬於內科急症。下降是唯一確定性治療；地塞米松只是為下降爭取時間——兩者不是替代關係。",
    "q.m24#5.p" to "【多選】關於高原用藥，下列哪些說法正確？",
    "q.m24#5.o0" to "地塞米松對適應性沒有影響，對肺水腫也無治療作用",
    "q.m24#5.o1" to "乙醯唑胺提高適應速度，上升前 1 天開始、上升後約 2 天停藥",
    "q.m24#5.o2" to "硝苯地平可能引起血壓迅速下降",
    "q.m24#5.o3" to "藥物不能替代下降",
    "q.m24#5.o4" to "乙醯唑胺可以替代身體的適應過程",
    "q.m24#5.e" to "這四條都是關鍵知識點，而它們的共同結論是「藥物不能替代下降」：無論吃什麼藥，下降始終是根本處置。藥物只是在為下降爭取條件。",
    "q.m24#6.p" to "【情境】一名隊員在寒冷中停止顫抖、言語不清。最不應該做的是？",
    "q.m24#6.o0" to "更換溼衣幷包裹保溫",
    "q.m24#6.o1" to "讓他自己走動產熱",
    "q.m24#6.o2" to "優先復溫軀幹",
    "q.m24#6.o3" to "避免粗暴搬動",
    "q.m24#6.e" to "“停止顫抖”意味著已進入中度以上失溫，低溫心肌極易被誘發心律失常。讓患者自行走動或粗暴搬動都可能直接觸發危險——這是失溫急救中最反直覺的一條。",
    "q.m24#7.p" to "【排序】把結組救援四步按順序排列。",
    "q.m24#7.o0" to "自制動穩住自己",
    "q.m24#7.o1" to "建立獨立確保站",
    "q.m24#7.o2" to "將重量轉移到確保站",
    "q.m24#7.o3" to "用 3:1 系統拉昇",
    "q.m24#7.e" to "四步不可顛倒。在考核裡你也許能按順序背出；但在真實場景裡，你需要在幾十秒內完成前三步——這才是這個知識點的真正門檻。",
    "q.m24#8.p" to "【情境】天氣預報為「多雲」，但現場看到積雲快速垂直髮展。你應該？",
    "q.m24#8.o0" to "相信預報，按計劃行動",
    "q.m24#8.o1" to "按可能轉壞的假設做決策，並考慮提前下撤",
    "q.m24#8.o2" to "等一小時再看",
    "q.m24#8.o3" to "繼續上升但加快速度",
    "q.m24#8.e" to "預報提供的是區域背景，而現場雲況是“此刻此地”的證據。當兩者衝突時，現場優先。更何況積雲的發展速度在高海拔往往以分鐘計。",
    "q.m24#9.p" to "【多選】透過雪崩地形時，哪些做法是正確的？",
    "q.m24#9.o0" to "一人一人透過，保持間距",
    "q.m24#9.o1" to "指定位於安全位置的觀察員",
    "q.m24#9.o2" to "提前規劃撤離路線與集合點",
    "q.m24#9.o3" to "全隊同時快速透過以縮短暴露",
    "q.m24#9.e" to "前三項把風險限制在單個人身上；而“全隊同時透過”把風險放大為團體級——從“可能埋一人”變成“可能埋全隊”，是最不應選的方案。",
    "q.m24#10.p" to "【情境】隊伍已到達距離頂峰一小時的位置，但已超出折返時間。正確做法是？",
    "q.m24#10.o0" to "繼續登頂，因為只剩一小時",
    "q.m24#10.o1" to "立即下撤——折返時間的意義正在於它在“就差一點”時才真正起作用",
    "q.m24#10.o2" to "再延後半小時",
    "q.m24#10.o3" to "讓體力最好的人繼續",
    "q.m24#10.e" to "這道題真正考的是“定折返時間是為了什麼”。如果它只在輕鬆時被遵守，“就差一點”時可以放寬，那它就從來不存——而事故恰恰就發生在這個“就差一點”。",
    "q.m24#11.p" to "【多選】哪些屬於“高風險環境中正確的團隊決策方式”？",
    "q.m24#11.o0" to "出發前量化撤退訊號",
    "q.m24#11.o1" to "最保守的意見優先",
    "q.m24#11.o2" to "主動製造反對意見（如逐個表態）",
    "q.m24#11.o3" to "少數服從多數",
    "q.m24#11.e" to "前三項共同構成“對抗群體誤判”的機制；而少數服從多數恰好相反——它會把少數人的合理擔憂直接壓制掉，而危險訊號往往正是少數人先察覺的。",
    "q.m24#12.p" to "【情境】通訊中斷，而你按計劃應在一小時後聯絡後方。應該做什麼？",
    "q.m24#12.o0" to "繼續按計劃行動，等訊號恢復",
    "q.m24#12.o1" to "按出發前約定的失聯預案行動（如到匯合點等待）",
    "q.m24#12.o2" to "分頭尋找訊號",
    "q.m24#12.o3" to "立即全體下撤",
    "q.m24#12.e" to "通訊中斷在山地是常態而非意外——因此它必須在出發前就擁有預案。有預案時，失聯只是一個“已知分支”；沒預案時，它就會變成現場凌亂。",
    "q.m24#13.p" to "【排序】把遇到重傷員後的完整處置順序排列。",
    "q.m24#13.o0" to "確保現場安全，避免二次事故",
    "q.m24#13.o1" to "評估意識、呼吸與迴圈，處理危及生命的問題",
    "q.m24#13.o2" to "呼救並報告準確位置與傷情",
    "q.m24#13.o3" to "保溫、固定與持續觀察，等待轉移或專業救援",
    "q.m24#13.e" to "順序體現的是“先安全、再救人、同時呼救、然後維持”。現實中最常見的錯誤是跳過第一步直接衝向傷員——這恰恰是“製造第二個傷員”的典型路徑。",
    "q.m24#14.p" to "【多選】下列哪些屬於技術攀登中“必須實地練習”的技能？",
    "q.m24#14.o0" to "冰鎬自我制動",
    "q.m24#14.o1" to "抓結與結組系統操作",
    "q.m24#14.o2" to "確保站搭建",
    "q.m24#14.o3" to "冰裂縫救援流程",
    "q.m24#14.o4" to "記住 14 座 8000 公尺峰的名稱與海拔",
    "q.m24#14.e" to "四項都無法透過閱讀獲得。它們共同的特點是：必須在壓力下執行、容錯空間極小、且依賴肌肉記憶。所以它們也是本應用反覆標記“需教練評估”的部分。",
    "q.m24#15.p" to "【情境】你已經透過全部理論考核。此時應該如何看待自己的能力？",
    "q.m24#15.o0" to "已經具備獨立攀登 8000 公尺的能力",
    "q.m24#15.o1" to "具備理論基礎與判斷框架，但所有技術技能仍需教練現場評估後才能實地使用",
    "q.m24#15.o2" to "可以直接擔任嚮導",
    "q.m24#15.o3" to "理論透過就等同於能力達標",
    "q.m24#15.e" to "這是整個課程中最重要的一條宣告：理論掌握不等於實地能力。本應用建立的是認知與判斷框架，而真正能在冰壁上救你的，是在安全場地上重複過幾百次的那個動作。",
    "q.m24#16.p" to "完成全部課程後，你建立起的核心資產是什麼？",
    "q.m24#16.o0" to "一套裝備清單",
    "q.m24#16.o1" to "一套“識別風險—評估風險—做出決策”的思考框架，以及知道什麼時候不該繼續",
    "q.m24#16.o2" to "一個登山證書",
    "q.m24#16.o3" to "一堆知識點",
    "q.m24#16.e" to "從 5000 公尺的科普到 8000 公尺的終極考核，整套課程其實在反覆傳遞同一件事：安全不是技術的結果，而是判斷的結果——而技術是為了讓判斷有餘地。",
    "q.m24#17.p" to "填空：在不確定情況下做決策，應優先採納最（ ）的意見。",
    "q.m24#17.a0" to "保守",
    "q.m24#17.e" to "「保守優先」是整個課程的收尾原則：它簡單到可以當場執行，又強大到能對抗大多數認知偏誤。山永遠在那裡，而人不是。",
    // ---------- q.m25 ----------
    "q.m25#0.p" to "上山後你感到頭部發脹、呼吸不暢，隊伍正按計劃繼續上升。此時最應該做的是？",
    "q.m25#0.o0" to "忍一忍，來都來了",
    "q.m25#0.o1" to "停下來如實告訴嚮導或隊友，並休息觀察",
    "q.m25#0.o2" to "自己吃點藥，繼續跟上隊伍",
    "q.m25#0.o3" to "加快速度，儘快到達營地就會好",
    "q.m25#0.e" to "高原上對身體訊號最忌諱兩種處理：忍著不說和自行處理。正確的第一步是把感受如實講出來，並停下來休息觀察。\n這不是軟弱——嚮導只有在知道情況後才能做出判斷，而你自己也需要一段觀察時間，才能分辨它是在緩解還是加重。",
    "q.m25#1.p" to "「來都來了」這句話在高原行程中為什麼危險？",
    "q.m25#1.o0" to "因為它浪費時間",
    "q.m25#1.o1" to "因為它把已經投入的時間當成了繼續冒險的理由",
    "q.m25#1.o2" to "因為它會影響隊內氣氛",
    "q.m25#1.o3" to "因為它聽起來不專業",
    "q.m25#1.e" to "這是典型的沉沒成本思維：已經走了這麼久、花了這麼多錢、請了這麼長的假，所以「不能白來」。\n但風險不會因為你投入了多少而降低。已經投入的東西收不回來，而繼續上升的代價可能是收不回來的更多東西。",
    "q.m25#2.p" to "你發現自己明顯跟不上隊伍節奏，一直在硬跟。最合適的做法是？",
    "q.m25#2.o0" to "咬牙跟上，不拖累隊友",
    "q.m25#2.o1" to "如實說明，並請隊伍按最慢者的節奏行進",
    "q.m25#2.o2" to "悄悄放慢，裝作沒事",
    "q.m25#2.o3" to "不告訴任何人，自己獨自下撤",
    "q.m25#2.e" to "高原上「硬跟」是一種隱性透支：當時的代價只是累，但它會累積成第二天的徹底崩潰。而且隊伍按最快的節奏走，本身就把所有人拖到了危險邊緣。\n正確做法是把節奏調到最慢的人能持續走的速度——這既保護個人，也保護整隊。",
    "q.m25#3.p" to "隊友說他有點不舒服，但堅持「沒事，能走」。你應該怎麼做？",
    "q.m25#3.o0" to "相信他的判斷，繼續走",
    "q.m25#3.o1" to "認真對待，並把情況告訴嚮導",
    "q.m25#3.o2" to "不干涉，讓他自己決定",
    "q.m25#3.o3" to "不必當真，很多人都會這樣說",
    "q.m25#3.e" to "高海拔的不適有一個殘酷特點：人的判斷力會先受影響，所以「我覺得我能行」在高海拔是打折的。\n把隊友的情況報告給嚮導，是對他負責的做法——如果確實沒事，最多是多一次確認；如果確實有事，你可能是唯一及時察覺的人。",
    "q.m25#4.p" to "出發前嚮導說明天有一段路必須結組透過。有人覺得「這麼緩的坡沒必要」。正確的認識是？",
    "q.m25#4.o0" to "緩坡確實不需要結組",
    "q.m25#4.o1" to "結組與否應聽嚮導的，他掌握地形與雪況資訊",
    "q.m25#4.o2" to "結組主要是為了整齊好看",
    "q.m25#4.o3" to "應由體力最好的人決定",
    "q.m25#4.e" to "從遠處看「緩」，和站在現場看冰裂縫、雪橋、暗裂縫的分佈，是兩回事。嚮導掌握的資訊與你不同，這正是他的價值所在。\n在技術性決定上，讓掌握資訊最多的人做判斷，是隊伍效率與安全的基本規則。",
    "q.m25#5.p" to "你走在隊伍中間，發現水已經喝完了，但離下一個補給點還有兩小時。應該？",
    "q.m25#5.o0" to "忍著不說，別麻煩別人",
    "q.m25#5.o1" to "立即告訴領隊，看能否協調",
    "q.m25#5.o2" to "向最近的隊友要水，但不告訴領隊",
    "q.m25#5.o3" to "少喝一點，繼續撐",
    "q.m25#5.e" to "水糧不足屬於隊伍層面的資訊，不是個人小事——它會影響領隊對整體節奏與補給點的判斷。\n私下向隊友要水看似「不麻煩人」，實際是把資訊截斷了：領隊仍然以為全隊狀況良好，可能繼續按原計劃推進。",
    "q.m25#6.p" to "關於「慢就是快」在高原的含義，正確的理解是？",
    "q.m25#6.o0" to "走得慢就一定能登頂",
    "q.m25#6.o1" to "用可持續的勻速前進，比反覆衝刺更省時間也更安全",
    "q.m25#6.o2" to "慢是為了照顧體力差的人",
    "q.m25#6.o3" to "高原上速度不重要",
    "q.m25#6.e" to "高原的供氧能力受限，頻繁的爆發式用力會迅速堆積乳酸並加重缺氧。\n穩定勻速反而更快：它讓你不需要頻繁停下恢復，也降低了因為過度消耗而被迫提前下撤的機率。這句話描述的是能量代謝的規律，不是安慰性的說法。",
    "q.m25#7.p" to "你比預定時間晚了兩個小時到達營地，天已經黑了。此時最應該做的是？",
    "q.m25#7.o0" to "連夜繼續趕到下一個營地",
    "q.m25#7.o1" to "就地紮營，並通知後方自己的位置",
    "q.m25#7.o2" to "獨自返回尋找掉隊的人",
    "q.m25#7.o3" to "繼續走，直到追上前隊",
    "q.m25#7.e" to "高原上連夜趕路是事故高發的組合：黑暗 + 疲勞 + 低溫 + 無法判斷地形。就地紮營是穩妥選擇。\n但必須加上一條：通知後方自己的位置。這樣萬一需要救援，至少知道去哪裡找；反之，獨自行動會讓隊伍同時失去兩個人。",
    "q.m25#8.p" to "隊友在半路上出現明顯不適、越走越慢。隊伍裡出現「等」還是「先走一部分」的分歧。更合理的做法是？",
    "q.m25#8.o0" to "全隊按原速繼續前進",
    "q.m25#8.o1" to "絕不分開，全隊一起放慢",
    "q.m25#8.o2" to "安排一位有經驗的人陪同他，其餘人繼續並保持聯絡",
    "q.m25#8.o3" to "讓他自己慢慢走，到營地會合",
    "q.m25#8.e" to "高原上「分隊」本身有風險，但在人力足夠時，安排最有經驗的人陪同落後者、其餘人繼續，往往比「全隊一起慢」和「全隊硬跟」都更合理。\n關鍵是三條：有人陪、保持通訊、把情況與預計到達時間告知前方。完全落單是最差的選項。",
    "q.m25#9.p" to "關於「登頂」在整段行程裡的位置，正確的認識是？",
    "q.m25#9.o0" to "登頂是行程的終點",
    "q.m25#9.o1" to "登頂只是行程的一半，下撤才是風險最集中的階段",
    "q.m25#9.o2" to "登頂最重要，其他都不重要",
    "q.m25#9.o3" to "沒登頂就等於行程失敗",
    "q.m25#9.e" to "大量事故發生在下撤途中，因為目標達成後警覺性會下降，而體能已經接近極限。\n把登頂理解成「一半」，意味著你必須在計劃裡為下撤留出同等的時間、體力和保護——而不是把全部資源都用在向上這件事上。",
    "q.m25#10.p" to "情景：第一次上高原的 24 小時",
    "q.m25#10.c" to "你第一次參加 5000 公尺級的徒步登山。到達海拔 4,300 公尺的營地後，接下來的 24 小時裡發生了幾件事。",
    "q.m25#10.e" to "這四步的核心不是醫學知識，而是兩個習慣：如實說與重新評估。高原行程中真正把人推入危險的不是某一次判斷失誤，而是一連串「忍過去」「不麻煩別人」的小選擇疊加。",
    "q.m25#10.s0.p" to "第 1 步：傍晚你開始頭痛、吃不下飯。隊友說「正常，睡一覺就好」。你該怎麼做？",
    "q.m25#10.s0.o0" to "聽隊友的，睡一覺就好",
    "q.m25#10.s0.o1" to "如實告訴嚮導自己的感受，並按要求休息、少量多次進食飲水",
    "q.m25#10.s0.o2" to "自己找藥吃，不告訴別人",
    "q.m25#10.s0.o3" to "喝點酒幫助入睡",
    "q.m25#10.s0.e" to "頭痛與食慾下降在高原很常見，但「常見」不等於「可以忽略」。如實報告 + 基本處置（休息、補水、少量進食）是標準反應。\n關鍵在於：嚮導需要在你的情況變化時第一時間知道——而不是第二天早上才發現。",
    "q.m25#10.s1.p" to "第 2 步：半夜你幾乎沒睡著。第二天早上隊伍準備繼續上升。你的選擇是？",
    "q.m25#10.s1.o0" to "不說，直接跟著走",
    "q.m25#10.s1.o1" to "說明睡眠情況，讓嚮導評估是否繼續",
    "q.m25#10.s1.o2" to "自己決定留下，不告訴隊伍",
    "q.m25#10.s1.o3" to "要求全隊停下來等你恢復",
    "q.m25#10.s1.e" to "睡眠差是高原最常見的困擾之一，單獨出現通常不構成停止上升的理由——但它必須被納入評估，而不是你自己默默扛著。\n嚮導會結合頭痛、食慾、行動狀態一起判斷，這正是他經驗的價值。",
    "q.m25#10.s2.p" to "第 3 步：隊伍繼續上升，你感覺比昨天好了一些，但走得很慢。此時心態上最要警惕的是什麼？",
    "q.m25#10.s2.o0" to "擔心被隊友笑話",
    "q.m25#10.s2.o1" to "「不能白來」的想法——它會讓你在需要停下時不情願停下",
    "q.m25#10.s2.o2" to "想拍照的衝動",
    "q.m25#10.s2.o3" to "對天氣的擔憂",
    "q.m25#10.s2.e" to "沉沒成本在第二天最容易發作：已經難受了一晚，如果現在放棄，那昨晚的難受就「白受了」。\n這種想法會讓人把已經付出的代價當成繼續的理由，而不是當成需要重新評估的訊號。",
    "q.m25#10.s3.p" to "第 4 步：最終你沒能到頂，在距離終點一小時處下撤了。怎麼看這次行程？",
    "q.m25#10.s3.o0" to "很失敗，下次不要來了",
    "q.m25#10.s3.o1" to "這是一次有效的適應經歷，下撤是判斷力的體現而不是失敗",
    "q.m25#10.s3.o2" to "都怪隊友拖累了進度",
    "q.m25#10.s3.o3" to "下次不管怎樣都要到頂",
    "q.m25#10.s3.e" to "高原適應需要多次暴露才能建立，第一次到 4,000～5,000 公尺本來就不該以「登頂」為唯一目標。\n而且——能在該撤的時候撤下來，正是這項運動最被看重的能力。它比一次僥倖的登頂能帶你去更遠的地方。",
    "q.m25#11.p" to "情景：隊伍壓力",
    "q.m25#11.c" to "行程第四天，天氣開始變差，隊伍裡出現了分歧。你心裡有一個和大家不太一樣的判斷。",
    "q.m25#11.e" to "這個情景考的是「說出保留意見」這件事。它在現實中很難，因為代價看起來是社交性的（掃興、不合群）；而收益是隱蔽的（避免了一次可能的事故）。把這三點記住，下一次你會更早開口。",
    "q.m25#11.s0.p" to "第 1 步：有人主張「衝一衝，天氣明天可能更好」，有人主張下撤。你傾向下撤，但不想當那個掃興的人。此時應該？",
    "q.m25#11.s0.o0" to "保持沉默，隨大流",
    "q.m25#11.s0.o1" to "把自己的判斷和依據說出來",
    "q.m25#11.s0.o2" to "私下抱怨幾句就算了",
    "q.m25#11.s0.o3" to "假裝支援繼續，心裡保留意見",
    "q.m25#11.s0.e" to "高風險環境中的「沉默的少數」是事故覆盤的常客。有保留意見卻不說，等於讓隊伍在資訊不完整的情況下做決策。\n說出擔憂的成本很小，代價可能是零；不說的代價可能非常大。",
    "q.m25#11.s1.p" to "第 2 步：討論後隊伍決定繼續上升，但你仍然覺得不妥。接下來應該？",
    "q.m25#11.s1.o0" to "消極執行，只做最低限度的事",
    "q.m25#11.s1.o1" to "明確表達保留，並確認隊伍的折返條件與撤退方案",
    "q.m25#11.s1.o2" to "立即獨自下撤",
    "q.m25#11.s1.o3" to "不再說話，但心裡埋怨",
    "q.m25#11.s1.e" to "決策已經做出時，能做的三件事是：留下明確記錄（我反對，理由是……）、確認撤退條件是否清晰、確保自己仍然願意並能夠執行。\n保留意見不等於消極執行——把意見說出來之後，你仍要把自己那份做好。",
    "q.m25#11.s2.p" to "第 3 步：事後證明你的擔心是對的，隊伍提前下撤了。這次經歷的價值在於？",
    "q.m25#11.s2.o0" to "證明了你比別人強",
    "q.m25#11.s2.o1" to "它驗證了「事前表達保留」是有效且不破壞關係的",
    "q.m25#11.s2.o2" to "說明以後應該自己單獨行動",
    "q.m25#11.s2.o3" to "沒什麼價值，反正沒登頂",
    "q.m25#11.s2.e" to "很多人第一次表達保留時，會擔心被當成「不合群」。但真實的隊伍反而會因為這種溝通而對彼此更有信心——因為它證明了隊裡有人願意說真話。\n把這次經驗記住，下一次你會更早開口。",
    // ---------- q.l5 ----------
    "q.l5#0.p" to "法式（平足）技術的核心要點是？",
    "q.l5#0.o0" to "只用前齒戳入冰面",
    "q.l5#0.o1" to "讓冰爪所有底部點平貼坡面，腳掌放平",
    "q.l5#0.o2" to "單腳跳著前進",
    "q.l5#0.o3" to "用靴子側面切進冰裡",
    "q.l5#0.e" to "法式的關鍵是「平」：十二個底部點全部貼合，受力分散到大腿與全身，因此最省力。這也是為什麼它適合長時間在緩雪的雪坡上移動。",
    "q.l5#1.p" to "前齒法（德式）為什麼最耗體力？",
    "q.l5#1.o0" to "因為需要用手臂發力",
    "q.l5#1.o1" to "因為受力集中在前齒，需要小腿持續用力",
    "q.l5#1.o2" to "因為必須屏住呼吸",
    "q.l5#1.o3" to "因為摩擦力更大",
    "q.l5#1.e" to "前齒法把體重壓在兩三個前齒上，小腿必須持續等長收縮維持姿態，因此極其消耗體力，無法長時間維持——這是它只用於陡坡的原因。",
    "q.l5#2.p" to "橫切雪坡時應該採用什麼步法？",
    "q.l5#2.o0" to "前齒法，前齒垂直踢入",
    "q.l5#2.o1" to "鴨步：腳跟併攏、腳尖外八，整副冰爪貼合坡面",
    "q.l5#2.o2" to "側身跳躍前進",
    "q.l5#2.o3" to "跪姿爬行",
    "q.l5#2.e" to "鴨步讓冰爪的橫向前齒與底部點同時咬合坡面，避免身體重量集中在內側幾顆齒上而滑脫。橫切時重心要略向坡內傾。",
    "q.l5#3.p" to "法式（平足）技術最適合的地形是？",
    "q.l5#3.o0" to "垂直冰壁",
    "q.l5#3.o1" to "低到中等角度的硬雪坡，適合長時間行進",
    "q.l5#3.o2" to "外懸屋簷",
    "q.l5#3.o3" to "只有平地才適用",
    "q.l5#3.e" to "法式把受力分散到全身與大腿，因此最省力，是低到中等角度與長時間雪坡行進的主力技術。陡峭地形則需要前齒法，但前齒法無法長時間維持。",
    "q.l5#4.p" to "在陡坡上長時間使用前齒法（德式）會導致什麼結果？",
    "q.l5#4.o0" to "越走越輕鬆",
    "q.l5#4.o1" to "小腿肌肉迅速疲勞，最終無法維持姿態",
    "q.l5#4.o2" to "冰爪會自動脫落",
    "q.l5#4.o3" to "沒有任何影響",
    "q.l5#4.e" to "前齒法把體重集中在兩三個前齒上，小腿必須持續等長收縮，因此極易疲勞。這正是它只適合短距離陡坡的原因，也是路線規劃時必須考慮的體力預算。",
    "q.l5#5.p" to "混合式（American technique）中兩隻腳的分工是？",
    "q.l5#5.o0" to "兩隻腳都保持平貼坡面",
    "q.l5#5.o1" to "兩隻腳都使用前齒",
    "q.l5#5.o2" to "一隻腳平貼坡面支撐，另一隻腳用前齒推進，交替使用",
    "q.l5#5.o3" to "只用一隻腳發力，另一隻腳休息",
    "q.l5#5.e" to "混合式是介於法式與德式之間的過渡技術：平貼的腳提供穩定與短暫的休息，前齒的腳提供推進力。它讓中等偏陡的坡面既有效率，又不至於像純前齒法那樣迅速耗盡小腿。",
    "q.l5#6.p" to "【配對】把冰爪檔位與它應當搭配的靴子型別對應起來。",
    "q.l5#6.l0" to "C1 全綁帶式",
    "q.l5#6.l1" to "C2 前綁後卡式",
    "q.l5#6.l2" to "C3 全卡式",
    "q.l5#6.r0" to "B1 軟底靴",
    "q.l5#6.r1" to "B2 半硬靴",
    "q.l5#6.r2" to "B3 全硬靴",
    "q.l5#6.e" to "靴爪必須配套：軟底靴配 C1，半硬配 C2，全硬配 C3。把全卡式冰爪裝在軟底靴上，靴體會變形、卡扣失去咬合，冰爪可能在陡坡上脫落——這是明確的危險配置。",
    "q.l5#7.p" to "冰坡行走最基本的兩種技術是？",
    "q.l5#7.o0" to "平步技術與側步技術",
    "q.l5#7.o1" to "全齒技術（法式）與前齒技術（德式）",
    "q.l5#7.o2" to "跳步技術與滑降技術",
    "q.l5#7.o3" to "上升技術與下降技術",
    "q.l5#7.e" to "全齒技術讓除前齒外的所有直立齒咬合冰面；前齒技術則把前齒垂直踢入冰面。複雜地形往往是兩者的混合使用——這也是為什麼先要把這兩種練紮實，再談混合式。",
    "q.l5#8.p" to "使用全齒（法式）技術時，主要的受力部位是？",
    "q.l5#8.o0" to "小腿",
    "q.l5#8.o1" to "大腿",
    "q.l5#8.o2" to "前臂",
    "q.l5#8.o3" to "腰背",
    "q.l5#8.e" to "因為腳掌保持平貼，力量主要由大腿與全身承擔，所以非常省力、可以長時間維持。前齒技術則相反，受力集中在兩三個前齒上，全靠小腿持續發力——兩條技術路線的體力賬完全不同。",
    "q.l5#9.p" to "全齒（法式）技術特別適用於什麼坡度的冰坡？",
    "q.l5#9.o0" to "0°～30°",
    "q.l5#9.o1" to "30°～50°",
    "q.l5#9.o2" to "50°～70°",
    "q.l5#9.o3" to "70° 以上",
    "q.l5#9.e" to "教材明確給出 0°～30° 這一區間。坡度再陡，腳掌就無法保持平貼，必須轉為前齒技術。記住每種技術適用的坡度範圍，其實就是在預判什麼時候該換技術。",
    // ---------- q.l6 ----------
    "q.l6#0.p" to "自我制動時雙腳應該怎麼放？",
    "q.l6#0.o0" to "雙腳用力蹬雪面剎車",
    "q.l6#0.o1" to "抬離雪面、腳尖朝上，把全部重量壓在冰鎬上",
    "q.l6#0.o2" to "腳尖插入雪中固定",
    "q.l6#0.o3" to "雙腳併攏平放雪面",
    "q.l6#0.e" to "腳一接觸雪面就會分擔掉本該壓在冰鎬上的重量，制動效率立刻下降，還可能造成踝、膝損傷。正確做法是雙腳抬起，讓身體重量全部透過冰鎬的鎬尖作用在雪面上。",
    "q.l6#1.p" to "滑墜時你正頭朝下、腳朝上，第一件該做的事是？",
    "q.l6#1.o0" to "先想辦法抓住繩子",
    "q.l6#1.o1" to "立即翻身轉為俯臥、腳朝下的姿態，再建立制動",
    "q.l6#1.o2" to "繼續滑，等速度降下來",
    "q.l6#1.o3" to "先丟下揹包",
    "q.l6#1.e" to "頭朝下時冰鎬的鎬尖角度無法有效壓入雪面，且頭部朝下撞擊風險極高。必須先用腰腹發力翻身轉為俯臥制動態，再壓鎬制動。",
    "q.l6#2.p" to "學習自我制動最正確的方式是？",
    "q.l6#2.o0" to "看教學影片就夠了",
    "q.l6#2.o1" to "讀教材並記住要點即可",
    "q.l6#2.o2" to "在安全的軟雪坡上、有教練保護下反覆實地練習直到形成本能",
    "q.l6#2.o3" to "直接在真實陡坡上撞一次就學會了",
    "q.l6#2.e" to "自我制動是條件反射級技能，需要在可控環境下重複數百次才能形成穩定反應。必須在坡度緩、下方開闊、雪質柔軟且有教練保護的場地練習。",
    "q.l6#3.p" to "自我制動時最有效的用力方式是？",
    "q.l6#3.o0" to "用手臂猛力下壓",
    "q.l6#3.o1" to "用身體重量垂直下壓鎬尖",
    "q.l6#3.o2" to "用鎬柄橫切雪面",
    "q.l6#3.o3" to "用鎬尖快速劃過雪面",
    "q.l6#3.e" to "手臂力量在疲勞與恐慌中無法持續，只有靠體重下壓才能讓鎬尖越陷越深。這也是為什麼姿勢（俯臥、雙腳抬起）比蠻力更重要。",
    "q.l6#4.p" to "在硬雪或冰面上，自我制動的效果會怎樣？",
    "q.l6#4.o0" to "效果更好，一壓就停",
    "q.l6#4.o1" to "制動距離顯著變長，甚至可能完全失效",
    "q.l6#4.o2" to "與軟雪沒有任何區別",
    "q.l6#4.o3" to "會自動轉為滑降",
    "q.l6#4.e" to "鎬尖在硬雪與冰面上難以咬合。這就是為什麼不要在無保護的情況下走入硬雪陡坡——技術不能替代規避，理解技術的失效邊界同樣重要。",
    "q.l6#5.p" to "自我制動時，雙手的分工應該是？",
    "q.l6#5.o0" to "雙手都握住鎬柄",
    "q.l6#5.o1" to "雙手都壓住鎬頭",
    "q.l6#5.o2" to "一隻手壓住鎬頭靠近鎬尖處提供下壓，另一隻手握住鎬柄控制方向與穩定",
    "q.l6#5.o3" to "單手操作即可，另一隻手空出來",
    "q.l6#5.e" to "壓鎬頭的手負責把身體重量傳導到鎬尖，握鎬柄的手負責穩定與修正方向。分工明確，制動才能既有力又不跑偏。",
    "q.l6#6.p" to "【排序】把滑墜制動的動作按正確順序排列。",
    "q.l6#6.o0" to "抓穩冰鎬，以自我制動式握法把鎬頭壓在身下",
    "q.l6#6.o1" to "將身體調整為頭上腳下、面朝雪面的俯臥姿勢",
    "q.l6#6.o2" to "用身體重量把鎬尖壓入冰雪，雙腿分開、膝蓋頂住冰雪面",
    "q.l6#6.o3" to "翹起雙腳，防止冰爪插入雪面造成翻滾",
    "q.l6#6.e" to "順序裡最容易被忽略的是最後一步：翹起雙腳。腳一旦接觸雪面就會分掉本該壓在冰鎬上的體重，還可能讓冰爪突然咬住雪面導致身體翻滾——制動反而被打斷。",
    "q.l6#7.p" to "進行自我制動時，冰鎬的鏟頭（鎬頭橫口一側）應當靠近哪裡？",
    "q.l6#7.o0" to "膝蓋外側",
    "q.l6#7.o1" to "肩窩處",
    "q.l6#7.o2" to "髖部",
    "q.l6#7.o3" to "頭側遠處",
    "q.l6#7.e" to "冰鎬鏟頭靠近肩窩，意味著鎬身在身體中線附近、受力集中在軀幹正下方，下壓最有效。位置偏遠會讓受力分散、鎬尖容易跑偏，制動距離顯著變長。",
    "q.l6#8.p" to "【多選】滑墜制動能否成功，主要受哪些因素影響？",
    "q.l6#8.o0" to "冰雪面的坡度",
    "q.l6#8.o1" to "冰雪面的硬度",
    "q.l6#8.o2" to "滑墜者的姿勢",
    "q.l6#8.o3" to "反應速度",
    "q.l6#8.o4" to "裝備的品牌與價格",
    "q.l6#8.e" to "教材的說法很坦誠：除了反應速度，制動的成功與否還受坡度、硬度與姿勢影響——「有時最熟練的動作都不能實現制動」。承認這個邊界，才會明白為什麼不滑墜比學會制動更重要。",
    "q.l6#9.p" to "制動時雙腿與膝蓋的正確姿態是？",
    "q.l6#9.o0" to "雙腿併攏、膝蓋離地",
    "q.l6#9.o1" to "雙腿分開，膝蓋頂住冰雪面",
    "q.l6#9.o2" to "單腿伸直、另一腿屈起",
    "q.l6#9.o3" to "雙腿抬高離開雪面",
    "q.l6#9.e" to "雙腿分開能提供橫向穩定、避免身體翻滾，膝蓋頂住冰雪面則形成額外的支撐點，幫助把重心穩定在鎬上。注意區分：膝蓋可以輕觸，而雙腳（冰爪）要抬起來。",
    // ---------- q.l7 ----------
    "q.l7#0.p" to "行進中預防滑墜最有效的方法是？",
    "q.l7#0.o0" to "走得快一點",
    "q.l7#0.o1" to "用冰鎬做自我確保，每一步都有臨時支點",
    "q.l7#0.o2" to "把冰鎬收進揹包",
    "q.l7#0.o3" to "只用繩子保護即可",
    "q.l7#0.e" to "自我確保是行進中最直接的防線：握鎬的手隨步伐把鎬柄插入雪面，形成第三支點。滑墜絕大多數發生在這種支撐缺失的瞬間。",
    "q.l7#1.p" to "結組行進時隊友突然滑墜，你首先應該做什麼？",
    "q.l7#1.o0" to "立刻衝下去拉住他",
    "q.l7#1.o1" to "立即轉入自制動姿勢並收緊繩索，為對方提供保護",
    "q.l7#1.o2" to "先解開繩索以免被拖走",
    "q.l7#1.o3" to "大聲呼救等待別人來救",
    "q.l7#1.e" to "繩隊的保護原理是：你先穩住自己，繩子才會傳遞制動。衝下去拉人或解繩都會讓隊伍一起滑墜——這是冰川事故中最常見的連鎖失敗。",
    "q.l7#2.p" to "失穩的瞬間，第一動作應該是？",
    "q.l7#2.o0" to "先整理裝備",
    "q.l7#2.o1" to "大聲警示隊友，同時立即轉俯臥建立制動",
    "q.l7#2.o2" to "先估算坡度",
    "q.l7#2.o3" to "先看看下方有什麼",
    "q.l7#2.e" to "滑墜的前兩秒決定了整個結局。警示隊友是為了讓他們同步進入保護狀態，而自己立刻轉俯臥制動是止損的核心動作。",
    "q.l7#3.p" to "結組行進時，繩索應該保持什麼狀態？",
    "q.l7#3.o0" to "越松越好，方便活動",
    "q.l7#3.o1" to "適度張緊、避免大量下垂",
    "q.l7#3.o2" to "必須完全繃直",
    "q.l7#3.o3" to "隨意即可",
    "q.l7#3.e" to "繩索大量下垂意味著墜落者要先自由下墜一段距離才受力，衝擊力成倍增加，也容易造成繩索切割雪面。適度張緊能讓制動更早介入。",
    "q.l7#4.p" to "為什麼「不要滑墜」比「學會制動」更根本？",
    "q.l7#4.o0" to "因為制動技術沒有用",
    "q.l7#4.o1" to "因為制動在硬雪與陡坡上可能失效，避免失穩才是最可靠的保護",
    "q.l7#4.o2" to "因為制動太消耗體力",
    "q.l7#4.o3" to "因為教練不讓練",
    "q.l7#4.e" to "自我制動是必備技能，但它有明確的失效邊界。真正可靠的安全策略是：不在沒有保護的情況下進入會滑墜的地形。技能是最後一層防線，而不是第一層。",
    "q.l7#5.p" to "制動過程中，鎬尖在硬雪面上彈跳、抓不住，應該怎麼做？",
    "q.l7#5.o0" to "抬手重新用力劈入",
    "q.l7#5.o1" to "保持俯臥姿態，用身體重量持續下壓，讓鎬尖逐漸咬合",
    "q.l7#5.o2" to "改用鎬柄橫切雪面",
    "q.l7#5.o3" to "放棄制動，改為保護頭部",
    "q.l7#5.e" to "抬手會讓制動瞬間完全失效，也讓你失去已經建立的下壓姿態。正確做法是保持俯臥、持續下壓，讓鎬尖在滑行中逐漸加深咬合——制動是漸進過程，不是一次動作。",
    "q.l7#6.p" to "為什麼說「冰面上的制動非常困難」？",
    "q.l7#6.o0" to "因為冰面太冷",
    "q.l7#6.o1" to "因為鎬尖難以咬入冰面，因此透過冰坡時應架設固定繩而非依賴制動",
    "q.l7#6.o2" to "因為冰面摩擦力太大",
    "q.l7#6.o3" to "因為冰面容易碎",
    "q.l7#6.e" to "制動依賴鎬尖咬入，而冰面恰恰最難咬合。教材給出的對策是系統性的：透過有坡度的冰坡時架設固定路線繩或交替保護，一般不結組行進——用系統解決問題，而不是把希望寄託在個人技術上。",
    "q.l7#7.p" to "【排序】結組行進中隊友滑墜，正確的處置順序是？",
    "q.l7#7.o0" to "立即轉入制動姿勢、穩住自己",
    "q.l7#7.o1" to "收緊繩索，為墜落者提供製動",
    "q.l7#7.o2" to "建立獨立確保站（雪錐、冰鎬埋設等）",
    "q.l7#7.o3" to "把重量轉移到確保站，再實施救援",
    "q.l7#7.e" to "四步之間不能顛倒：先穩住自己才有能力做後面的動作；不建站就直接救援，等於把兩個人的重量都壓在你身上。現實中這幾步要在幾分鐘內完成，所以必須事前反覆演練。",
    "q.l7#8.p" to "制動成功、滑墜停止之後，緊接著應該做什麼？",
    "q.l7#8.o0" to "立刻站起來繼續走",
    "q.l7#8.o1" to "保持制動，逐步建立保護並把重量轉移到確保站上",
    "q.l7#8.o2" to "先解開繩索",
    "q.l7#8.o3" to "先檢查裝備是否損壞",
    "q.l7#8.e" to "滑墜停止不等於安全——你仍處於沒有保護的姿態，一旦再次滑動很難重新制動。正確做法是在保持制動的狀態下先建立可靠保護，把自己「解放」出來，再去處理傷情與路線。",
    "q.l7#9.p" to "【多選】下列哪些屬於預防滑墜的有效做法？",
    "q.l7#9.o0" to "行進中持續用冰鎬做自我確保",
    "q.l7#9.o1" to "在硬雪或冰坡上架設固定路線繩",
    "q.l7#9.o2" to "保持可持續的勻速，避免突然發力導致失衡",
    "q.l7#9.o3" to "按隊伍最慢者的節奏行進，避免隊伍拉開",
    "q.l7#9.o4" to "加快行進速度，縮短暴露時間",
    "q.l7#9.e" to "這四項分別從個人技術、系統保護、節奏控制與隊伍協同四個層面降低滑墜機率。滑墜預防從來不是單一動作，而是把這幾層同時做到位。",
    // ---------- q.l8 ----------
    "q.l8#0.p" to "為什麼下撤階段事故更為高發？",
    "q.l8#0.o0" to "因為下坡路更難走",
    "q.l8#0.o1" to "因為體能消耗導致注意力與動作質量下降",
    "q.l8#0.o2" to "因為下山時天氣總是更差",
    "q.l8#0.o3" to "因為裝備會失效",
    "q.l8#0.e" to "登頂後目標達成，警覺性自然下降，而身體已接近透支。大量登山事故發生在下撤途中——這也是「登頂只是行程的一半」這句話的由來。",
    "q.l8#1.p" to "什麼條件下才允許使用控制式滑降（glissade）？",
    "q.l8#1.o0" to "只要坡度夠陡就可以",
    "q.l8#1.o1" to "無裂縫、無落石風險、下方開闊，且隨時能轉入自我制動",
    "q.l8#1.o2" to "任何雪坡都可以",
    "q.l8#1.o3" to "只要隊友同意就可以",
    "q.l8#1.e" to "滑降是不可逆的加速行為，一旦開始很難停下。必須排除冰裂縫、落石與下方人員，並保證隨時可以翻身制動，否則應老老實實下攀。",
    "q.l8#2.p" to "技術地形下降時的首選方式是？",
    "q.l8#2.o0" to "面朝坡內下攀，保持三點支撐",
    "q.l8#2.o1" to "面朝坡外快速跑下",
    "q.l8#2.o2" to "直接滑降",
    "q.l8#2.o3" to "坐著往下滑",
    "q.l8#2.e" to "面朝坡內下攀讓你能看見腳下的落腳點，重心靠近坡面更穩定，且雙手可保持支撐。面朝坡外下攀會讓你看不見落腳點，是常見錯誤。",
    "q.l8#3.p" to "下撤時最容易出現的危險錯誤是？",
    "q.l8#3.o0" to "面朝坡內、三點支撐下攀",
    "q.l8#3.o1" to "重心前傾、面朝坡外下攀",
    "q.l8#3.o2" to "保持穩定節奏",
    "q.l8#3.o3" to "使用冰鎬做自我確保",
    "q.l8#3.e" to "面朝坡外下攀時你看不見落腳點，重心前傾會進一步加劇失穩。加上疲勞導致腿部控制力下降，這正是下撤階段事故高發的真正原因。",
    "q.l8#4.p" to "滑降開始前必須完成的一件事是？",
    "q.l8#4.o0" to "把冰鎬收進揹包",
    "q.l8#4.o1" to "確認下方無人、路線無裂縫與落石，並保持冰鎬隨時可制動",
    "q.l8#4.o2" to "繫緊揹包肩帶",
    "q.l8#4.o3" to "通知家人行程",
    "q.l8#4.e" to "滑降是不可逆的加速行為。開始前必須排除下方人員、冰裂縫與落石，並保持冰鎬就位——否則一旦遇到意外，你將沒有任何手段減速。",
    "q.l8#5.p" to "長距離下撤時，如何管理隊伍疲勞？",
    "q.l8#5.o0" to "一口氣走到底，減少停留",
    "q.l8#5.o1" to "按時短暫停留、補充水分與能量，並重新評估隊伍狀態",
    "q.l8#5.o2" to "加快速度以縮短暴露時間",
    "q.l8#5.o3" to "只在有人受傷時才停留",
    "q.l8#5.e" to "下撤是事故高發段，疲勞是主要誘因。規律而短暫的停留既能補充能量，也讓你重新觀察天氣、路線與隊友狀態——這些判斷在連續行軍中最容易被忽略。",
    "q.l8#6.p" to "【排序】把下降前的準備步驟按合理順序排列。",
    "q.l8#6.o0" to "確認下降路線與落點，排除下方人員",
    "q.l8#6.o1" to "檢查繩索、保護器、主鎖與扁帶是否齊備",
    "q.l8#6.o2" to "建立可靠的保護點（或確認已有確保站）",
    "q.l8#6.o3" to "整理繩索，避免打結與纏繞後開始下降",
    "q.l8#6.e" to "下降是「把生命交給一個點」的操作，所以順序上要先確認去哪、再確認裝備、然後才建立依賴。整理繩索這一步同樣關鍵——繩索打結或纏繞會導致無法下降，被迫在繩上長時間懸掛。",
    "q.l8#7.p" to "下降時選擇繩降還是下攀，主要依據是？",
    "q.l8#7.o0" to "下降距離越短越應該繩降",
    "q.l8#7.o1" to "地形難度、可用保護點與隊伍能力",
    "q.l8#7.o2" to "天氣狀況",
    "q.l8#7.o3" to "裝備新舊程度",
    "q.l8#7.e" to "繩降快但依賴保護點與操作，下攀慢但更自主。技術地形、保護點是否可靠、隊伍是否熟練——三者共同決定選哪種。要注意的是，繩降事故率高，因為操作失誤的容錯空間很小。",
    "q.l8#8.p" to "繩降所需的常用技術裝備包括？",
    "q.l8#8.o0" to "主鎖 1 把、扁帶 1 根",
    "q.l8#8.o1" to "主鎖若干把、長扁帶或菊繩、抓結輔繩等",
    "q.l8#8.o2" to "只需要繩索",
    "q.l8#8.o3" to "只需要保護器",
    "q.l8#8.e" to "教材列出的下降裝備包含主鎖多把、長扁帶或菊繩，以及抓結輔繩等。原因在於下降往往需要「邊下降邊回收保護點」，同時還要留有備份——裝備不足會迫使你在高處臨時湊合，那正是事故的溫床。",
    "q.l8#9.p" to "【多選】下降階段的主要風險點包括？",
    "q.l8#9.o0" to "保護點失效",
    "q.l8#9.o1" to "繩尾未打結導致脫繩墜落",
    "q.l8#9.o2" to "繩索被卡住或纏繞",
    "q.l8#9.o3" to "落石與下方人員",
    "q.l8#9.o4" to "因為下坡省力，下降階段的風險總體低於上升",
    "q.l8#9.e" to "這四項是下降事故的常見原因。其中「繩尾未打結」最容易被忽略——如果繩長不夠而繩尾又沒有打結，人會在不知不覺中滑出繩端，直接墜落。這類錯誤在疲勞的下撤階段尤其常見。",
    // ---------- q.l9 ----------
    "q.l9#0.p" to "用來把繩子連線到安全帶、且最常用於冰川路線的結是？",
    "q.l9#0.o0" to "回穿 8 字結",
    "q.l9#0.o1" to "平結",
    "q.l9#0.o2" to "單結",
    "q.l9#0.o3" to "稱人結",
    "q.l9#0.e" to "回穿 8 字結強度高、結構直觀、便於他人檢查，受力後仍相對容易解開。平結在受力後可能滑脫或死結化，絕不能用於保護性連線。",
    "q.l9#1.p" to "需要單手快速調節長度、把繩子固定到主鎖上時，用哪個結？",
    "q.l9#1.o0" to "雙漁人結",
    "q.l9#1.o1" to "克氏結",
    "q.l9#1.o2" to "蝴蝶結",
    "q.l9#1.o3" to "水結",
    "q.l9#1.e" to "克氏結可以在主鎖上單手推拉調節長度，是確保站自我固定（self-anchor）的標準做法。雙漁人結用於連線兩繩，蝴蝶結用於繩中固定點。",
    "q.l9#2.p" to "抓結（普魯士結一類摩擦結）的主要特性是？",
    "q.l9#2.o0" to "受力時抓緊繩索，不受力時可沿繩推動",
    "q.l9#2.o1" to "可以永久替代主繩",
    "q.l9#2.o2" to "只能用於打結裝飾",
    "q.l9#2.o3" to "受力後會自行解開",
    "q.l9#2.e" to "摩擦結的單向抓握特性，使它可以用於上升、備份與機械優勢系統。也正因為它可靠與否取決於繩徑搭配與纏繞圈數，所以必須實地練習驗證。",
    "q.l9#3.p" to "繩結完成後，尾端至少應留多長？",
    "q.l9#3.o0" to "1 公分左右即可",
    "q.l9#3.o1" to "不少於 10 倍繩徑",
    "q.l9#3.o2" to "不需要留尾端",
    "q.l9#3.o3" to "越長越好，至少 1 公尺",
    "q.l9#3.e" to "足夠的尾端是防止繩結在受力或反覆晃動中滑脫的基本保障。同時要養成與同伴互相檢查的習慣——繩結是保護系統中唯一由手工完成、沒有出廠檢驗的環節。",
    "q.l9#4.p" to "用於連線兩根繩子或製作抓結環的結是？",
    "q.l9#4.o0" to "平結",
    "q.l9#4.o1" to "雙漁人結",
    "q.l9#4.o2" to "單結",
    "q.l9#4.o3" to "稱人結",
    "q.l9#4.e" to "雙漁人結極其穩定、不易鬆脫，但受力後較難解開，因此適合連線繩索與製作閉合輔繩環。平結在受力後可能滑脫，絕不能用於承重連線。",
    "q.l9#5.p" to "為什麼抓結（摩擦結）的可靠性取決於繩徑搭配？",
    "q.l9#5.o0" to "繩徑搭配無關緊要",
    "q.l9#5.o1" to "輔繩相對主繩過細時接觸與擠壓力不足，會抓不住主繩",
    "q.l9#5.o2" to "輔繩越細越好抓",
    "q.l9#5.o3" to "輔繩越粗越好抓",
    "q.l9#5.e" to "摩擦結靠輔繩對主繩的擠壓產生抓握力。輔繩過細則接觸面積與擠壓力都不足，過粗則難以纏繞緊密。因此每次使用前都必須確認搭配，並在安全位置實際測試過再依賴它。",
    "q.l9#6.p" to "蝴蝶結（alpine butterfly）的主要用途是？",
    "q.l9#6.o0" to "連線兩根繩子",
    "q.l9#6.o1" to "在繩中段製造一個可多向受力的固定環",
    "q.l9#6.o2" to "替代 8 字結連線安全帶",
    "q.l9#6.o3" to "製作抓結環",
    "q.l9#6.e" to "蝴蝶結在繩中段形成一個環，且兩個方向受力都能承載，因此常用於結組、冰川行進與救援系統。它也常被用來在繩段之間打結，增加繩索陷入雪面的摩擦。",
    "q.l9#7.p" to "【配對】把繩結與它的主要用途對應起來。",
    "q.l9#7.l0" to "“8”字結",
    "q.l9#7.l1" to "雙漁人結",
    "q.l9#7.l2" to "抓結（普魯士結）",
    "q.l9#7.l3" to "布林結",
    "q.l9#7.r0" to "連線固定點、連線安全帶最常用",
    "q.l9#7.r1" to "連線兩根繩子，或製作閉合的輔繩環",
    "q.l9#7.r2" to "摩擦結，受力時抓緊、不受力時可推動",
    "q.l9#7.r3" to "連線固定點，泊船時也常用",
    "q.l9#7.e" to "這四個結覆蓋了冰川行進與基礎保護的絕大多數場景。教材裡把它們按「連線固定點」「連線繩子」「摩擦結」分類——按功能記，比按形狀記牢得多。",
    "q.l9#8.p" to "關於繩結與繩子強度的關係，正確的認識是？",
    "q.l9#8.o0" to "打結不會影響繩子強度",
    "q.l9#8.o1" to "任何繩結都會降低繩子在該處的強度，不同繩結的降幅不同",
    "q.l9#8.o2" to "打結會讓繩子變強",
    "q.l9#8.o3" to "只要繩結打得好就不影響強度",
    "q.l9#8.e" to "繩子在打結處彎折，受力時纖維受力不均，強度必然下降——區別只在於降幅大小。這也是教材專門列出「繩結強度變化對照表」的原因：選擇繩結時，除了看功能好不好用，也要考慮它對強度的損耗。",
    "q.l9#9.p" to "教材用一句話概括繩結的意義：「繩結賦予了繩子（ ）。」",
    "q.l9#9.a0" to "生命力",
    "q.l9#9.a1" to "生命",
    "q.l9#9.e" to "原文是「繩結賦予了繩子生命力」。這句話點出了繩結的本質——繩子本身只是一根線，只有透過繩結與保護裝備、固定點及其他繩子建立連線，它才成為一個能承載生命的系統。",
    // ---------- q.l10 ----------
    "q.l10#0.p" to "冰川結組最理想的隊伍人數是？",
    "q.l10#0.o0" to "2 人",
    "q.l10#0.o1" to "3 人",
    "q.l10#0.o2" to "6 人以上",
    "q.l10#0.o3" to "單人結組",
    "q.l10#0.e" to "3 人繩隊在一人墜入裂縫時有足夠的人力建立確保站並操作救援系統。2 人隊一旦有人墜落，剩下的人既要制動又要建站救人，餘量極小。",
    "q.l10#1.p" to "冰川結組的常見間距是？",
    "q.l10#1.o0" to "2–3 公尺",
    "q.l10#1.o1" to "8–12 公尺",
    "q.l10#1.o2" to "30 公尺以上",
    "q.l10#1.o3" to "越短越好",
    "q.l10#1.e" to "8–12 公尺既能保證墜落時隊友有足夠的反應與制動距離，又便於交流與協作。間距過短會讓墜落的衝擊幾乎無法緩衝。",
    "q.l10#2.p" to "結組能真正提供保護的前提是？",
    "q.l10#2.o0" to "只要繫上繩子就自動安全",
    "q.l10#2.o1" to "隊友能夠有效制動並建立起保護",
    "q.l10#2.o2" to "繩子足夠長",
    "q.l10#2.o3" to "人數足夠多",
    "q.l10#2.e" to "繩隊的安全來自「制動 + 固定」這兩個動作的可靠執行。缺少制動能力或確保站技術的繩隊，只是把人綁在一起一起掉下去而已。",
    "q.l10#3.p" to "冰川結組時在繩段之間打結（如蝴蝶結），作用是？",
    "q.l10#3.o0" to "純粹裝飾",
    "q.l10#3.o1" to "增加繩索陷入雪面的摩擦，抑制墜落者繼續下墜",
    "q.l10#3.o2" to "方便識別隊友",
    "q.l10#3.o3" to "減輕繩索重量",
    "q.l10#3.e" to "繩結在雪面上形成額外的阻力點，能顯著降低墜落者的下墜深度，也為上方隊友爭取建立保護的時間。這是很廉價但很有效的一道緩衝。",
    "q.l10#4.p" to "冰川行進時，救援器材應該放在哪裡？",
    "q.l10#4.o0" to "揹包最深處",
    "q.l10#4.o1" to "伸手可及的位置，隨時可取用",
    "q.l10#4.o2" to "留在營地帳篷裡",
    "q.l10#4.o3" to "交給隊友保管",
    "q.l10#4.e" to "冰裂縫救援的黃金窗口只有幾分鐘。抓結繩套、主鎖、雪錐如果壓在揹包底部，等你翻出來時，隊友可能已經失溫或繩索已被雪簷切斷。",
    "q.l10#5.p" to "2 人結組相比 3 人結組，最主要的風險是什麼？",
    "q.l10#5.o0" to "行進速度更慢",
    "q.l10#5.o1" to "一人墜落時，剩餘人力難以同時兼顧制動與救援操作",
    "q.l10#5.o2" to "繩索長度不夠",
    "q.l10#5.o3" to "需要攜帶更多裝備",
    "q.l10#5.e" to "2 人隊一旦有人墜入裂縫，剩下的人既要維持制動、又要建立確保站並操作拉昇系統，幾乎沒有餘量。若必須 2 人結組行進，需要更保守的路線選擇與更充分的預案。",
    "q.l10#6.p" to "冰川結組行進中，為什麼不宜隨時解開繩索？",
    "q.l10#6.o0" to "因為解開和重新系上很麻煩",
    "q.l10#6.o1" to "裂縫區的風險是連續的，解開繩索的瞬間就失去了保護",
    "q.l10#6.o2" to "因為繩子容易丟失",
    "q.l10#6.o3" to "因為會被隊友責備",
    "q.l10#6.e" to "冰川上的風險分佈並不均勻，也難以預判，中途解繩往往發生在「覺得這段沒事」的誤判之下。若確有必要解繩，應先停止行進、確認地形與雪況，再統一行動。",
    "q.l10#7.p" to "【配對】把國際通用的攀登口令與含義對應起來。",
    "q.l10#7.l0" to "On belay",
    "q.l10#7.l1" to "Climbing",
    "q.l10#7.l2" to "Falling",
    "q.l10#7.l3" to "Off belay",
    "q.l10#7.r0" to "保護就緒，可以開始",
    "q.l10#7.r1" to "開始攀登",
    "q.l10#7.r2" to "我墜落了（警示）",
    "q.l10#7.r3" to "解除保護，保護結束",
    "q.l10#7.e" to "口令系統的價值在於「不需要解釋」。高海拔風聲大、距離遠，簡短且雙方含義一致的詞能避免歧義；而保護環節裡最危險的就是「以為對方知道」。教材專門列出國際通用口令，就是因為它們是跨隊伍、跨語言的最低共識。",
    "q.l10#8.p" to "保護員所需的基本技術裝備是？",
    "q.l10#8.o0" to "安全帶 1 根、主鎖 1 把、保護器 1 副、手套 1 副、頭盔 1 頂",
    "q.l10#8.o1" to "只需要保護器與主鎖",
    "q.l10#8.o2" to "頭盔與雪鏡",
    "q.l10#8.o3" to "安全帶與繩索",
    "q.l10#8.e" to "這份清單看似簡單，但每一項缺失都會造成具體後果：手套缺了會磨傷手並影響控繩，頭盔缺了則無法應對落石。保護員是「給別人兜底的人」，所以自己的裝備必須先說齊。",
    "q.l10#9.p" to "為什麼攀登開始前要進行「互相檢查」？",
    "q.l10#9.o0" to "出於隊伍紀律要求",
    "q.l10#9.o1" to "因為安全帶、繩結與保護器的誤操作往往自己看不出來",
    "q.l10#9.o2" to "為了記錄進度",
    "q.l10#9.o3" to "為了熱身",
    "q.l10#9.e" to "自己檢查自己往往只能看到「我以為打好的樣子」，而同伴能從背後、從側面看到你視線不及的地方。教材把「攀登前互相檢查」列為保護溝通的第一個環節——它是用他人視角補自己的盲區。",
    // ---------- q.l11 ----------
    "q.l11#0.p" to "SRENE 原則中的 R 代表什麼？",
    "q.l11#0.o0" to "Rapid 快速",
    "q.l11#0.o1" to "Redundant 冗餘",
    "q.l11#0.o2" to "Rope 繩索",
    "q.l11#0.o3" to "Rigid 剛性",
    "q.l11#0.e" to "Redundant（冗餘）要求系統中有多個獨立保護點，任一點失效時其餘點仍能承載。它是確保站安全最核心的一條。",
    "q.l11#1.p" to "「No Extension」這條原則的含義是？",
    "q.l11#1.o0" to "繩子越長越好",
    "q.l11#1.o1" to "某一點失效時系統不應產生衝擊性延展",
    "q.l11#1.o2" to "確保站不應建在低處",
    "q.l11#1.o3" to "不需要額外備用器材",
    "q.l11#1.e" to "如果保護點之間留有松餘，某點崩脫時其他點會承受突然的衝擊載荷（衝擊力遠大於靜載）。No Extension 要求預先均衡收緊，避免這種衝擊。",
    "q.l11#2.p" to "確保站設計最核心的思想是？",
    "q.l11#2.o0" to "儘量節省器材",
    "q.l11#2.o1" to "單點失效不導致整個系統崩潰",
    "q.l11#2.o2" to "建得越高越好",
    "q.l11#2.o3" to "只用最粗的繩子",
    "q.l11#2.e" to "岩雪保護點的可靠性無法做到絕對確定，因此係統的設計目標是容錯：讓任何單一失效都不致命，為攀登者爭取反應與備份時間。",
    "q.l11#3.p" to "EARNEST 相比 SRENE 補充的兩個維度是？",
    "q.l11#3.o0" to "Efficient（高效）與 Timely（快速）",
    "q.l11#3.o1" to "Easy（簡單）與 Tight（緊繃）",
    "q.l11#3.o2" to "Equal（相等）與 Nice（美觀）",
    "q.l11#3.o3" to "Empty（空）與 True（真）",
    "q.l11#3.e" to "確保站不只要安全，還要搭得快、操作不繁瑣——因為搭建過程本身就是暴露在風險中的時間。這正是 EARNEST 比 SRENE 更貼近真實場景的地方。",
    "q.l11#4.p" to "雪地保護點的可靠性主要取決於？",
    "q.l11#4.o0" to "器材品牌",
    "q.l11#4.o1" to "雪質與埋設質量",
    "q.l11#4.o2" to "繩索顏色",
    "q.l11#4.o3" to "海拔高度",
    "q.l11#4.e" to "同樣的雪錐或死掛，在深雪、溼雪與雪橋邊緣的承載能力差異極大。雪地保護點必須現場判斷雪層結構，而不能照搬固定流程。",
    "q.l11#5.p" to "確保站為什麼要強調「均衡受力」？",
    "q.l11#5.o0" to "為了讓確保站更整齊",
    "q.l11#5.o1" to "讓負荷按設計分散到各保護點，避免單點過載",
    "q.l11#5.o2" to "為了節省器材",
    "q.l11#5.o3" to "為了便於拆除",
    "q.l11#5.e" to "均衡受力意味著每個點承擔接近設計值的負荷，而不是讓某一點承擔全部。若某點先達到極限而失效，負荷會突然轉移到其餘點，容易引發連鎖失效。",
    "q.l11#6.p" to "下列哪種做法違反了確保站的「冗餘」原則？",
    "q.l11#6.o0" to "使用強度不同的器材",
    "q.l11#6.o1" to "兩個保護點實際上依賴同一條岩縫或同一塊岩體",
    "q.l11#6.o2" to "保護點之間用扁帶連線",
    "q.l11#6.o3" to "設定三個保護點",
    "q.l11#6.e" to "冗餘要求各個保護點是獨立失效的。如果兩點共用同一條岩縫，岩縫崩開時兩點會同時失效——形式上像「兩點」，實際只有一點。這是非常常見、也非常致命的假冗餘。",
    "q.l11#7.p" to "【配對】把確保站評估原則的縮寫與其含義對應起來。",
    "q.l11#7.l0" to "S（Solid）",
    "q.l11#7.l1" to "R（Redundant）",
    "q.l11#7.l2" to "E（Equalized）",
    "q.l11#7.l3" to "No Extension",
    "q.l11#7.r0" to "牢固：每個點的強度足夠承載預期負荷",
    "q.l11#7.r1" to "冗餘：多個彼此獨立的保護點",
    "q.l11#7.r2" to "均衡：負荷合理分配到各點",
    "q.l11#7.r3" to "不延展：某點失效時不產生衝擊性延展",
    "q.l11#7.e" to "這四項構成確保站評估的基本框架，縮寫是 SRENE。值得記住的是順序：先看單點是否牢固，再看系統是否有冗餘——如果連單點都不可靠，討論冗餘沒有意義。",
    "q.l11#8.p" to "從受力資料出發，扁帶夾角應儘量控制在什麼範圍內？",
    "q.l11#8.o0" to "60° 以內",
    "q.l11#8.o1" to "90° 以內",
    "q.l11#8.o2" to "120° 以內",
    "q.l11#8.o3" to "夾角不影響受力",
    "q.l11#8.e" to "夾角 0° 時每點約承擔 50%，60° 約 58%，90° 約 71%——夾角越大，同一個人的重量在每個點上造成的負荷就越大。「控制在 60° 以內」這條經驗規則，正是從這組資料來的。",
    "q.l11#9.p" to "為什麼確保站的「效率」與「及時性」也被納入評估？",
    "q.l11#9.o0" to "為了讓操作更好看",
    "q.l11#9.o1" to "因為搭建確保站的過程本身就是暴露在風險中的時間",
    "q.l11#9.o2" to "為了節省器材",
    "q.l11#9.o3" to "為了便於教學",
    "q.l11#9.e" to "搭確保站時，你往往處於無保護或保護不足的狀態。這段暴露時間越短，風險越低——所以「搭得快、操作不繁瑣」不是偷懶，而是安全指標的一部分。",
    "q.l11#10.p" to "【多選】一個合格的確保站應具備哪些特徵？",
    "q.l11#10.o0" to "每個保護點自身牢固",
    "q.l11#10.o1" to "各保護點彼此獨立失效",
    "q.l11#10.o2" to "負荷在各點之間合理分配",
    "q.l11#10.o3" to "系統預留延展量以吸收衝擊",
    "q.l11#10.e" to "前三項都是要求，最後一項恰恰相反——確保站要求「不延展」，而不是預留延展量。預留松餘會讓某點崩脫時其餘點承受衝擊載荷，衝擊力遠大於靜載。",
    "q.l11#11.p" to "如果現場條件所限、只能用單一保護點，正確的做法是？",
    "q.l11#11.o0" to "放棄攀登，原路返回",
    "q.l11#11.o1" to "把它儘可能做得可靠，並儘量減少系統在它上面的暴露時間",
    "q.l11#11.o2" to "再隨便加一個點湊成兩個",
    "q.l11#11.o3" to "把繩索直接系在安全帶上",
    "q.l11#11.e" to "現實中確實存在只能單點的情況（例如只有一個可靠冰錐）。此時的態度應當是「承認它沒有容錯」，因此把點做到最可靠、把人儘快移過去，而不是隨便加一個無效的點來製造虛假的安全感。",
    // ---------- q.l12 ----------
    "q.l12#0.p" to "隊友墜入冰裂縫後，第一步應該做什麼？",
    "q.l12#0.o0" to "立刻跳下去救他",
    "q.l12#0.o1" to "立即自制動並建立確保站，把重量轉移到確保站上",
    "q.l12#0.o2" to "先打電話求救",
    "q.l12#0.o3" to "先把繩子割斷",
    "q.l12#0.e" to "墜落者的體重此刻全部壓在你身上。必須先用自制動穩住自己，再建立獨立確保站並把負荷轉移過去，之後才有餘力操作救援系統。跳下去或割繩都會讓情況立刻惡化。",
    "q.l12#1.p" to "救援拉昇最常用的機械優勢系統是？",
    "q.l12#1.o0" to "1:1 直接拉",
    "q.l12#1.o1" to "3:1 Z 系統（Z-pulley）",
    "q.l12#1.o2" to "10:1 系統",
    "q.l12#1.o3" to "不需要機械優勢",
    "q.l12#1.e" to "3:1 的 Z 系統用抓結加一個滑輪就能獲得三倍機械優勢，結構簡單、搭建快、器材需求少，是冰川救援的標準選擇。",
    "q.l12#2.p" to "為什麼雪橋特別危險？",
    "q.l12#2.o0" to "因為它總是發出響聲",
    "q.l12#2.o1" to "被新雪覆蓋後外觀與普通雪面無異，難以識別",
    "q.l12#2.o2" to "因為它只在夜間出現",
    "q.l12#2.o3" to "因為它一定很薄",
    "q.l12#2.e" to "雪橋是最隱蔽的冰川風險：表面平整厚實，實際下方是空腔。判斷雪橋可靠性需要觀察裂縫走向、雪層結構與季節條件，這也是必須結組的原因。",
    "q.l12#3.p" to "透過冰裂縫區時，繩索的狀態應該是？",
    "q.l12#3.o0" to "完全松垂以便活動",
    "q.l12#3.o1" to "適度張緊、避免大量下垂",
    "q.l12#3.o2" to "繃得越緊越好",
    "q.l12#3.o3" to "不需要結組",
    "q.l12#3.e" to "繩索下垂會讓墜落者先自由下墜再突然受力，衝擊力成倍增加。適度張緊能讓制動更早介入，也減少繩索切入裂縫邊緣雪簷的風險。",
    "q.l12#4.p" to "透過雪橋時最穩妥的做法是？",
    "q.l12#4.o0" to "快速單人跑過",
    "q.l12#4.o1" to "結組行進、保持繩索張緊，一人透過時其餘人做好制動準備",
    "q.l12#4.o2" to "繞開所有雪橋",
    "q.l12#4.o3" to "用力跺腳測試後再透過",
    "q.l12#4.e" to "雪橋的可靠性無法靠外觀判斷。結組加上隨時準備制動，是把「不確定」轉化為「可控風險」的方式。用力跺腳測試反而可能直接壓塌雪橋。",
    "q.l12#5.p" to "隊員被繩索吊在裂縫中時，最需要防範的是什麼？",
    "q.l12#5.o0" to "隊員在裂縫中睡著",
    "q.l12#5.o1" to "受力繩索持續切割裂縫邊緣的雪簷，可能突然斷裂",
    "q.l12#5.o2" to "裝備從身上掉落",
    "q.l12#5.o3" to "天氣突然變化",
    "q.l12#5.e" to "受力繩索會在雪簷上反覆切割，形成越來越深的槽口。這是救援時間壓力的主要來源——必須在雪簷被切穿之前完成拉昇，或先把負荷轉移到可靠的確保站上。",
    "q.l12#6.p" to "用抓結搭建 Z 系統時，為什麼必須設定備份？",
    "q.l12#6.o0" to "為了讓系統看起來更完整",
    "q.l12#6.o1" to "主抓結一旦失效會瞬間失去機械優勢，墜落者將再次下墜",
    "q.l12#6.o2" to "為了增加摩擦力",
    "q.l12#6.o3" to "為了節省繩索",
    "q.l12#6.e" to "抓結的抓握依賴摩擦，可能因結冰、泥汙或繩索磨損而失效。備份抓結能在主系統失效時接住負荷，避免二次墜落帶來額外的傷害與時間損失。",
    "q.l12#7.p" to "【排序】把冰裂縫救援的標準流程按順序排列。",
    "q.l12#7.o0" to "立即自制動，穩住自己",
    "q.l12#7.o1" to "建立獨立確保站",
    "q.l12#7.o2" to "把重量從身體轉移到確保站上",
    "q.l12#7.o3" to "用 3:1 機械優勢系統拉昇",
    "q.l12#7.e" to "四步不能顛倒。其中第三步最容易被跳過：不把重量轉移出去，你就必須一直用身體拉住隊友，根本騰不出手作業系統——這是救援失敗最常見的原因。",
    "q.l12#8.p" to "墜入裂縫的人自己應該做什麼？",
    "q.l12#8.o0" to "用力晃動繩索引起注意",
    "q.l12#8.o1" to "保持冷靜，嘗試用抓結自我上升，並避免繩索繼續切入裂縫邊緣的雪簷",
    "q.l12#8.o2" to "立刻解開繩索",
    "q.l12#8.o3" to "儘量往下爬尋找出口",
    "q.l12#8.e" to "墜落者的配合能顯著降低救援難度。晃動繩索會加劇雪簷切割，解繩則直接失去連線。正確做法是穩住自己、減輕繩索的切割、並在有條件時用抓結分擔一部分體重。",
    "q.l12#9.p" to "【多選】冰川結組時應該隨身攜帶、伸手可及的救援器材包括？",
    "q.l12#9.o0" to "抓結輔繩（普式抓結繩套）",
    "q.l12#9.o1" to "主鎖與滑輪",
    "q.l12#9.o2" to "雪錐或冰錐",
    "q.l12#9.o3" to "扁帶",
    "q.l12#9.o4" to "登山杖",
    "q.l12#9.e" to "這四類共同構成應變系統：抓結提供單向抓握，主鎖與滑輪組成機械優勢，雪錐/冰錐用於建立確保站，扁帶用於連線與延長。關鍵是「伸手可及」——壓在揹包底部的器材等於沒有。",
    "q.l12#10.p" to "為什麼必須先把重量轉移到確保站，才能開始拉昇？",
    "q.l12#10.o0" to "為了讓繩索受力更均勻",
    "q.l12#10.o1" to "因為不轉移重量，你的雙手就被佔用在維持制動上，無法作業系統",
    "q.l12#10.o2" to "為了節省體力",
    "q.l12#10.o3" to "為了保護繩索",
